import React, { useState, useEffect, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { 
  Cloud, 
  Sun, 
  CloudRain, 
  CloudLightning, 
  Wind, 
  X, 
  Thermometer, 
  MapPin,
  Clock,
  Calendar,
  CloudSnow,
  CloudDrizzle,
  Loader2
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

// Initialize Gemini API
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

interface WeatherData {
  location: string;
  currentTemp: number;
  condition: string;
  hourly: {
    time: string;
    temp: number;
    icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle';
  }[];
  daily: {
    day: string;
    low: number;
    high: number;
    condition: string;
    icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle';
  }[];
}

const WeatherIcon = ({ type, className }: { type: string, className?: string }) => {
  switch (type) {
    case 'sun': return <Sun className={className} />;
    case 'cloud': return <Cloud className={className} />;
    case 'rain': return <CloudRain className={className} />;
    case 'storm': return <CloudLightning className={className} />;
    case 'snow': return <CloudSnow className={className} />;
    case 'drizzle': return <CloudDrizzle className={className} />;
    default: return <Cloud className={className} />;
  }
};

const App = () => {
  const [isOverlayOpen, setIsOverlayOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const timerRef = useRef<number | null>(null);

  const fetchWeather = async () => {
    setLoading(true);
    setError(null);
    setIsOverlayOpen(true);

    // Reset auto-close timer whenever opened
    if (timerRef.current) window.clearTimeout(timerRef.current);
    timerRef.current = window.setTimeout(() => {
      setIsOverlayOpen(false);
    }, 180000); // 3 minutes

    try {
      let locationQuery = "London, UK"; // Default

      // Try to get actual location
      try {
        const position = await new Promise<GeolocationPosition>((resolve, reject) => {
          navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 5000 });
        });
        locationQuery = `lat: ${position.coords.latitude}, lon: ${position.coords.longitude}`;
      } catch (e) {
        console.warn("Geolocation failed, using default.");
      }

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Generate a realistic 24-hour and 7-day weather forecast for ${locationQuery}. 
                   Format it as JSON. Ensure icons are limited to: sun, cloud, rain, storm, snow, drizzle.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              location: { type: Type.STRING },
              currentTemp: { type: Type.NUMBER },
              condition: { type: Type.STRING },
              hourly: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    time: { type: Type.STRING },
                    temp: { type: Type.NUMBER },
                    icon: { type: Type.STRING }
                  },
                  required: ["time", "temp", "icon"]
                }
              },
              daily: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    day: { type: Type.STRING },
                    low: { type: Type.NUMBER },
                    high: { type: Type.NUMBER },
                    condition: { type: Type.STRING },
                    icon: { type: Type.STRING }
                  },
                  required: ["day", "low", "high", "condition", "icon"]
                }
              }
            },
            required: ["location", "currentTemp", "condition", "hourly", "daily"]
          }
        }
      });

      const data = JSON.parse(response.text || '{}');
      setWeatherData(data);
    } catch (err) {
      setError("Failed to load weather data. Please try again.");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const closeOverlay = () => {
    setIsOverlayOpen(false);
    if (timerRef.current) window.clearTimeout(timerRef.current);
  };

  return (
    <div className="min-h-screen bg-slate-900 text-white font-sans flex flex-col items-center justify-center p-4">
      {/* Main Dashboard UI */}
      <div className="max-w-md w-full bg-slate-800 rounded-3xl p-8 shadow-2xl border border-slate-700">
        <h1 className="text-3xl font-bold mb-6 text-center bg-gradient-to-r from-blue-400 to-emerald-400 bg-clip-text text-transparent">
          Smart Home
        </h1>

        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={fetchWeather}
            className="flex flex-col items-center justify-center p-6 bg-slate-700/50 hover:bg-blue-600/20 rounded-2xl border border-slate-600 transition-all group active:scale-95"
          >
            <Cloud className="w-12 h-12 text-blue-400 mb-2 group-hover:scale-110 transition-transform" />
            <span className="font-semibold">Weather</span>
            <span className="text-xs text-slate-400 mt-1">Check Forecast</span>
          </button>

          <div className="flex flex-col items-center justify-center p-6 bg-slate-700/50 rounded-2xl border border-slate-600">
            <Thermometer className="w-12 h-12 text-orange-400 mb-2" />
            <span className="font-semibold">22°C</span>
            <span className="text-xs text-slate-400 mt-1">Indoor Temp</span>
          </div>
        </div>
      </div>

      {/* Weather Overlay */}
      {isOverlayOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-0 sm:p-4 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-xl" onClick={closeOverlay} />

          <div className="relative w-full h-full sm:h-auto sm:max-w-3xl bg-white/10 border border-white/20 rounded-none sm:rounded-[2.5rem] overflow-hidden flex flex-col shadow-2xl overflow-y-auto max-h-screen no-scrollbar">

            {/* Header */}
            <div className="p-6 flex justify-between items-center border-b border-white/10 sticky top-0 bg-slate-900/50 backdrop-blur-md z-10">
              <div className="flex items-center gap-2 text-white/90">
                <MapPin className="w-5 h-5 text-blue-400" />
                <span className="font-medium text-lg">{loading ? 'Locating...' : weatherData?.location}</span>
              </div>
              <button 
                onClick={closeOverlay}
                className="p-2 hover:bg-white/10 rounded-full transition-colors"
              >
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6 sm:p-10 space-y-10">
              {loading ? (
                <div className="flex flex-col items-center justify-center py-20 gap-4">
                  <Loader2 className="w-12 h-12 text-blue-400 animate-spin" />
                  <p className="text-white/60 font-medium">Predicting the skies...</p>
                </div>
              ) : error ? (
                <div className="text-center py-20 space-y-4">
                  <p className="text-red-400">{error}</p>
                  <button onClick={fetchWeather} className="bg-white/10 px-6 py-2 rounded-full hover:bg-white/20 transition-colors">Retry</button>
                </div>
              ) : weatherData && (
                <>
                  {/* Current Weather Hero */}
                  <div className="text-center space-y-2 animate-in slide-in-from-bottom-4 duration-500">
                    <div className="flex justify-center mb-4">
                      <WeatherIcon type={weatherData.hourly[0]?.icon} className="w-24 h-24 text-blue-400" />
                    </div>
                    <div className="text-7xl font-light tracking-tighter">
                      {weatherData.currentTemp}°<span className="text-4xl text-white/40 font-thin">C</span>
                    </div>
                    <div className="text-xl text-white/60 font-medium capitalize">
                      {weatherData.condition}
                    </div>
                  </div>

                  {/* Hourly Forecast */}
                  <div className="space-y-4">
                    <div className="flex items-center gap-2 text-white/40 uppercase tracking-widest text-xs font-bold px-2">
                      <Clock className="w-4 h-4" />
                      Next 24 Hours
                    </div>
                    <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
                      {weatherData.hourly.map((hour, idx) => (
                        <div 
                          key={idx} 
                          className="flex-shrink-0 w-24 bg-white/5 rounded-3xl p-4 flex flex-col items-center gap-3 border border-white/5 hover:bg-white/10 transition-colors"
                        >
                          <span className="text-sm text-white/60">{hour.time}</span>
                          <WeatherIcon type={hour.icon} className="w-8 h-8 text-blue-300" />
                          <span className="font-semibold">{hour.temp}°</span>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* 7-Day Forecast */}
                  <div className="space-y-4">
                    <div className="flex items-center gap-2 text-white/40 uppercase tracking-widest text-xs font-bold px-2">
                      <Calendar className="w-4 h-4" />
                      7-Day Outlook
                    </div>
                    <div className="bg-white/5 rounded-[2rem] border border-white/5 overflow-hidden">
                      {weatherData.daily.map((day, idx) => (
                        <div 
                          key={idx} 
                          className={`flex items-center justify-between p-5 ${idx !== weatherData.daily.length - 1 ? 'border-b border-white/5' : ''}`}
                        >
                          <div className="w-24 font-medium">{idx === 0 ? 'Today' : day.day}</div>
                          <div className="flex items-center gap-3 flex-1 px-4">
                            <WeatherIcon type={day.icon} className="w-6 h-6 text-blue-300" />
                            <span className="text-sm text-white/60 capitalize truncate">{day.condition}</span>
                          </div>
                          <div className="flex gap-4 w-28 justify-end">
                            <span className="font-semibold">{day.high}°</span>
                            <span className="text-white/40">{day.low}°</span>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="text-center text-white/20 text-[10px] uppercase tracking-widest pt-4">
                    Auto-closing in 3 minutes
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

