import React, { useState, useEffect } from 'react';
import Calendar from './components/Calendar';
import WeatherWidget from './components/WeatherWidget';
import StockWidget from './components/StockWidget';
import TaskWidget from './components/TaskWidget';
import { GOOGLE_CLIENT_ID, GOOGLE_SCOPES } from './constants';
import { fetchUserProfile } from './services/googleCalendarService';

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('google_access_token'));
  const [user, setUser] = useState<any>(null);
  const [loginError, setLoginError] = useState<string | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setCurrentDate(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (accessToken) {
      fetchUserProfile(accessToken).then(profile => {
        if (profile && !profile.error) {
          setUser(profile);
          setLoginError(null);
        } else {
          handleLogout();
        }
      }).catch(() => handleLogout());
    }
  }, [accessToken]);

  const handleLogin = () => {
    setLoginError(null);
    try {
      // @ts-ignore
      if (typeof google === 'undefined' || !google.accounts) {
        setLoginError("Google Auth library not ready. Please refresh.");
        return;
      }

      // @ts-ignore
      const client = google.accounts.oauth2.initTokenClient({
        client_id: GOOGLE_CLIENT_ID,
        scope: GOOGLE_SCOPES,
        callback: (response: any) => {
          if (response.error) {
            setLoginError(`Google Error: ${response.error}`);
            console.error("Auth callback error:", response);
            return;
          }
          if (response.access_token) {
            setAccessToken(response.access_token);
            localStorage.setItem('google_access_token', response.access_token);
            setLoginError(null);
          }
        },
        error_callback: (err: any) => {
          if (err.type === 'popup_closed') {
            setLoginError("Inlogvenster gesloten.");
          } else {
            setLoginError("Authenticatie mislukt. Controleer 'JavaScript Origins' in Cloud Console.");
          }
          console.error("GIS Error:", err);
        }
      });

      // Using 'select_account' is smoother than 'consent' for repeated attempts
      client.requestAccessToken({ prompt: 'select_account' });
    } catch (err) {
      setLoginError("Login kon niet starten. Ben je verbonden?");
      console.error(err);
    }
  };

  const handleLogout = () => {
    setAccessToken(null);
    setUser(null);
    localStorage.removeItem('google_access_token');
    localStorage.removeItem('hub_agenda_events');
  };

  const formattedDate = currentDate.toLocaleDateString('nl-BE', {
    weekday: 'long',
    month: 'long',
    day: 'numeric'
  });

  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-[#fcfcfc] overflow-x-hidden">
      {/* Header */}
      <header className="w-full max-w-[1920px] px-8 pt-10 pb-6 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-50">
        <div>
          <h1 className="text-5xl md:text-6xl font-extralight tracking-tight text-gray-900">
            {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
            {user?.given_name ? `, ${user.given_name}` : ''}
          </h1>
          <div className="flex items-center gap-4 mt-3">
            <p className="text-gray-400 text-sm uppercase tracking-[0.3em] font-medium">
              {formattedDate}
            </p>
            {accessToken && (
              <button 
                onClick={handleLogout}
                className="text-[10px] text-gray-300 hover:text-red-400 uppercase tracking-widest font-bold transition-colors"
              >
                Log uit
              </button>
            )}
          </div>
        </div>

        <div className="mt-6 md:mt-0 flex flex-col items-end gap-3">
          {loginError && (
            <div className="bg-red-50 text-red-500 text-[10px] px-3 py-1.5 rounded-lg font-bold border border-red-100 mb-2 animate-fade-in flex items-center gap-2">
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z"/></svg>
              {loginError}
            </div>
          )}
          <div className="flex items-center gap-4">
            {!accessToken ? (
              <button 
                onClick={handleLogin}
                className="flex items-center gap-2 px-5 py-2.5 bg-white border border-gray-100 rounded-xl shadow-sm hover:border-black hover:shadow-md transition-all text-xs font-bold uppercase tracking-widest"
              >
                <svg className="w-4 h-4" viewBox="0 0 24 24">
                   <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                   <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                   <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"/>
                   <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                </svg>
                Google Login
              </button>
            ) : user && (
              <div className="flex items-center gap-3 animate-fade-in">
                <div className="text-right">
                  <div className="text-[10px] font-bold text-gray-900 uppercase tracking-widest">{user.name}</div>
                  <div className="text-[9px] text-green-500 font-bold">LIVE SYNC ACTIEF</div>
                </div>
                {user.picture && <img src={user.picture} alt="" className="w-8 h-8 rounded-full border border-gray-100 shadow-sm" />}
              </div>
            )}
            <WeatherWidget />
          </div>
          <div className="text-right">
            <div className="text-[10px] font-medium text-gray-300 uppercase tracking-[0.2em]">Herenthout, BE</div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="w-full max-w-[1920px] px-8 py-10 grid grid-cols-1 lg:grid-cols-12 gap-10 items-start">
        {/* Left Sidebar */}
        <aside className="lg:col-span-2 space-y-8">
          <StockWidget />
          <div className="p-6 bg-white rounded-3xl shadow-sm border border-gray-100 opacity-60">
            <span className="text-[10px] font-bold text-gray-300 uppercase tracking-[0.2em] block mb-3">Focus Quote</span>
            <p className="text-xs italic text-gray-500 leading-relaxed">"Focus on what you can control."</p>
          </div>
        </aside>

        {/* Center - Weekly Flow */}
        <section className="lg:col-span-8">
          <Calendar accessToken={accessToken} />
        </section>

        {/* Right Sidebar */}
        <aside className="lg:col-span-2">
          <TaskWidget />
        </aside>
      </main>

      {/* Footer */}
      <footer className="w-full max-w-[1920px] px-8 py-12 mt-auto text-center">
        <div className="inline-flex items-center gap-4 text-[10px] text-gray-200 uppercase tracking-[0.4em]">
          <span>Integrated Intelligence</span>
          <span className="w-1 h-1 rounded-full bg-gray-100"></span>
          <span>Google API Connected</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

