const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('google_access_token'));
  const [user, setUser] = useState<any>(null);
  const [loginError, setLoginError] = useState<string | null>(null);

  // Weather States
  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null);
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [weatherError, setWeatherError] = useState<string | null>(null);
  const autoCloseTimer = useRef<number | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setCurrentDate(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = () => {
    // Auth logic simplified for this example
    setAccessToken("mock_token");
    setUser({ given_name: "User", name: "User Name", picture: "" });
  };

  const handleLogout = () => {
    setAccessToken(null);
    setUser(null);
  };

  const fetchWeatherForecast = async () => {
    setWeatherLoading(true);
    setWeatherError(null);
    setIsWeatherOpen(true);

    // Set auto-close timer
    if (autoCloseTimer.current) window.clearTimeout(autoCloseTimer.current);
    autoCloseTimer.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);

    try {
      let location = "Herenthout, BE";
      try {
        const pos = await new Promise<GeolocationPosition>((res, rej) => 
          navigator.geolocation.getCurrentPosition(res, rej, { timeout: 5000 }));
        location = `${pos.coords.latitude}, ${pos.coords.longitude}`;
      } catch (e) { console.warn("Using default location"); }

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Genereer een realistische weersverwachting voor ${location} in JSON formaat. 
                   Geef 24 uur (elk uur) en 7 dagen. 
                   Beschikbare iconen: sun, cloud, rain, storm, snow, drizzle. 
                   Taal: Nederlands.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              location: { type: Type.STRING },
              currentTemp: { type: Type.NUMBER },
              condition: { type: Type.STRING },
              hourly: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    time: { type: Type.STRING },
                    temp: { type: Type.NUMBER },
                    icon: { type: Type.STRING }
                  },
                  required: ["time", "temp", "icon"]
                }
              },
              daily: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    day: { type: Type.STRING },
                    low: { type: Type.NUMBER },
                    high: { type: Type.NUMBER },
                    condition: { type: Type.STRING },
                    icon: { type: Type.STRING }
                  },
                  required: ["day", "low", "high", "condition", "icon"]
                }
              }
            },
            required: ["location", "currentTemp", "condition", "hourly", "daily"]
          }
        }
      });

      setWeatherData(JSON.parse(response.text || '{}'));
    } catch (err) {
      setWeatherError("Kon weersinformatie niet ophalen.");
      console.error(err);
    } finally {
      setWeatherLoading(false);
    }
  };

  const formattedDate = currentDate.toLocaleDateString('nl-BE', {
    weekday: 'long',
    month: 'long',
    day: 'numeric'
  });

  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-[#fcfcfc] overflow-x-hidden relative">
      {/* Header */}
      <header className="w-full max-w-[1920px] px-8 pt-10 pb-6 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-50">
        <div>
          <h1 className="text-5xl md:text-6xl font-extralight tracking-tight text-gray-900">
            {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
            {user?.given_name ? `, ${user.given_name}` : ''}
          </h1>
          <div className="flex items-center gap-4 mt-3">
            <p className="text-gray-400 text-sm uppercase tracking-[0.3em] font-medium">
              {formattedDate}
            </p>
            {accessToken && (
              <button 
                onClick={handleLogout}
                className="text-[10px] text-gray-300 hover:text-red-400 uppercase tracking-widest font-bold transition-colors"
              >
                Log uit
              </button>
            )}
          </div>
        </div>

        <div className="mt-6 md:mt-0 flex flex-col items-end gap-3">
          <div className="flex items-center gap-4">
            {!accessToken ? (
              <button 
                onClick={handleLogin}
                className="flex items-center gap-2 px-5 py-2.5 bg-white border border-gray-100 rounded-xl shadow-sm hover:border-black hover:shadow-md transition-all text-xs font-bold uppercase tracking-widest"
              >
                Google Login
              </button>
            ) : user && (
              <div className="flex items-center gap-3 animate-fade-in">
                <div className="text-right">
                  <div className="text-[10px] font-bold text-gray-900 uppercase tracking-widest">{user.name}</div>
                  <div className="text-[9px] text-green-500 font-bold">LIVE SYNC ACTIEF</div>
                </div>
                {user.picture && <img src={user.picture} alt="" className="w-8 h-8 rounded-full border border-gray-100 shadow-sm" />}
              </div>
            )}
            <WeatherWidget onClick={fetchWeatherForecast} />
          </div>
          <div className="text-right">
            <div className="text-[10px] font-medium text-gray-300 uppercase tracking-[0.2em]">Herenthout, BE</div>
          </div>
