          navigator.geolocation.getCurrentPosition(res, rej, { timeout: 8000 }));
        location = `lat: ${pos.coords.latitude}, lon: ${pos.coords.longitude}`;
      } catch (e) { console.warn("Using default location or manual query"); }

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Genereer een zeer gedetailleerde en realistische weersverwachting voor ${location} (en noem de dichtstbijzijnde stad/dorp in de response) in JSON-formaat. 
