// --- Main App ---
const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('google_access_token'));
  const [user, setUser] = useState<any>(null);

  // Weather States
  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null);
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [weatherError, setWeatherError] = useState<string | null>(null);
  const autoCloseTimer = useRef<number | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setCurrentDate(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = () => {
    setAccessToken("mock_token");
    setUser({ given_name: "Gasten", name: "Bezoeker", picture: "https://i.pravatar.cc/150?u=visitor" });
  };

  const handleLogout = () => {
    setAccessToken(null);
    setUser(null);
  };

  const fetchWeatherForecast = async () => {
    setWeatherLoading(true);
    setWeatherError(null);
    setIsWeatherOpen(true);

    // Reset auto-close timer (3 minutes)
    if (autoCloseTimer.current) window.clearTimeout(autoCloseTimer.current);
    autoCloseTimer.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);

    try {
      // Hardcoded location context for Gemini to ensure it matches meteo.be/nl/herenthout
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Genereer een realistische weersverwachting voor Herenthout, België (2270).
                   Baseer je op de huidige seizoenskenmerken voor deze regio in de Kempen.
                   Geef 24 uur (elk uur) en de komende 7 dagen. 
                   Iconen: sun, cloud, rain, storm, snow, drizzle. 
                   Voeg windSpeed (bijv '14 km/h') en humidity (getal) toe.
                   Output als JSON in het Nederlands.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              location: { type: Type.STRING },
              currentTemp: { type: Type.NUMBER },
              condition: { type: Type.STRING },
              humidity: { type: Type.NUMBER },
              windSpeed: { type: Type.STRING },
              hourly: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    time: { type: Type.STRING },
                    temp: { type: Type.NUMBER },
                    icon: { type: Type.STRING }
                  },
                  required: ["time", "temp", "icon"]
                }
              },
              daily: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    day: { type: Type.STRING },
                    low: { type: Type.NUMBER },
                    high: { type: Type.NUMBER },
                    condition: { type: Type.STRING },
                    icon: { type: Type.STRING }
                  },
                  required: ["day", "low", "high", "condition", "icon"]
                }
              }
            },
            required: ["location", "currentTemp", "condition", "hourly", "daily"]
          }
        }
      });

      const parsedData = JSON.parse(response.text || '{}');
      setWeatherData(parsedData);
    } catch (err) {
      setWeatherError("Kan weersinformatie voor Herenthout momenteel niet ophalen.");
      console.error(err);
    } finally {
      setWeatherLoading(false);
    }
  };

  const formattedDate = currentDate.toLocaleDateString('nl-BE', {
    weekday: 'long',
    month: 'long',
    day: 'numeric'
  });

  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-[#fcfcfc] overflow-x-hidden relative touch-pan-y">
      {/* Background Decor */}
      <div className="absolute top-0 right-0 w-[1000px] h-[1000px] bg-blue-50/40 rounded-full blur-[150px] -z-10 translate-x-1/3 -translate-y-1/3" />

      {/* Header */}
      <header className="w-full max-w-[1920px] px-10 sm:px-16 pt-16 pb-10 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-100/60">
        <div className="space-y-6">
          <h1 className="text-6xl sm:text-8xl font-extralight tracking-tighter text-gray-900 leading-[0.95]">
            {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
            {user?.given_name ? <span className="text-gray-300">, {user.given_name}</span> : ''}
          </h1>
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3">
               <Clock className="w-5 h-5 text-gray-300" />
               <p className="text-gray-400 text-sm uppercase tracking-[0.4em] font-black">
                 {formattedDate}
               </p>
            </div>
            {accessToken && (
              <button 
                onClick={handleLogout}
                className="text-[11px] text-gray-300 hover:text-red-400 uppercase tracking-widest font-black transition-colors border-l border-gray-100 pl-8 touch-manipulation"
              >
                Log uit
              </button>
            )}
          </div>
        </div>

        <div className="mt-12 md:mt-0 flex flex-col items-end gap-6">
          <div className="flex items-center gap-8">
            {!accessToken ? (
              <button 
                onClick={handleLogin}
                className="flex items-center gap-4 px-10 py-5 bg-gray-900 text-white rounded-2xl shadow-xl hover:bg-black transition-all text-xs font-black uppercase tracking-[0.3em] active:scale-95 touch-manipulation"
              >
                Google Sync
              </button>
            ) : (
              <div className="flex items-center gap-6 bg-white p-3 pr-8 rounded-[1.5rem] border border-gray-50 shadow-sm">
                <div className="w-12 h-12 bg-gray-100 rounded-2xl overflow-hidden">
                   <img src={user.picture} alt="" className="w-full h-full object-cover" />
                </div>
                <div className="text-right">
                  <div className="text-xs font-black text-gray-900 uppercase tracking-widest">{user.name}</div>
                  <div className="text-[10px] text-green-500 font-bold flex items-center justify-end gap-2">
                    <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />
                    LIVE
                  </div>
                </div>
              </div>
            )}
            <WeatherWidget onClick={fetchWeatherForecast} />
          </div>
          <div className="text-right px-2">
            <div className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em]">LOCATIE: HERENTHOUT, BE</div>
          </div>
        </div>
      </header>

      {/* Content Grid */}
      <main className="w-full max-w-[1920px] px-10 sm:px-16 py-16 grid grid-cols-1 xl:grid-cols-12 gap-16 items-start">
        <aside className="xl:col-span-3 space-y-12">
          <StockWidget />
          <div className="p-10 bg-white rounded-[3rem] shadow-sm border border-gray-100 relative group overflow-hidden">
