            <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] block mb-6">Mantra</span>
            <p className="text-lg font-light text-gray-500 leading-relaxed italic">
              "Focus op de voortgang, niet op de perfectie."
            </p>
          </div>
        </aside>

        <section className="xl:col-span-6">
          <Calendar accessToken={accessToken} />
        </section>

        <aside className="xl:col-span-3">
          <TaskWidget />
        </aside>
      </main>

      {/* Overlay Render */}
      {isWeatherOpen && (
        <WeatherOverlay 
          onClose={() => setIsWeatherOpen(false)}
          weatherData={weatherData}
          loading={weatherLoading}
          error={weatherError}
          onRetry={fetchWeatherForecast}
        />
      )}

      {/* Interactive Footer */}
      <footer className="w-full max-w-[1920px] px-16 py-20 mt-auto flex flex-col items-center gap-10">
