  const [weatherError, setWeatherError] = useState<string | null>(null);
  const autoCloseTimer = useRef<number | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setCurrentDate(new Date()), 60000);
    // Initial fetch to populate widget
    fetchWeatherForecast(false); 
    return () => clearInterval(timer);
  }, []);

  const handleLogin = () => {
    setAccessToken("mock_token");
    setUser({ given_name: "Gasten", name: "Bezoeker", picture: "https://i.pravatar.cc/150?u=visitor" });
  };

  const handleLogout = () => {
    setAccessToken(null);
    setUser(null);
  };

  async function fetchWeatherForecast(openOverlay = true) {
    if (openOverlay) {
      setWeatherLoading(true);
      setIsWeatherOpen(true);

      // Auto-close timer
      if (autoCloseTimer.current) window.clearTimeout(autoCloseTimer.current);
      autoCloseTimer.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);
    }

    setWeatherError(null);

    try {
      const response = await ai.models.generateContent({
