            <div className="w-full space-y-24 pb-20">
              <div className="space-y-10">
                <div className="flex items-center gap-4 px-4">
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full" />
                  <span className="text-sm text-gray-900 font-black uppercase tracking-[0.4em]">Komende 14 uur</span>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-12 no-scrollbar px-4 custom-touch-scrollbar scroll-smooth snap-x">
                  {weatherData.hourly.slice(0, 14).map((h: any, i: number) => (
                    <div 
                      key={i} 
                      className="flex-shrink-0 w-28 sm:w-32 bg-white/60 border border-white p-6 sm:p-8 rounded-[2rem] flex flex-col items-center gap-6 hover:bg-white hover:shadow-2xl transition-all snap-start"
                    >
                      <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.1em]">{h.time}</span>
                      <WeatherIcon type={h.icon} className="w-10 h-10 text-blue-400" />
                      <span className="text-2xl font-light text-gray-900 tracking-tight">{h.temp}°</span>
                    </div>
