// --- Main App ---
const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('hub_access_token'));
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const tokenClientRef = useRef<any>(null);

  // Agenda States
  const [agendaItems, setAgendaItems] = useState<AgendaItem[]>([]);
  const [agendaLoading, setAgendaLoading] = useState(false);

  // Weather States
  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(() => {
    const cached = localStorage.getItem(WEATHER_CACHE_KEY);
    if (cached) {
      try { return JSON.parse(cached); } catch (e) { return null; }
    }
    return null;
  });
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [weatherError, setWeatherError] = useState<string | null>(null);
  const autoCloseTimer = useRef<number | null>(null);

  useEffect(() => {
    // Clock
    const clockTimer = setInterval(() => setCurrentDate(new Date()), 60000);

    // Initialize Google Identity Services
    const initGsi = () => {
      // Fix: Access google property via any cast to resolve property not existing on window error
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: async (response: any) => {
            if (response.access_token) {
              setAccessToken(response.access_token);
              localStorage.setItem('hub_access_token', response.access_token);
              await fetchUserProfile(response.access_token);
              await fetchCalendarEvents(response.access_token);
            }
            setIsSyncing(false);
          },
        });

        // If we have a cached token, try to refresh user info & events
        if (accessToken) {
          fetchUserProfile(accessToken).catch(() => handleLogout());
          fetchCalendarEvents(accessToken).catch(() => handleLogout());
        }
      } else {
        setTimeout(initGsi, 500);
      }
    };
    initGsi();

    // Weather auto-fetch
    const cached = localStorage.getItem(WEATHER_CACHE_KEY);
    let shouldFetchWeather = true;
    if (cached) {
      try {
        const parsed = JSON.parse(cached);
        if (parsed.lastUpdated && Date.now() - parsed.lastUpdated < CACHE_DURATION) {
          shouldFetchWeather = false;
        }
      } catch (e) {}
    }
    if (shouldFetchWeather) fetchWeatherForecast(false); 

    return () => clearInterval(clockTimer);
  }, []);

  const handleLogin = () => {
    setIsSyncing(true);
    if (tokenClientRef.current) {
      tokenClientRef.current.requestAccessToken({ prompt: accessToken ? '' : 'select_account' });
    }
  };

  const handleLogout = () => {
    const oldToken = accessToken;
    setAccessToken(null);
    setUser(null);
    setAgendaItems([]);
    localStorage.removeItem('hub_access_token');
    // Fix: Access google property via any cast to resolve property not existing on window error
    if ((window as any).google) {
      (window as any).google.accounts.oauth2.revoke(oldToken || '', () => {});
    }
  };

  const fetchUserProfile = async (token: string) => {
    try {
      const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!resp.ok) throw new Error('Auth expired');
      const data = await resp.json();
      setUser({
        given_name: data.given_name,
        name: data.name,
        picture: data.picture
      });
    } catch (err) {
      handleLogout();
    }
  };

  const fetchCalendarEvents = async (token: string) => {
    setAgendaLoading(true);
    try {
      const now = new Date();
      const startOfDay = new Date(now.setHours(0, 0, 0, 0)).toISOString();
      const endOfDay = new Date(now.setHours(23, 59, 59, 999)).toISOString();

      const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${startOfDay}&timeMax=${endOfDay}&singleEvents=true&orderBy=startTime`;

      const resp = await fetch(url, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (!resp.ok) {
        if (resp.status === 401) handleLogout();
        throw new Error('Calendar fetch failed');
      }

      const data = await resp.json();
      const mappedItems: AgendaItem[] = data.items.map((event: any) => {
        const start = event.start.dateTime || event.start.date;
        const timeStr = new Date(start).toLocaleTimeString('nl-BE', { 
          hour: '2-digit', 
          minute: '2-digit', 
          hour12: false 
        });

        // Categorization logic based on keywords
        let category: any = 'personal';
        const titleLower = (event.summary || '').toLowerCase();
        if (titleLower.includes('werk') || titleLower.includes('meeting') || titleLower.includes('call')) category = 'work';
        else if (titleLower.includes('doktor') || titleLower.includes('sport') || titleLower.includes('fitness')) category = 'health';
        else if (titleLower.includes('feest') || titleLower.includes('drink') || titleLower.includes('dinner')) category = 'social';

        return {
          id: event.id,
          time: timeStr,
          title: event.summary || '(Geen titel)',
          location: event.location || '',
          category: category
        };
      });

      setAgendaItems(mappedItems);
    } catch (err) {
      console.error("Calendar fetch error:", err);
    } finally {
      setAgendaLoading(false);
    }
  };

  async function fetchWeatherForecast(triggerOverlay = true) {
    if (triggerOverlay) {
      setIsWeatherOpen(true);
      if (autoCloseTimer.current) window.clearTimeout(autoCloseTimer.current);
      autoCloseTimer.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);
    }

    const isStale = !weatherData || (weatherData.lastUpdated && Date.now() - weatherData.lastUpdated > CACHE_DURATION);
    if (isStale || triggerOverlay) setWeatherLoading(true);

    setWeatherError(null);

    try {
      // Fix: Create new GoogleGenAI instance before call as per guidelines
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Zoek het actuele weer voor Herenthout, België via https://www.meteo.be/nl/herenthout. 
                   Zorg dat je exact 24 uurlijkse datapunten (hourly) en exact 7 dagelijkse datapunten (daily) ophaalt. 
                   Gebruik de tool voor up-to-date data. Return JSON in het Nederlands.`,
        config: {
          tools: [{googleSearch: {}}],
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              location: { type: Type.STRING },
              currentTemp: { type: Type.NUMBER },
              condition: { type: Type.STRING },
              humidity: { type: Type.NUMBER },
              windSpeed: { type: Type.STRING },
              hourly: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    time: { type: Type.STRING },
                    temp: { type: Type.NUMBER },
                    icon: { type: Type.STRING }
                  },
                  required: ["time", "temp", "icon"]
                }
              },
              daily: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    day: { type: Type.STRING },
                    low: { type: Type.NUMBER },
                    high: { type: Type.NUMBER },
                    condition: { type: Type.STRING },
                    icon: { type: Type.STRING }
                  },
                  required: ["day", "low", "high", "condition", "icon"]
                }
              }
            },
            required: ["location", "currentTemp", "condition", "hourly", "daily"]
          }
        }
      });

      // Fix: Use text property directly and handle grounding chunks URLs
      const text = response.text || '{}';
      const parsedData = JSON.parse(text);

      // Extract URL from search grounding if available
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks && chunks.length > 0) {
        const webChunk = chunks.find((c: any) => c.web?.uri);
        if (webChunk) parsedData.sourceUrl = webChunk.web.uri;
      }

      if (!parsedData.sourceUrl) parsedData.sourceUrl = "https://www.meteo.be/nl/herenthout";
      parsedData.lastUpdated = Date.now();

      setWeatherData(parsedData);
      localStorage.setItem(WEATHER_CACHE_KEY, JSON.stringify(parsedData));
    } catch (err) {
      console.error("Weather fetch failed:", err);
      if (triggerOverlay && !weatherData) setWeatherError("Live data kon niet worden opgehaald.");
    } finally {
      setWeatherLoading(false);
    }
  }

  const handleWeatherClick = () => {
    const isStale = !weatherData || (weatherData.lastUpdated && Date.now() - weatherData.lastUpdated > CACHE_DURATION);
    setIsWeatherOpen(true);
    if (autoCloseTimer.current) window.clearTimeout(autoCloseTimer.current);
    autoCloseTimer.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);
    if (isStale) fetchWeatherForecast(true);
  };

  const formattedDate = currentDate.toLocaleDateString('nl-BE', {
    weekday: 'long',
    month: 'long',
    day: 'numeric'
  });

  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-[#fcfcfc] overflow-x-hidden relative touch-pan-y">
      <div className="absolute top-0 right-0 w-[1000px] h-[1000px] bg-blue-50/40 rounded-full blur-[150px] -z-10 translate-x-1/3 -translate-y-1/3" />

      {/* Header */}
      <header className="w-full px-[30px] pt-12 pb-8 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-100/60">
        <div className="space-y-6">
          <h1 className="text-6xl sm:text-8xl font-extralight tracking-tighter text-gray-900 leading-[0.95]">
            {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
            {user?.given_name ? <span className="text-gray-300">, {user.given_name}</span> : ''}
          </h1>
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3">
               <Clock className="w-5 h-5 text-gray-300" />
               <p className="text-gray-400 text-sm uppercase tracking-[0.4em] font-black">
                 {formattedDate}
               </p>
            </div>
            {accessToken && (
              <button 
                onClick={handleLogout}
                className="text-[11px] text-gray-300 hover:text-red-400 uppercase tracking-widest font-black transition-colors border-l border-gray-100 pl-8 touch-manipulation flex items-center gap-2"
              >
                Log uit
              </button>
            )}
          </div>
        </div>

        <div className="mt-12 md:mt-0 flex flex-col items-end gap-6">
          <div className="flex items-center gap-8">
            {!accessToken ? (
              <button 
                onClick={handleLogin}
                disabled={isSyncing}
                className={`flex items-center gap-4 px-10 py-5 bg-gray-900 text-white rounded-2xl shadow-xl hover:bg-black transition-all text-xs font-black uppercase tracking-[0.3em] active:scale-95 touch-manipulation ${isSyncing ? 'opacity-70 cursor-wait' : ''}`}
              >
                {isSyncing ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
                {isSyncing ? 'Verbinden...' : 'Google Sync'}
              </button>
            ) : (
              <div className="flex items-center gap-6 bg-white p-3 pr-8 rounded-[1.5rem] border border-gray-50 shadow-sm animate-in fade-in zoom-in-95 duration-300">
                <div className="w-12 h-12 bg-gray-100 rounded-2xl overflow-hidden shadow-inner border border-gray-50">
                   <img src={user?.picture} alt="" className="w-full h-full object-cover" />
                </div>
                <div className="text-right">
                  <div className="text-xs font-black text-gray-900 uppercase tracking-widest">{user?.name || 'Account'}</div>
                  <div className="text-[10px] text-green-500 font-bold flex items-center justify-end gap-2">
                    <CheckCircle2 size={10} className="text-green-500" />
                    LIVE SYNC
                  </div>
                </div>
              </div>
            )}
            <WeatherWidget 
              data={weatherData} 
              onClick={handleWeatherClick} 
              isRefreshing={weatherLoading && !!weatherData} 
            />
          </div>
          <div className="text-right px-2">
            <div className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em]">HERENTHOUT, BELGIË</div>
          </div>
        </div>
      </header>

      {/* Main Grid */}
      <main className="w-full px-[30px] py-12 grid grid-cols-1 xl:grid-cols-10 gap-8 items-start h-full">

        {/* Agenda - 80% span */}
        <section className="xl:col-span-8 h-full">
          <Calendar 
            accessToken={accessToken} 
            items={agendaItems} 
            isLoading={agendaLoading} 
            onRefresh={() => accessToken && fetchCalendarEvents(accessToken)}
          />
        </section>

        {/* Sidebar - 20% span */}
        <aside className="xl:col-span-2 space-y-8 flex flex-col h-full">
          <TaskWidget />
          <StockWidget />
          <div className="p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100 relative group overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-blue-50/30 rounded-full -mr-12 -mt-12 group-hover:scale-125 transition-transform duration-1000" />
            <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] block mb-6">Mantra</span>
            <p className="text-md font-light text-gray-500 leading-relaxed italic">
              "Focus op de voortgang, niet op de perfectie."
            </p>
          </div>
        </aside>
      </main>

      {isWeatherOpen && (
        <WeatherOverlay 
          onClose={() => setIsWeatherOpen(false)}
          weatherData={weatherData}
          loading={weatherLoading}
          error={weatherError}
          onRetry={() => fetchWeatherForecast(true)}
        />
      )}

      {/* Footer */}
      <footer className="w-full px-[30px] py-16 mt-auto flex flex-col items-center gap-10">
        <div className="flex items-center gap-12 text-[11px] text-gray-200 uppercase tracking-[0.6em] font-black">
          <span className="cursor-default">Digital Hub Herenthout</span>
          <div className="w-2 h-2 rounded-full bg-blue-50" />
          <span className="cursor-default">v2.6.0 Live Sync</span>
        </div>
        <div className="w-32 h-1.5 bg-gray-100 rounded-full" />
      </footer>
    </div>
  );
};

