    <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.3em] block mb-6">Financieel</span>
    <div className="space-y-4">
      <div className="flex justify-between items-center p-4 bg-gray-50/50 rounded-2xl border border-gray-100">
