        </div>
        <span className="text-xs font-black text-green-500 bg-green-50 px-3 py-1 rounded-full">+0.38%</span>
      </div>
      <div className="flex justify-between items-center p-4 bg-gray-50/50 rounded-2xl border border-gray-100">
        <div>
          <span className="text-[10px] font-bold text-gray-400 block uppercase tracking-widest">DAX</span>
          <span className="text-sm font-bold text-gray-800">18.210,40</span>
        </div>
        <span className="text-xs font-black text-red-400 bg-red-50 px-3 py-1 rounded-full">-0.05%</span>
      </div>
