);

const TaskWidget = () => (
  <div className="p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100">
    <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.3em] block mb-6">Takenlijst</span>
    <div className="space-y-3">
      {[
        { label: 'Check Meteo Herenthout', time: '09:00' },
        { label: 'Belastingaangifte', time: '11:30' },
