);

// --- Weather Components ---
const WeatherIcon = ({ type, className }: { type: string, className?: string }) => {
  switch (type.toLowerCase()) {
    case 'sun': return <Sun className={className} />;
    case 'cloud': return <Cloud className={className} />;
    case 'rain': return <CloudRain className={className} />;
    case 'storm': return <CloudLightning className={className} />;
    case 'snow': return <CloudSnow className={className} />;
    case 'drizzle': return <CloudDrizzle className={className} />;
    default: return <Cloud className={className} />;
  }
};

const WeatherWidget = ({ data, onClick, isRefreshing }: { data: WeatherData | null, onClick: () => void, isRefreshing: boolean }) => (
  <button 
    onClick={onClick}
    className="flex items-center gap-6 px-8 py-5 bg-white border border-gray-100 rounded-2xl shadow-sm hover:border-blue-400 hover:shadow-xl transition-all group active:scale-95 touch-manipulation relative"
  >
    <div className="flex flex-col items-end">
      <span className="text-xl font-black text-gray-900 leading-none">
        {data ? `${data.currentTemp}°C` : '--°C'}
      </span>
      {data && (
        <div className="flex items-center gap-1.5 mt-1.5">
          <Wind size={10} className="text-blue-300" />
          <span className="text-[9px] text-gray-400 uppercase tracking-widest font-black">{data.windSpeed}</span>
        </div>
      )}
      <span className="text-[8px] text-gray-300 uppercase tracking-[0.2em] font-black mt-1">Herenthout</span>
    </div>
    <div className="w-14 h-14 bg-blue-50 rounded-2xl flex items-center justify-center group-hover:bg-blue-100 transition-colors">
      {isRefreshing ? (
        <RefreshCw className="w-6 h-6 text-blue-300 animate-spin" />
      ) : (
        <WeatherIcon type={data?.hourly[0]?.icon || 'cloud'} className="w-7 h-7 text-blue-400 group-hover:scale-110 transition-transform" />
      )}
    </div>
  </button>
);

const WeatherOverlay = ({ onClose, weatherData, loading, error, onRetry, debugLog }: any) => {
  const handleContentClick = (e: React.MouseEvent) => e.stopPropagation();
  const [copied, setCopied] = useState(false);

  const handleCopyLog = () => {
    if (debugLog) {
      navigator.clipboard.writeText(debugLog);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const handleSelectKey = async () => {
    if ((window as any).aistudio?.openSelectKey) {
      await (window as any).aistudio.openSelectKey();
      onRetry();
    }
  };

  const isKeyError = error?.toLowerCase().includes('key') || debugLog?.toLowerCase().includes('key');

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center animate-in fade-in duration-300">
      <div className="absolute inset-0 bg-white/40 backdrop-blur-[60px]" onClick={onClose} />

      <div 
        onClick={handleContentClick}
        className="relative w-full h-full bg-white/50 flex flex-col overflow-hidden"
      >
        <div className="p-[30px] flex justify-between items-center border-b border-gray-200/20 bg-white/30 backdrop-blur-xl shrink-0">
          <div className="flex items-center gap-6">
            <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center shadow-md border border-gray-50">
              <Clock className="w-7 h-7 text-blue-500" />
            </div>
            <div>
              <h3 className="text-2xl font-black text-gray-900 tracking-tight">
                {loading && !weatherData ? 'Laden...' : 'Weersverwachting'}
              </h3>
              <p className="text-xs text-gray-400 font-black uppercase tracking-[0.3em] mt-0.5 flex items-center gap-2">
                Herenthout, BE 
                {weatherData?.sourceUrl && <a href={weatherData.sourceUrl} target="_blank" rel="noreferrer" className="text-blue-400 hover:text-blue-600"><ExternalLink size={12}/></a>}
                {weatherData?.lastUpdated && <span className="text-[9px] opacity-60">Sinds {new Date(weatherData.lastUpdated).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit' })}</span>}
              </p>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="w-16 h-16 flex items-center justify-center bg-gray-900 hover:bg-black rounded-[2rem] transition-all text-white shadow-2xl active:scale-90 touch-manipulation"
          >
            <X className="w-8 h-8" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-[30px] space-y-24 scroll-smooth custom-touch-scrollbar">
          {loading && !weatherData ? (
            <div className="flex flex-col items-center justify-center py-40 gap-10">
              <div className="relative">
                <Loader2 className="w-20 h-20 text-blue-500 animate-spin" />
                <div className="absolute inset-0 blur-3xl bg-blue-500/10 animate-pulse rounded-full scale-150" />
              </div>
              <p className="text-gray-900 text-xs font-black uppercase tracking-[0.5em] animate-pulse">Data ophalen...</p>
            </div>
          ) : error && !weatherData ? (
            <div className="text-center py-40 space-y-8 animate-in slide-in-from-bottom-2">
              <X className="w-20 h-20 text-red-400 mx-auto" />
              <div className="space-y-6">
                <p className="text-gray-600 font-medium max-w-sm mx-auto text-lg">{error}</p>

                <div className="flex flex-col gap-4 items-center">
                  {isKeyError && (
                    <button 
                      onClick={handleSelectKey}
                      className="flex items-center gap-3 px-8 py-4 bg-blue-600 text-white rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-blue-700 shadow-xl transition-all active:scale-95"
                    >
                      <Key size={16} />
                      Selecteer API Key
                    </button>
                  )}

                  {debugLog && (
                    <button 
                      onClick={handleCopyLog}
                      className="flex items-center gap-2 px-4 py-2 text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-blue-500 transition-colors border border-gray-100 rounded-xl hover:border-blue-100 bg-gray-50/50"
                    >
                      {copied ? <ClipboardCheck size={14} className="text-green-500" /> : <Copy size={14} />}
                      {copied ? 'Foutlog Gekopieerd' : 'Kopieer Foutlog'}
                    </button>
                  )}
                </div>
              </div>

              <div className="pt-8">
                <button 
                  onClick={onRetry} 
                  className="px-12 py-6 bg-gray-900 text-white rounded-[2rem] text-xs font-black uppercase tracking-[0.3em] hover:bg-black transition-all shadow-xl active:scale-95 touch-manipulation"
                >
                  Opnieuw proberen
                </button>
              </div>

              {isKeyError && (
                <p className="text-[10px] text-gray-300 uppercase tracking-widest mt-12 max-w-xs mx-auto">
                  Let op: Gebruik een API key uit een GCP project met facturering ingeschakeld (billing).
                </p>
              )}
            </div>
          ) : weatherData && (
            <div className="w-full space-y-24 pb-20">
              <div className="space-y-10">
                <div className="flex items-center gap-4 px-4">
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full" />
                  <span className="text-sm text-gray-900 font-black uppercase tracking-[0.4em]">Komende 14 uur</span>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-12 no-scrollbar px-4 custom-touch-scrollbar scroll-smooth snap-x">
                  {weatherData.hourly.slice(0, 14).map((h: any, i: number) => (
                    <div 
                      key={i} 
                      className="flex-shrink-0 w-28 sm:w-32 bg-white/60 border border-white p-6 sm:p-8 rounded-[2rem] flex flex-col items-center gap-6 hover:bg-white hover:shadow-2xl transition-all snap-start"
                    >
                      <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.1em]">{h.time}</span>
                      <WeatherIcon type={h.icon} className="w-10 h-10 text-blue-400" />
                      <span className="text-2xl font-light text-gray-900 tracking-tight">{h.temp}°</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="space-y-10">
                <div className="flex items-center gap-4 px-4">
                   <div className="w-1.5 h-1.5 bg-blue-500 rounded-full" />
                  <span className="text-sm text-gray-900 font-black uppercase tracking-[0.4em]">Komende 7 dagen</span>
                </div>
                <div className="flex xl:grid xl:grid-cols-7 gap-6 overflow-x-auto xl:overflow-visible pb-10 xl:pb-0 px-4 custom-touch-scrollbar">
                  {weatherData.daily.slice(0, 7).map((d: any, i: number) => (
                    <div key={i} className={`flex-shrink-0 w-[260px] xl:w-auto p-10 bg-white/40 border border-white rounded-[3.5rem] flex flex-col items-center gap-8 hover:bg-white transition-all ${i === 0 ? 'ring-2 ring-blue-100 ring-offset-4 ring-offset-white' : ''}`}>
                      <span className="text-[12px] font-black text-gray-800 tracking-widest">{i === 0 ? 'VANDAAG' : d.day.toUpperCase()}</span>
                      <WeatherIcon type={d.icon} className="w-16 h-16 text-blue-300 my-4" />
                      <div className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] text-center px-2 leading-relaxed line-clamp-2 min-h-[3rem]">
                        {d.condition}
                      </div>
                      <div className="mt-4 flex items-center gap-6 border-t border-gray-100/50 pt-10 w-full justify-center">
                        <span className="text-3xl font-black text-gray-900">{d.high}°</span>
                        <span className="text-3xl font-light text-gray-300">{d.low}°</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="py-10 text-center space-y-4">
                <div className="flex items-center justify-center gap-6 text-[10px] text-gray-200 font-black uppercase tracking-[0.6em]">
                  <span className="w-12 h-px bg-gray-100" />
                  Geoptimaliseerde Cache Actief
                  <span className="w-12 h-px bg-gray-100" />
                </div>
                <p className="text-[9px] font-bold text-gray-300 uppercase tracking-widest">Inactiviteitstimer: 3 minuten</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// --- Main App ---
const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('hub_access_token'));
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const tokenClientRef = useRef<any>(null);

  // Agenda States
  const [agendaItems, setAgendaItems] = useState<AgendaItem[]>([]);
  const [agendaLoading, setAgendaLoading] = useState(false);

  // Weather States
  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(() => {
    const cached = localStorage.getItem(WEATHER_CACHE_KEY);
    if (cached) {
      try { return JSON.parse(cached); } catch (e) { return null; }
    }
    return null;
  });
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [weatherError, setWeatherError] = useState<string | null>(null);
  const [weatherDebugLog, setWeatherDebugLog] = useState<string | null>(null);
  const autoCloseTimer = useRef<number | null>(null);

  useEffect(() => {
    // Clock
    const clockTimer = setInterval(() => setCurrentDate(new Date()), 60000);

    // Initialize Google Identity Services
    const initGsi = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: async (response: any) => {
            if (response.access_token) {
              setAccessToken(response.access_token);
              localStorage.setItem('hub_access_token', response.access_token);
              await fetchUserProfile(response.access_token);
              await fetchCalendarEvents(response.access_token);
            }
            setIsSyncing(false);
          },
        });

        if (accessToken) {
          fetchUserProfile(accessToken).catch(() => handleLogout());
          fetchCalendarEvents(accessToken).catch(() => handleLogout());
        }
      } else {
        setTimeout(initGsi, 500);
      }
    };
    initGsi();

    const cached = localStorage.getItem(WEATHER_CACHE_KEY);
    let shouldFetchWeather = true;
    if (cached) {
      try {
        const parsed = JSON.parse(cached);
        if (parsed.lastUpdated && Date.now() - parsed.lastUpdated < CACHE_DURATION) {
          shouldFetchWeather = false;
        }
      } catch (e) {}
    }
    if (shouldFetchWeather) fetchWeatherForecast(false); 

    return () => clearInterval(clockTimer);
  }, []);

  const handleLogin = () => {
    setIsSyncing(true);
    if (tokenClientRef.current) {
      tokenClientRef.current.requestAccessToken({ prompt: accessToken ? '' : 'select_account' });
    }
  };

  const handleLogout = () => {
    const oldToken = accessToken;
    setAccessToken(null);
    setUser(null);
    setAgendaItems([]);
    localStorage.removeItem('hub_access_token');
    if ((window as any).google) {
      (window as any).google.accounts.oauth2.revoke(oldToken || '', () => {});
    }
  };

  const fetchUserProfile = async (token: string) => {
    try {
      const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!resp.ok) throw new Error('Auth expired');
      const data = await resp.json();
      setUser({
        given_name: data.given_name,
        name: data.name,
        picture: data.picture
      });
    } catch (err) {
      handleLogout();
    }
  };

  const fetchCalendarEvents = async (token: string) => {
    setAgendaLoading(true);
    try {
      const now = new Date();
      const startOfDay = new Date(now.setHours(0, 0, 0, 0)).toISOString();
      const endOfDay = new Date(now.setHours(23, 59, 59, 999)).toISOString();

      const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${startOfDay}&timeMax=${endOfDay}&singleEvents=true&orderBy=startTime`;

      const resp = await fetch(url, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (!resp.ok) {
        if (resp.status === 401) handleLogout();
        throw new Error('Calendar fetch failed');
      }

      const data = await resp.json();
      const mappedItems: AgendaItem[] = data.items.map((event: any) => {
        const start = event.start.dateTime || event.start.date;
        const timeStr = new Date(start).toLocaleTimeString('nl-BE', { 
          hour: '2-digit', 
          minute: '2-digit', 
          hour12: false 
        });

        let category: any = 'personal';
        const titleLower = (event.summary || '').toLowerCase();
        if (titleLower.includes('werk') || titleLower.includes('meeting') || titleLower.includes('call')) category = 'work';
        else if (titleLower.includes('doktor') || titleLower.includes('sport') || titleLower.includes('fitness')) category = 'health';
        else if (titleLower.includes('feest') || titleLower.includes('drink') || titleLower.includes('dinner')) category = 'social';

        return {
          id: event.id,
          time: timeStr,
          title: event.summary || '(Geen titel)',
          location: event.location || '',
          category: category
        };
      });

      setAgendaItems(mappedItems);
    } catch (err) {
      console.error("Calendar fetch error:", err);
    } finally {
      setAgendaLoading(false);
    }
  };

  async function fetchWeatherForecast(triggerOverlay = true) {
    if (triggerOverlay) {
      setIsWeatherOpen(true);
      if (autoCloseTimer.current) window.clearTimeout(autoCloseTimer.current);
      autoCloseTimer.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);
    }

    const isStale = !weatherData || (weatherData.lastUpdated && Date.now() - weatherData.lastUpdated > CACHE_DURATION);
    if (isStale || triggerOverlay) setWeatherLoading(true);

    setWeatherError(null);
    setWeatherDebugLog(null);

    let debugInfo = `Timestamp: ${new Date().toISOString()}\n`;
    debugInfo += `Injected API Key length: ${process.env.API_KEY?.length || 0}\n`;

    try {
      // Check if we need to request a key selection from user
      if (typeof (window as any).aistudio?.hasSelectedApiKey === 'function') {
        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        if (!hasKey) {
          debugInfo += "No API key selected via AI Studio dialog. Opening selector.\n";
          setWeatherError("Kies een API Key om live weerdata op te halen.");
          setWeatherDebugLog(debugInfo);
          setWeatherLoading(false);
          return;
        }
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      debugInfo += "Initiating AI generateContent call with gemini-3-flash-preview...\n";

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", 
        contents: `Gebruik Google Search om de meest actuele en gedetailleerde weersinformatie voor Herenthout op te halen, specifiek van https://www.meteo.be/nl/herenthout. 
                   Je MOET de volgende data exact ophalen en structureren:
                   - Huidige temperatuur (in Celsius), windsnelheid en luchtvochtigheid.
                   - EXACT 14 uurlijkse datapunten (tijdstip, temperatuur, icon) voor de komende uren.
                   - EXACT 7 dagelijkse datapunten (dagnaam, min temp, max temp, conditie, icon) beginnend bij vandaag.
                   Mogelijke icon-namen: sun, cloud, rain, storm, snow, drizzle.
                   Return uitsluitend JSON in het Nederlands.`,
        config: {
          tools: [{googleSearch: {}}],
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              location: { type: Type.STRING },
              currentTemp: { type: Type.NUMBER },
              condition: { type: Type.STRING },
              humidity: { type: Type.NUMBER },
              windSpeed: { type: Type.STRING },
              hourly: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    time: { type: Type.STRING },
                    temp: { type: Type.NUMBER },
                    icon: { type: Type.STRING }
                  },
                  required: ["time", "temp", "icon"]
                }
              },
              daily: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    day: { type: Type.STRING },
                    low: { type: Type.NUMBER },
                    high: { type: Type.NUMBER },
                    condition: { type: Type.STRING },
                    icon: { type: Type.STRING }
                  },
                  required: ["day", "low", "high", "condition", "icon"]
                }
              }
            },
            required: ["location", "currentTemp", "condition", "hourly", "daily"]
          }
        }
      });

      debugInfo += "Response received.\n";
      let text = response.text || '{}';
      let parsedData;
      try {
        parsedData = JSON.parse(text);
      } catch (e) {
        const jsonBlock = text.match(/\{[\s\S]*\}/);
        if (jsonBlock) {
          parsedData = JSON.parse(jsonBlock[0]);
        } else {
          throw new Error("Geen geldige JSON data ontvangen.");
        }
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const webLink = chunks.find((c: any) => c.web?.uri);
        if (webLink) parsedData.sourceUrl = webLink.web.uri;
      }

      if (!parsedData.sourceUrl) parsedData.sourceUrl = "https://www.meteo.be/nl/herenthout";
      parsedData.lastUpdated = Date.now();

      setWeatherData(parsedData);
      localStorage.setItem(WEATHER_CACHE_KEY, JSON.stringify(parsedData));
    } catch (err: any) {
      console.error("Weather fetch error:", err);
      debugInfo += `Error: ${err.message}\n`;

      if (triggerOverlay && !weatherData) {
        if (err.message?.includes("API key not valid") || err.message?.includes("INVALID_ARGUMENT")) {
          setWeatherError("Ongeldige API Key gedetecteerd. Selecteer a.u.b. een geldige key.");
        } else {
          setWeatherError("Kon live weerdata niet ophalen. Controleer uw verbinding of API key.");
        }
        setWeatherDebugLog(debugInfo);
      }
    } finally {
      setWeatherLoading(false);
    }
  }

  const handleWeatherClick = () => {
    const isStale = !weatherData || (weatherData.lastUpdated && Date.now() - weatherData.lastUpdated > CACHE_DURATION);
    setIsWeatherOpen(true);
    if (autoCloseTimer.current) window.clearTimeout(autoCloseTimer.current);
    autoCloseTimer.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);
    if (isStale) fetchWeatherForecast(true);
  };

  const formattedDate = currentDate.toLocaleDateString('nl-BE', {
    weekday: 'long',
    month: 'long',
    day: 'numeric'
  });

  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-[#fcfcfc] overflow-x-hidden relative touch-pan-y">
      <div className="absolute top-0 right-0 w-[1000px] h-[1000px] bg-blue-50/40 rounded-full blur-[150px] -z-10 translate-x-1/3 -translate-y-1/3" />

      {/* Header */}
      <header className="w-full px-[30px] pt-12 pb-8 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-100/60">
        <div className="space-y-6">
          <h1 className="text-6xl sm:text-8xl font-extralight tracking-tighter text-gray-900 leading-[0.95]">
            {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
            {user?.given_name ? <span className="text-gray-300">, {user.given_name}</span> : ''}
          </h1>
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3">
               <Clock className="w-5 h-5 text-gray-300" />
               <p className="text-gray-400 text-sm uppercase tracking-[0.4em] font-black">
                 {formattedDate}
               </p>
            </div>
            {accessToken && (
              <button 
                onClick={handleLogout}
                className="text-[11px] text-gray-300 hover:text-red-400 uppercase tracking-widest font-black transition-colors border-l border-gray-100 pl-8 touch-manipulation flex items-center gap-2"
              >
                Log uit
              </button>
            )}
          </div>
        </div>

        <div className="mt-12 md:mt-0 flex flex-col items-end gap-6">
          <div className="flex items-center gap-8">
            {!accessToken ? (
              <button 
                onClick={handleLogin}
                disabled={isSyncing}
                className={`flex items-center gap-4 px-10 py-5 bg-gray-900 text-white rounded-2xl shadow-xl hover:bg-black transition-all text-xs font-black uppercase tracking-[0.3em] active:scale-95 touch-manipulation ${isSyncing ? 'opacity-70 cursor-wait' : ''}`}
              >
                {isSyncing ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
                {isSyncing ? 'Verbinden...' : 'Google Sync'}
              </button>
            ) : (
              <div className="flex items-center gap-6 bg-white p-3 pr-8 rounded-[1.5rem] border border-gray-50 shadow-sm animate-in fade-in zoom-in-95 duration-300">
                <div className="w-12 h-12 bg-gray-100 rounded-2xl overflow-hidden shadow-inner border border-gray-50">
                   <img src={user?.picture} alt="" className="w-full h-full object-cover" />
                </div>
                <div className="text-right">
                  <div className="text-xs font-black text-gray-900 uppercase tracking-widest">{user?.name || 'Account'}</div>
                  <div className="text-[10px] text-green-500 font-bold flex items-center justify-end gap-2">
                    <CheckCircle2 size={10} className="text-green-500" />
                    LIVE SYNC
                  </div>
                </div>
              </div>
            )}
            <WeatherWidget 
              data={weatherData} 
              onClick={handleWeatherClick} 
              isRefreshing={weatherLoading && !!weatherData} 
            />
          </div>
          <div className="text-right px-2">
            <div className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em]">HERENTHOUT, BELGIË</div>
          </div>
        </div>
      </header>

      {/* Main Grid */}
      <main className="w-full px-[30px] py-12 grid grid-cols-1 xl:grid-cols-10 gap-8 items-start h-full">

        {/* Agenda - 80% span */}
        <section className="xl:col-span-8 h-full">
          <Calendar 
            accessToken={accessToken} 
            items={agendaItems} 
            isLoading={agendaLoading} 
            onRefresh={() => accessToken && fetchCalendarEvents(accessToken)}
          />
        </section>

        {/* Sidebar - 20% span */}
        <aside className="xl:col-span-2 space-y-8 flex flex-col h-full">
          <TaskWidget />
          <StockWidget />
          <div className="p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100 relative group overflow-hidden">
