          {accessToken && !isLoading && (
            <button 
              onClick={onRefresh}
              className="flex items-center gap-2 px-3 py-1 bg-blue-50 text-[10px] text-blue-600 font-black rounded-full uppercase tracking-widest border border-blue-100 hover:bg-blue-100 transition-colors"
            >
              <RefreshCw size={10} className={isLoading ? "animate-spin" : ""} />
