                  </div>

                  {/* Events List */}
                  <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-touch-scrollbar no-scrollbar">
                    {dayEvents.length === 0 ? (
                      <div className="h-full flex items-center justify-center">
