                            )}
                          </div>
                          <h4 className="text-2xl font-bold text-gray-800 leading-[1.15] group-hover:text-blue-600 transition-colors">
                            {item.title}
                          </h4>
                          {item.location && (
                            <div className="flex items-start gap-2 mt-4 opacity-50">
                              <MapPinned size={18} className="text-gray-400 shrink-0 mt-1" />
                              <span className="text-base font-bold text-gray-500 leading-tight">{item.location}</span>
                            </div>
                          )}
