// --- Main App ---
const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('hub_access_token'));
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const tokenClientRef = useRef<any>(null);

  const [agendaItems, setAgendaItems] = useState<AgendaItem[]>([]);
  const [agendaLoading, setAgendaLoading] = useState(false);

  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(() => {
    const cached = localStorage.getItem(WEATHER_CACHE_KEY);
    if (cached) {
      try { return JSON.parse(cached); } catch (e) { return null; }
    }
    return null;
  });
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [weatherError, setWeatherError] = useState<string | null>(null);
  const [weatherDebugLog, setWeatherDebugLog] = useState<string | null>(null);
  const autoCloseTimer = useRef<number | null>(null);

  useEffect(() => {
    const clockTimer = setInterval(() => setCurrentDate(new Date()), 60000);
    const initGsi = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: async (response: any) => {
            if (response.access_token) {
              setAccessToken(response.access_token);
              localStorage.setItem('hub_access_token', response.access_token);
              await fetchUserProfile(response.access_token);
              await fetchCalendarEvents(response.access_token);
            }
            setIsSyncing(false);
          },
        });
        if (accessToken) {
          fetchUserProfile(accessToken).catch(() => handleLogout());
          fetchCalendarEvents(accessToken).catch(() => handleLogout());
        }
      } else {
        setTimeout(initGsi, 500);
      }
    };
    initGsi();

    const cached = localStorage.getItem(WEATHER_CACHE_KEY);
    if (!cached || (JSON.parse(cached).lastUpdated && Date.now() - JSON.parse(cached).lastUpdated > CACHE_DURATION)) {
      fetchWeatherForecast(false);
    }

    return () => clearInterval(clockTimer);
  }, []);

  const handleLogin = () => {
    setIsSyncing(true);
    if (tokenClientRef.current) {
      tokenClientRef.current.requestAccessToken({ prompt: accessToken ? '' : 'select_account' });
    }
  };

  const handleLogout = () => {
    const oldToken = accessToken;
    setAccessToken(null);
    setUser(null);
    setAgendaItems([]);
    localStorage.removeItem('hub_access_token');
    if ((window as any).google) {
      (window as any).google.accounts.oauth2.revoke(oldToken || '', () => {});
    }
  };

  const fetchUserProfile = async (token: string) => {
    try {
      const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!resp.ok) throw new Error('Auth expired');
      const data = await resp.json();
      setUser({ given_name: data.given_name, name: data.name, picture: data.picture });
    } catch (err) { handleLogout(); }
  };

  const fetchCalendarEvents = async (token: string) => {
    setAgendaLoading(true);
    try {
      const now = new Date();
      const startOfWindow = new Date(now);
      startOfWindow.setHours(0, 0, 0, 0);

      const endOfWindow = new Date(now);
      endOfWindow.setDate(now.getDate() + 7);
      endOfWindow.setHours(23, 59, 59, 999);

      const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${startOfWindow.toISOString()}&timeMax=${endOfWindow.toISOString()}&singleEvents=true&orderBy=startTime`;
      const resp = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
      if (!resp.ok) throw new Error('Calendar fetch failed');
      const data = await resp.json();
      const mappedItems: AgendaItem[] = data.items.map((event: any) => {
        const startRaw = event.start.dateTime || event.start.date;
        const startDate = new Date(startRaw);

        // Handle time range: only for events that are NOT all-day
        let timeStr = '';
        if (event.start.dateTime && event.end.dateTime) {
          const startTime = new Date(event.start.dateTime).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit', hour12: false });
          const endTime = new Date(event.end.dateTime).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit', hour12: false });
          timeStr = `${startTime} - ${endTime}`;
        }

        let category: any = 'personal';
        const titleLower = (event.summary || '').toLowerCase();
        if (titleLower.includes('werk') || titleLower.includes('meeting')) category = 'work';
        else if (titleLower.includes('doktor') || titleLower.includes('sport')) category = 'health';
        else if (titleLower.includes('feest') || titleLower.includes('drink')) category = 'social';
        return { 
          id: event.id, 
          start: startDate, 
          time: timeStr, 
          title: event.summary || '(Geen titel)', 
          location: event.location || '', 
          category 
        };
      });
      setAgendaItems(mappedItems);
    } catch (err) { console.error(err); } finally { setAgendaLoading(false); }
  };

  async function fetchWeatherFallback() {
    const lat = 51.1378;
    const lon = 4.7570;
    const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&hourly=temperature_2m,weather_code&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=7`;
    const resp = await fetch(url);
    if (!resp.ok) throw new Error("Fallback fetch failed");
    const data = await resp.json();

    const days = ['Zondag', 'Maandag', 'Dinsdag', 'Woensdag', 'Donderdag', 'Vrijdag', 'Zaterdag'];
    const now = new Date();

    // Find index of the next hour
    const nextHourIndex = data.hourly.time.findIndex((t: string) => new Date(t) > now);
    const hourlyData = data.hourly.time.slice(nextHourIndex, nextHourIndex + 14).map((t: string, i: number) => {
      const info = getWeatherInfo(data.hourly.weather_code[nextHourIndex + i]);
      return {
        time: new Date(t).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit' }),
        temp: Math.round(data.hourly.temperature_2m[nextHourIndex + i]),
        icon: info.icon
      };
    });

    const currentInfo = getWeatherInfo(data.current.weather_code);

    return {
      location: "Herenthout",
      currentTemp: Math.round(data.current.temperature_2m),
      condition: currentInfo.text,
      humidity: data.current.relative_humidity_2m,
      windSpeed: `${Math.round(data.current.wind_speed_10m)} km/u`,
      sourceUrl: "https://www.meteo.be/nl/herenthout",
      lastUpdated: Date.now(),
      hourly: hourlyData,
      daily: data.daily.time.slice(0, 7).map((t: string, i: number) => {
        const info = getWeatherInfo(data.daily.weather_code[i]);
        return {
          day: days[new Date(t).getDay()],
          low: Math.round(data.daily.temperature_2m_min[i]),
          high: Math.round(data.daily.temperature_2m_max[i]),
          condition: info.text,
          icon: info.icon
        };
      })
    };
  }

  async function fetchWeatherForecast(triggerOverlay = true) {
    if (triggerOverlay) {
      setIsWeatherOpen(true);
      if (autoCloseTimer.current) window.clearTimeout(autoCloseTimer.current);
      autoCloseTimer.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);
    }
    setWeatherLoading(true);
    setWeatherError(null);

    let debug = `Fetch started: ${new Date().toISOString()}\n`;

    try {
      const apiKey = process.env.API_KEY || '';
      if (apiKey.length > 30) {
        debug += "Trying Gemini Search...\n";
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
          model: "gemini-3-flash-preview", 
          contents: `Haal de weersverwachting op voor Herenthout van https://www.meteo.be/nl/herenthout.
                     Return EXACT JSON: 
                     - Huidige temp, luchtvochtigheid, windsnelheid.
                     - 14 uurlijkse punten (START VANAF VOLGEND UUR).
                     - 7 dagelijkse punten met de dagnaam en een beschrijving (bijv. "Licht bewolkt").`,
          config: { tools: [{googleSearch: {}}], responseMimeType: "application/json" }
        });
        const parsed = JSON.parse(response.text || '{}');
        parsed.lastUpdated = Date.now();
        parsed.sourceUrl = "https://www.meteo.be/nl/herenthout";
        parsed.hourly = parsed.hourly.slice(0, 14);
        setWeatherData(parsed);
        localStorage.setItem(WEATHER_CACHE_KEY, JSON.stringify(parsed));
        setWeatherLoading(false);
        return;
      }
    } catch (e: any) { debug += `AI Error: ${e.message}\n`; }

    // FALLBACK
    try {
      debug += "Executing Fallback...\n";
      const data = await fetchWeatherFallback();
      setWeatherData(data);
      localStorage.setItem(WEATHER_CACHE_KEY, JSON.stringify(data));
      setWeatherError(null);
    } catch (err: any) {
      debug += `Final Error: ${err.message}\n`;
      if (!weatherData) setWeatherError("Meteo data niet beschikbaar.");
      setWeatherDebugLog(debug);
    } finally { setWeatherLoading(false); }
  }

  const handleWeatherClick = () => {
    fetchWeatherForecast(true);
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-[#fcfcfc] overflow-x-hidden relative">
      <div className="absolute top-0 right-0 w-[1000px] h-[1000px] bg-blue-50/40 rounded-full blur-[150px] -z-10 translate-x-1/3 -translate-y-1/3" />
      <header className="w-full px-[30px] pt-12 pb-8 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-100/60">
        <div className="space-y-6">
          <h1 className="text-6xl sm:text-8xl font-extralight tracking-tighter text-gray-900 leading-[0.95]">
            {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
            {user?.given_name ? <span className="text-gray-300">, {user.given_name}</span> : ''}
          </h1>
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3">
               <Clock className="w-5 h-5 text-gray-300" />
               <p className="text-gray-400 text-sm uppercase tracking-[0.4em] font-black">
                 {currentDate.toLocaleDateString('nl-BE', { weekday: 'long', month: 'long', day: 'numeric' })}
               </p>
            </div>
          </div>
        </div>
        <div className="mt-12 md:mt-0 flex flex-col items-end gap-6">
          <div className="flex items-center gap-8">
            {!accessToken ? (
              <button onClick={handleLogin} disabled={isSyncing} className="px-10 py-5 bg-gray-900 text-white rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl">
                {isSyncing ? 'Verbinden...' : 'Google Sync'}
              </button>
            ) : (
              <div className="flex items-center gap-6 bg-white p-3 pr-8 rounded-[1.5rem] border border-gray-50 shadow-sm">
                <div className="w-12 h-12 bg-gray-100 rounded-2xl overflow-hidden border border-gray-50">
                   <img src={user?.picture} alt="" className="w-full h-full object-cover" />
                </div>
                <div className="text-right">
                  <div className="text-xs font-black text-gray-900 uppercase tracking-widest">{user?.name}</div>
                  <div className="text-[10px] text-green-500 font-bold flex items-center justify-end gap-1"><CheckCircle2 size={10}/> LIVE</div>
                </div>
              </div>
            )}
            <WeatherWidget data={weatherData} onClick={handleWeatherClick} isRefreshing={weatherLoading && !!weatherData} />
          </div>
          <div className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em]">HERENTHOUT, BELGIË</div>
        </div>
      </header>
      <main className="w-full px-[30px] py-12 grid grid-cols-1 xl:grid-cols-10 gap-8 min-h-[700px]">
        <section className="xl:col-span-8 h-full">
          <Calendar accessToken={accessToken} items={agendaItems} isLoading={agendaLoading} onRefresh={() => accessToken && fetchCalendarEvents(accessToken)} />
        </section>
        <aside className="xl:col-span-2 space-y-8 flex flex-col h-full">
          <TaskWidget />
          <StockWidget />
          <div className="p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100">
            <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] block mb-6">Mantra</span>
            <p className="text-md font-light text-gray-500 leading-relaxed italic">"Focus op de voortgang, niet op de perfectie."</p>
          </div>
        </aside>
      </main>
      {isWeatherOpen && <WeatherOverlay onClose={() => setIsWeatherOpen(false)} weatherData={weatherData} loading={weatherLoading} error={weatherError} debugLog={weatherDebugLog} onRetry={() => fetchWeatherForecast(true)} />}
    </div>
  );
};

