            <div className="flex items-center gap-4">
              <div className={`w-14 h-14 rounded-2xl flex items-center justify-center ${data.isCharging ? 'bg-green-500/20 text-green-400' : 'bg-blue-500/20 text-blue-400'}`}>
                 <BatteryIcon size={28} />
              </div>
              <div>
                <span className="text-4xl font-black text-white leading-none">{data.soc}%</span>
