                  {data.isCharging ? 'Aan het opladen' : 'Batterij gebruik'}
                </span>
              </div>
            </div>
            <div className="text-right">
               <span className={`text-xl font-black ${data.isCharging ? 'text-green-400' : 'text-blue-300'}`}>
                 {Math.abs(data.batteryPower)}W
               </span>
               <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest block">Flow</span>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white/5 p-5 rounded-3xl border border-white/5">
               <div className="flex items-center gap-2 mb-2 text-yellow-400">
                 <Sun size={14} />
                 <span className="text-[9px] font-black uppercase tracking-widest">PV Opbrengst</span>
               </div>
               <div className="text-xl font-bold text-white">{data.pvYield}W</div>
            </div>
            <div className="bg-white/5 p-5 rounded-3xl border border-white/5">
