               <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Net Verbruik</span>
             </div>
             <div className={`text-lg font-black ${data.gridPower > 0 ? 'text-rose-400' : 'text-green-400'}`}>
               {data.gridPower}W
             </div>
          </div>
        </div>
      ) : null}
    </div>
  );
};

