  CheckCircle2, Bell, MapPinned, Copy, ClipboardCheck, Key,
  Zap, Battery as BatteryIcon, Home, Share2, Activity, AlertTriangle, LogOut
} from 'lucide-react';

// --- Constants & Types ---
const CLIENT_ID = '83368315587-g04nagjcgrsaotbdpet6gq2f7njrh2tu.apps.googleusercontent.com';
const SCOPES = 'https://www.googleapis.com/auth/calendar.readonly https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/drive.readonly';
const VICTRON_USER = 'stevenvw@gmail.com';
const VICTRON_FILENAME = 'victron_password.txt';

const WEATHER_CACHE_KEY = 'hub_weather_cache';

interface AgendaItem {
