  );
};

const VictronWidget = ({ data, isLoading, error, debugLog, onRetry, onLogout }: { data: VictronData | null; isLoading: boolean; error: string | null; debugLog: string | null; onRetry: () => void; onLogout: () => void }) => {
  const [copied, setCopied] = useState(false);

  const handleCopyLog = () => {
    if (debugLog) {
      navigator.clipboard.writeText(debugLog);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const isScopeError = error?.toLowerCase().includes('insufficient') || error?.toLowerCase().includes('scope');

  return (
    <div className="p-8 bg-gray-900 rounded-[2.5rem] shadow-2xl border border-gray-800 relative overflow-hidden group min-h-[300px] flex flex-col justify-center transition-all duration-500">
      <div className="absolute top-0 right-0 p-8 opacity-10">
        <Activity size={80} className="text-blue-400" />
      </div>
      <div className="flex justify-between items-start mb-6 relative z-10">
        <button 
          onClick={handleCopyLog}
          className="group/label flex flex-col items-start transition-all active:scale-95 touch-manipulation text-left"
