    case 'storm': return <CloudLightning className={className} />;
    case 'snow': return <CloudSnow className={className} />;
    case 'drizzle': return <CloudDrizzle className={className} />;
    default: return <Cloud className={className} />;
  }
};

const WeatherWidget = ({ data, onClick, isRefreshing }: { data: WeatherData | null, onClick: () => void, isRefreshing: boolean }) => (
  <button 
    onClick={onClick}
    className="flex items-center gap-6 px-8 py-5 bg-white border border-gray-100 rounded-2xl shadow-sm hover:border-blue-400 hover:shadow-xl transition-all group active:scale-95 touch-manipulation relative"
  >
    <div className="flex flex-col items-end">
      <span className="text-xl font-black text-gray-900 leading-none">
        {data ? `${data.currentTemp}°C` : '--°C'}
      </span>
      {data && (
        <div className="flex items-center gap-1.5 mt-1.5">
          <Wind size={10} className="text-blue-300" />
          <span className="text-[9px] text-gray-400 uppercase tracking-widest font-black">{data.windSpeed}</span>
        </div>
      )}
      <span className="text-[8px] text-gray-300 uppercase tracking-[0.2em] font-black mt-1">Herenthout</span>
    </div>
    <div className="w-14 h-14 bg-blue-50 rounded-2xl flex items-center justify-center group-hover:bg-blue-100 transition-colors">
      {isRefreshing ? (
        <RefreshCw className="w-6 h-6 text-blue-300 animate-spin" />
      ) : (
        <WeatherIcon type={data?.hourly[0]?.icon || 'cloud'} className="w-7 h-7 text-blue-400 group-hover:scale-110 transition-transform" />
      )}
    </div>
  </button>
);

const WeatherOverlay = ({ onClose, weatherData, loading, error, onRetry }: any) => {
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center animate-in fade-in duration-300">
      <div className="absolute inset-0 bg-white/40 backdrop-blur-[60px]" onClick={onClose} />
      <div className="relative w-full h-full bg-white/50 flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>
        <div className="p-[30px] flex justify-between items-center border-b border-gray-200/20 bg-white/30 backdrop-blur-xl shrink-0">
          <div className="flex items-center gap-6">
            <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center shadow-md border border-gray-50">
              <Clock className="w-7 h-7 text-blue-500" />
            </div>
            <div>
              <h3 className="text-2xl font-black text-gray-900 tracking-tight">{loading && !weatherData ? 'Laden...' : 'Weersverwachting'}</h3>
              <p className="text-xs text-gray-400 font-black uppercase tracking-[0.3em] mt-0.5 flex items-center gap-2">
                Herenthout, BE 
                <a href="https://www.meteo.be/nl/herenthout" target="_blank" rel="noreferrer" className="text-blue-400 hover:text-blue-600 flex items-center gap-1">Meteo.be <ExternalLink size={12}/></a>
              </p>
            </div>
          </div>
          <button onClick={onClose} className="w-16 h-16 flex items-center justify-center bg-gray-900 hover:bg-black rounded-[2rem] transition-all text-white shadow-2xl active:scale-90 touch-manipulation">
            <X className="w-8 h-8" />
          </button>
        </div>
        <div className="flex-1 overflow-y-auto p-[30px] space-y-24 scroll-smooth custom-touch-scrollbar pb-20">
          {loading && !weatherData ? (
            <div className="flex flex-col items-center justify-center py-40 gap-10">
              <Loader2 className="w-20 h-20 text-blue-500 animate-spin" />
              <p className="text-gray-900 text-xs font-black uppercase tracking-[0.5em] animate-pulse">Live Meteo ophalen...</p>
            </div>
          ) : error && !weatherData ? (
            <div className="text-center py-40 space-y-8">
              <X className="w-20 h-20 text-red-400 mx-auto" />
              <p className="text-gray-600 font-medium max-w-sm mx-auto text-lg">{error}</p>
              <button onClick={onRetry} className="px-12 py-6 bg-gray-900 text-white rounded-[2rem] text-xs font-black uppercase tracking-widest shadow-xl">Opnieuw proberen</button>
            </div>
          ) : weatherData && (
            <div className="w-full space-y-24">
              <div className="space-y-10">
                <div className="flex items-center gap-4 px-4"><div className="w-1.5 h-1.5 bg-blue-500 rounded-full" /><span className="text-sm text-gray-900 font-black uppercase tracking-[0.4em]">Komende uren</span></div>
                <div className="flex gap-4 overflow-x-auto pb-12 no-scrollbar px-4 snap-x">
                  {weatherData.hourly.map((h: any, i: number) => (
                    <div key={i} className="flex-shrink-0 w-28 sm:w-32 bg-white/60 border border-white p-6 sm:p-8 rounded-[2rem] flex flex-col items-center gap-6 hover:bg-white hover:shadow-2xl transition-all snap-start">
                      <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.1em]">{h.time}</span>
                      <WeatherIcon type={h.icon} className="w-10 h-10 text-blue-400" />
                      <span className="text-2xl font-light text-gray-900 tracking-tight">{h.temp}°</span>
                    </div>
                  ))}
                </div>
              </div>
              <div className="space-y-10">
                <div className="flex items-center gap-4 px-4"><div className="w-1.5 h-1.5 bg-blue-500 rounded-full" /><span className="text-sm text-gray-900 font-black uppercase tracking-[0.4em]">7-daagse Verwachting</span></div>
                <div className="flex xl:grid xl:grid-cols-7 gap-6 overflow-x-auto xl:overflow-visible pb-10 xl:pb-0 px-4">
                  {weatherData.daily.map((d: any, i: number) => (
                    <div key={i} className={`flex-shrink-0 w-[260px] xl:w-auto p-10 bg-white/40 border border-white rounded-[3.5rem] flex flex-col items-center gap-8 hover:bg-white transition-all ${i === 0 ? 'ring-2 ring-blue-100' : ''}`}>
                      <span className="text-[12px] font-black text-gray-800 tracking-widest">{i === 0 ? 'VANDAAG' : d.day.toUpperCase()}</span>
                      <WeatherIcon type={d.icon} className="w-16 h-16 text-blue-300 my-4" />
                      <div className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] text-center px-2 line-clamp-2 min-h-[3rem]">{d.condition}</div>
                      <div className="mt-4 flex items-center gap-6 border-t border-gray-100/50 pt-10 w-full justify-center">
                        <span className="text-3xl font-black text-gray-900">{d.high}°</span>
                        <span className="text-3xl font-light text-gray-300">{d.low}°</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// --- App Root ---
const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('hub_access_token'));
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [agendaItems, setAgendaItems] = useState<AgendaItem[]>([]);
  const [agendaLoading, setAgendaLoading] = useState(false);

  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(() => {
    const cached = localStorage.getItem(WEATHER_CACHE_KEY);
    return cached ? JSON.parse(cached) : null;
  });
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [weatherError, setWeatherError] = useState<string | null>(null);
  const weatherTimerRef = useRef<number | null>(null);

  const [victronData, setVictronData] = useState<VictronData | null>(null);
  const [victronLoading, setVictronLoading] = useState(false);
  const [victronError, setVictronError] = useState<string | null>(null);
  const [victronDebugLog, setVictronDebugLog] = useState<string | null>(null);
  const victronTimerRef = useRef<number | null>(null);

  const tokenClientRef = useRef<any>(null);

  useEffect(() => {
    const clockTimer = setInterval(() => setCurrentDate(new Date()), 60000);
    const initGsi = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: async (response: any) => {
            if (response.access_token) {
              setAccessToken(response.access_token);
              localStorage.setItem('hub_access_token', response.access_token);
              await fetchUserProfile(response.access_token);
              await fetchCalendarEvents(response.access_token);
              startVictronSync(response.access_token);
            }
            setIsSyncing(false);
          },
        });
        if (accessToken) {
          fetchUserProfile(accessToken).catch(() => handleLogout());
          fetchCalendarEvents(accessToken).catch(() => handleLogout());
          startVictronSync(accessToken);
        }
      } else { setTimeout(initGsi, 500); }
    };
    initGsi();
    if (!weatherData) fetchWeatherForecast(false);

    return () => {
      clearInterval(clockTimer);
      if (victronTimerRef.current) clearInterval(victronTimerRef.current);
      if (weatherTimerRef.current) clearTimeout(weatherTimerRef.current);
    };
  }, []);

  const handleLogin = () => { setIsSyncing(true); if (tokenClientRef.current) tokenClientRef.current.requestAccessToken({ prompt: accessToken ? '' : 'select_account' }); };
  const handleLogout = () => { localStorage.removeItem('hub_access_token'); setAccessToken(null); setUser(null); setAgendaItems([]); setVictronData(null); setVictronError(null); if (victronTimerRef.current) clearInterval(victronTimerRef.current); };

  const fetchUserProfile = async (token: string) => {
    const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', { headers: { Authorization: `Bearer ${token}` } });
    if (!resp.ok) throw new Error('Auth expired');
    const data = await resp.json();
    setUser({ given_name: data.given_name, name: data.name, picture: data.picture });
  };

  const fetchCalendarEvents = async (token: string) => {
    setAgendaLoading(true);
    try {
      const now = new Date();
      const start = new Date(now); start.setHours(0,0,0,0);
      const end = new Date(now); end.setDate(now.getDate() + 7); end.setHours(23,59,59,999);
      const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${start.toISOString()}&timeMax=${end.toISOString()}&singleEvents=true&orderBy=startTime`;
      const resp = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
      const data = await resp.json();
      const mapped = data.items.map((event: any) => {
        const startRaw = event.start.dateTime || event.start.date;
        const startDate = new Date(startRaw);
        let timeStr = '';
        if (event.start.dateTime && event.end.dateTime) {
          timeStr = `${new Date(event.start.dateTime).toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit', hour12:false})} - ${new Date(event.end.dateTime).toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit', hour12:false})}`;
        }
        const titleRaw = event.summary || '(Geen titel)';
        let cleaned = titleRaw;
        if (timeStr) {
          const timeRegex = /\b\d{1,2}[u:h:]\d{0,2}(\s*[-–]\s*\d{1,2}[u:h:]\d{0,2})?\b/gi;
          cleaned = titleRaw.replace(timeRegex, '').replace(/\(\s*\)/g, '').replace(/\[\s*\]/g, '').replace(/\s\s+/g, ' ').trim();
        }
        let category: any = 'personal';
        const low = titleRaw.toLowerCase();
        if (low.includes('werk') || low.includes('meeting')) category = 'work';
        else if (low.includes('doktor') || low.includes('sport')) category = 'health';
        else if (low.includes('feest') || low.includes('drink')) category = 'social';
        return { id: event.id, start: startDate, time: timeStr, title: cleaned, location: event.location || '', category };
      });
      setAgendaItems(mapped);
    } catch (e) { console.error(e); } finally { setAgendaLoading(false); }
  };

  async function fetchWeatherForecast(triggerOverlay = true) {
    if (triggerOverlay) {
      setIsWeatherOpen(true);
      if (weatherTimerRef.current) clearTimeout(weatherTimerRef.current);
      weatherTimerRef.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);
    }
    setWeatherLoading(true);
    try {
      const lat = 51.1378, lon = 4.7570;
      const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&hourly=temperature_2m,weather_code&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=7`;
      const resp = await fetch(url);
      const data = await resp.json();
      const days = ['Zondag', 'Maandag', 'Dinsdag', 'Woensdag', 'Donderdag', 'Vrijdag', 'Zaterdag'];
      const now = new Date();
      const nextHourIndex = data.hourly.time.findIndex((t: string) => new Date(t) > now);
      const hourlyData = data.hourly.time.slice(nextHourIndex, nextHourIndex + 14).map((t: string, i: number) => ({
        time: new Date(t).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit' }),
        temp: Math.round(data.hourly.temperature_2m[nextHourIndex + i]),
        icon: getWeatherInfo(data.hourly.weather_code[nextHourIndex + i]).icon
      }));
      const formatted = {
        location: "Herenthout",
        currentTemp: Math.round(data.current.temperature_2m),
        condition: getWeatherInfo(data.current.weather_code).text,
        humidity: data.current.relative_humidity_2m,
        windSpeed: `${Math.round(data.current.wind_speed_10m)} km/u`,
        lastUpdated: Date.now(),
        hourly: hourlyData,
        daily: data.daily.time.slice(0, 7).map((t: string, i: number) => {
          const info = getWeatherInfo(data.daily.weather_code[i]);
          return { day: days[new Date(t).getDay()], low: Math.round(data.daily.temperature_2m_min[i]), high: Math.round(data.daily.temperature_2m_max[i]), condition: info.text, icon: info.icon };
        })
      };
      setWeatherData(formatted);
      localStorage.setItem(WEATHER_CACHE_KEY, JSON.stringify(formatted));
    } catch (e) { setWeatherError("Meteo niet beschikbaar."); } finally { setWeatherLoading(false); }
  }

  const startVictronSync = async (googleToken: string) => {
    if (victronTimerRef.current) clearInterval(victronTimerRef.current);
    const sync = async () => {
      let log = `--- VICTRON SYNC LOG [${new Date().toISOString()}] ---\n`;
      try {
        if (!victronData) setVictronLoading(true);
        log += `1. Google Drive Check: Searching for '${VICTRON_FILENAME}'...\n`;
        const searchResp = await fetch(`https://www.googleapis.com/drive/v3/files?q=name='${VICTRON_FILENAME}'&fields=files(id,name)`, { headers: { Authorization: `Bearer ${googleToken}` } });
        if (!searchResp.ok) throw new Error(`Google Drive Search failed: ${searchResp.status}`);
        const searchData = await searchResp.json();
        if (!searchData.files?.[0]) throw new Error(`Bestand '${VICTRON_FILENAME}' niet gevonden.`);

        log += `2. Password Retrieval: Fetching file content (ID: ${searchData.files[0].id})...\n`;
        const contentResp = await fetch(`https://www.googleapis.com/drive/v3/files/${searchData.files[0].id}?alt=media`, { headers: { Authorization: `Bearer ${googleToken}` } });
        const password = (await contentResp.text()).trim();
        log += `   Password retrieved (${password.length} chars).\n`;

        log += `3. VRM Login: Authenticating ${VICTRON_USER}...\n`;
        const loginResp = await fetch('https://vrmapi.victronenergy.com/v2/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: VICTRON_USER, password }) });
        if (!loginResp.ok) throw new Error(`VRM Login failed: ${loginResp.status}`);
        const loginData = await loginResp.json();
        log += `   Auth successful (User ID: ${loginData.idUser}).\n`;

        log += `4. Site Discovery: Fetching installations...\n`;
        const instResp = await fetch(`https://vrmapi.victronenergy.com/v2/users/${loginData.idUser}/installations`, { headers: { 'X-Authorization': `Bearer ${loginData.token}` } });
        const site = (await instResp.json()).records?.[0];
        if (!site) throw new Error("Geen installatie gevonden.");
        log += `   Site found: ${site.name} (ID: ${site.idSite})\n`;

        log += `5. Data Acquisition: Prioritizing system-overview...\n`;
        const overviewResp = await fetch(`https://vrmapi.victronenergy.com/v2/installations/${site.idSite}/system-overview`, { headers: { 'X-Authorization': `Bearer ${loginData.token}` } });
        const overviewData = await overviewResp.json();

        // ADD FULL OVERVIEW TO LOG
        log += `\n--- FULL SYSTEM-OVERVIEW JSON ---\n${JSON.stringify(overviewData, null, 2)}\n`;

        let systemRecords = overviewData.records || overviewData.data || overviewData;

        if (!Array.isArray(systemRecords) || systemRecords.length === 0) {
            log += `\n   System-overview empty. Falling back to diagnostics...\n`;
            const diagResp = await fetch(`https://vrmapi.victronenergy.com/v2/installations/${site.idSite}/diagnostics`, { headers: { 'X-Authorization': `Bearer ${loginData.token}` } });
            const diagData = await diagResp.json();
            // ADD FULL DIAGNOSTICS TO LOG
            log += `\n--- FULL DIAGNOSTICS JSON ---\n${JSON.stringify(diagData, null, 2)}\n`;
            systemRecords = diagData.records || diagData.data || diagData;
        } else {
            // Even if overview exists, fetch diag for complete debug
            const diagResp = await fetch(`https://vrmapi.victronenergy.com/v2/installations/${site.idSite}/diagnostics`, { headers: { 'X-Authorization': `Bearer ${loginData.token}` } });
            const diagData = await diagResp.json();
            log += `\n--- FULL DIAGNOSTICS JSON (SUPPLEMENTAL) ---\n${JSON.stringify(diagData, null, 2)}\n`;
        }

        if (!Array.isArray(systemRecords)) {
           log += `   ERROR: Records are not an array.\n`;
           throw new Error("Ongeldige data structuur van Victron.");
        }

        log += `\n--- MAPPING ATTEMPTS ---\n`;

        const getRaw = (identifiers: string[]) => {
          const record = systemRecords.find((r: any) => 
            identifiers.some(id => 
              (r.code && r.code.toString().toLowerCase() === id.toLowerCase()) || 
              (r.id && r.id.toString() === id) || 
              (r.description && r.description.toString().toLowerCase() === id.toLowerCase()) ||
              (r.label && r.label.toString().toLowerCase() === id.toLowerCase())
            )
          );

          if (!record) {
              log += `   Mapping [${identifiers.join('/')}]: NOT FOUND\n`;
              return 0;
          }

          let val = record.value;
          if ((val === null || val === undefined) && record.formattedValue) {
              const cleaned = record.formattedValue.replace(/[^-0-9.]/g, '');
              val = parseFloat(cleaned);
              log += `   Mapping [${identifiers.join('/')}]: FOUND (${record.description || record.label || record.code}) via formattedValue [${record.formattedValue}] -> Result: ${val}\n`;
          } else {
              val = parseFloat(val);
              log += `   Mapping [${identifiers.join('/')}]: FOUND (${record.description || record.label || record.code}) via value -> Result: ${val}\n`;
          }

          return isNaN(val) ? 0 : val;
        };

        const soc = getRaw(['bs', '81', 'battery soc', 'soc', 'Battery SOC', 'Batterij-laadstatus']);
        const acLoad = getRaw(['cl', '142', 'consumption', 'ac load', 'AC Load', 'AC-belasting']);
        const pvYield = getRaw(['pv', '143', 'pv power', 'solar', 'PV Yield', 'PV-opbrengst']);
        const gridPower = getRaw(['gc', '144', 'grid', 'grid power', 'Grid Power', 'Net-stroom']);
        const batteryPower = getRaw(['bp', '84', 'battery power', 'Battery Power', 'Batterij-stroom']);

        setVictronData({
          soc: Math.round(soc), 
          acLoad: Math.round(acLoad), 
          pvYield: Math.round(pvYield), 
          gridPower: Math.round(gridPower), 
          batteryPower: Math.round(batteryPower), 
          isCharging: batteryPower > 0, 
          siteName: site.name
        });

        log += `\n--- SYNC SUCCESS ---\n`;
        setVictronError(null);
        setVictronDebugLog(log);
      } catch (e: any) { 
        log += `\n--- SYNC FAILED ---\nERROR: ${e.message}\n`;
        setVictronError(e.message); 
        setVictronDebugLog(log); 
      } finally { 
        setVictronLoading(false); 
      }
    };

    sync();
    victronTimerRef.current = window.setInterval(sync, 15000);
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-[#fcfcfc] overflow-x-hidden relative">
      <div className="absolute top-0 right-0 w-[1000px] h-[1000px] bg-blue-50/20 rounded-full blur-[120px] -z-10 translate-x-1/2 -translate-y-1/2 pointer-events-none" />
      <header className="w-full px-[30px] pt-12 pb-8 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-100/60">
        <div className="space-y-6">
          <h1 className="text-6xl sm:text-8xl font-extralight tracking-tighter text-gray-900 leading-[0.95]">
            {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
            {user?.given_name ? <span className="text-gray-300">, {user.given_name}</span> : ''}
          </h1>
          <div className="flex items-center gap-8"><Clock className="w-5 h-5 text-gray-300" /><p className="text-gray-400 text-sm uppercase tracking-[0.4em] font-black">{currentDate.toLocaleDateString('nl-BE', { weekday: 'long', month: 'long', day: 'numeric' })}</p></div>
        </div>
        <div className="mt-12 md:mt-0 flex flex-col items-end gap-6">
          <div className="flex items-center gap-8">
            {!accessToken ? (
              <button onClick={handleLogin} disabled={isSyncing} className="px-10 py-5 bg-gray-900 text-white rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl">{isSyncing ? 'Verbinden...' : 'Google Sync'}</button>
            ) : (
              <div className="flex items-center gap-6 bg-white p-3 pr-8 rounded-[1.5rem] border border-gray-50 shadow-sm cursor-pointer group" onClick={handleLogout}>
                <div className="w-12 h-12 bg-gray-100 rounded-2xl overflow-hidden border border-gray-50 group-hover:opacity-80 transition-opacity">
                  <img src={user?.picture} alt="" className="w-full h-full object-cover" />
                </div>
                <div className="text-right">
                  <div className="text-xs font-black text-gray-900 uppercase tracking-widest">{user?.name}</div>
                  <div className="text-[10px] text-green-500 font-bold flex items-center justify-end gap-1"><CheckCircle2 size={10}/> ONLINE</div>
                </div>
              </div>
            )}
            <WeatherWidget data={weatherData} onClick={() => fetchWeatherForecast(true)} isRefreshing={weatherLoading} />
          </div>
          <div className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em]">HERENTHOUT, BELGIË</div>
        </div>
      </header>
      <main className="w-full px-[30px] py-12 grid grid-cols-1 xl:grid-cols-10 gap-8 min-h-[700px]">
        <section className="xl:col-span-8 h-full">
          <Calendar accessToken={accessToken} items={agendaItems} isLoading={agendaLoading} onRefresh={() => accessToken && fetchCalendarEvents(accessToken)} />
        </section>
        <aside className="xl:col-span-2 space-y-8 flex flex-col h-full">
          <VictronWidget data={victronData} isLoading={victronLoading} error={victronError} debugLog={victronDebugLog} onRetry={() => accessToken && startVictronSync(accessToken)} onLogout={handleLogout} />
          <TaskWidget />
          <div className="p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100 mt-auto">
            <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] block mb-6">Inspiratie</span>
            <p className="text-md font-light text-gray-500 leading-relaxed italic">"Focus op de voortgang, niet op de perfectie."</p>
          </div>
        </aside>
      </main>
      {isWeatherOpen && <WeatherOverlay onClose={() => setIsWeatherOpen(false)} weatherData={weatherData} loading={weatherLoading} error={weatherError} onRetry={() => fetchWeatherForecast(true)} />}
    </div>
  );
