// --- App Root ---
const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('hub_access_token'));
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [agendaItems, setAgendaItems] = useState<AgendaItem[]>([]);
  const [agendaLoading, setAgendaLoading] = useState(false);

  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(() => {
    const cached = localStorage.getItem(WEATHER_CACHE_KEY);
    return cached ? JSON.parse(cached) : null;
  });
  const [weatherLoading, setWeatherLoading] = useState(false);
  const weatherTimerRef = useRef<number | null>(null);

  const [isEnergyOpen, setIsEnergyOpen] = useState(false);
  const [victronData, setVictronData] = useState<VictronData | null>(null);
  const [victronLoading, setVictronLoading] = useState(false);
  const [victronError, setVictronError] = useState<string | null>(null);
  const energyTimerRef = useRef<number | null>(null);
  const victronSyncTimerRef = useRef<number | null>(null);

  const tokenClientRef = useRef<any>(null);

  useEffect(() => {
    const clockTimer = setInterval(() => setCurrentDate(new Date()), 60000);
    const initGsi = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: async (response: any) => {
            if (response.access_token) {
              setAccessToken(response.access_token);
              localStorage.setItem('hub_access_token', response.access_token);
              await fetchUserProfile(response.access_token);
              await fetchCalendarEvents(response.access_token);
              startVictronSync(response.access_token);
            }
            setIsSyncing(false);
          },
        });
        if (accessToken) {
          fetchUserProfile(accessToken).catch(() => handleLogout());
          fetchCalendarEvents(accessToken).catch(() => handleLogout());
          startVictronSync(accessToken);
        }
      } else { setTimeout(initGsi, 500); }
    };
    initGsi();
    if (!weatherData) fetchWeatherForecast(false);

    return () => {
      clearInterval(clockTimer);
      if (victronSyncTimerRef.current) clearInterval(victronSyncTimerRef.current);
      if (weatherTimerRef.current) clearTimeout(weatherTimerRef.current);
      if (energyTimerRef.current) clearTimeout(energyTimerRef.current);
    };
  }, []);

  const handleLogin = () => { setIsSyncing(true); if (tokenClientRef.current) tokenClientRef.current.requestAccessToken({ prompt: accessToken ? '' : 'select_account' }); };
  const handleLogout = () => { localStorage.removeItem('hub_access_token'); setAccessToken(null); setUser(null); setAgendaItems([]); setVictronData(null); setVictronError(null); if (victronSyncTimerRef.current) clearInterval(victronSyncTimerRef.current); };

  const fetchUserProfile = async (token: string) => {
    const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', { headers: { Authorization: `Bearer ${token}` } });
    if (!resp.ok) throw new Error('Auth expired');
    const data = await resp.json();
    setUser({ given_name: data.given_name, name: data.name, picture: data.picture });
  };

  const fetchCalendarEvents = async (token: string) => {
    setAgendaLoading(true);
    try {
      const now = new Date();
      const start = new Date(now); start.setHours(0,0,0,0);
      const end = new Date(now); end.setDate(now.getDate() + 7); end.setHours(23,59,59,999);
      const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${start.toISOString()}&timeMax=${end.toISOString()}&singleEvents=true&orderBy=startTime`;
      const resp = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
      const data = await resp.json();
      const mapped = data.items.map((event: any) => {
        const startRaw = event.start.dateTime || event.start.date;
        const startDate = new Date(startRaw);
        let timeStr = '';
        if (event.start.dateTime && event.end.dateTime) {
          timeStr = `${new Date(event.start.dateTime).toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit', hour12:false})} - ${new Date(event.end.dateTime).toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit', hour12:false})}`;
        }
        const titleRaw = event.summary || '(Geen titel)';
        let cleaned = titleRaw;
        if (timeStr) {
          const timeRegex = /\b\d{1,2}[u:h:]\d{0,2}(\s*[-–]\s*\d{1,2}[u:h:]\d{0,2})?\b/gi;
          cleaned = titleRaw.replace(timeRegex, '').replace(/\(\s*\)/g, '').replace(/\[\s*\]/g, '').replace(/\s\s+/g, ' ').trim();
        }
        let category: any = 'personal';
        const low = titleRaw.toLowerCase();
        if (low.includes('werk') || low.includes('meeting')) category = 'work';
        else if (low.includes('doktor') || low.includes('sport')) category = 'health';
        else if (low.includes('feest') || low.includes('drink')) category = 'social';
        return { id: event.id, start: startDate, time: timeStr, title: cleaned, location: event.location || '', category };
      });
      setAgendaItems(mapped);
    } catch (e) { console.error(e); } finally { setAgendaLoading(false); }
  };

  async function fetchWeatherForecast(triggerOverlay = true) {
    if (triggerOverlay) {
      setIsWeatherOpen(true);
      if (weatherTimerRef.current) clearTimeout(weatherTimerRef.current);
      weatherTimerRef.current = window.setTimeout(() => setIsWeatherOpen(false), 180000);
    }
    setWeatherLoading(true);
    try {
      const lat = 51.1378, lon = 4.7570;
      const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&hourly=temperature_2m,weather_code&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=7`;
      const resp = await fetch(url);
      const data = await resp.json();
      const days = ['Zondag', 'Maandag', 'Dinsdag', 'Woensdag', 'Donderdag', 'Vrijdag', 'Zaterdag'];
      const now = new Date();
      const nextHourIndex = data.hourly.time.findIndex((t: string) => new Date(t) > now);
      const hourlyData = data.hourly.time.slice(nextHourIndex, nextHourIndex + 12).map((t: string, i: number) => ({
        time: new Date(t).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit' }),
        temp: Math.round(data.hourly.temperature_2m[nextHourIndex + i]),
        icon: getWeatherInfo(data.hourly.weather_code[nextHourIndex + i]).icon
      }));
      const formatted = {
        location: "Herenthout",
        currentTemp: Math.round(data.current.temperature_2m),
        condition: getWeatherInfo(data.current.weather_code).text,
        humidity: data.current.relative_humidity_2m,
        windSpeed: `${Math.round(data.current.wind_speed_10m)} km/u`,
        lastUpdated: Date.now(),
        hourly: hourlyData,
        daily: data.daily.time.slice(0, 7).map((t: string, i: number) => {
          const info = getWeatherInfo(data.daily.weather_code[i]);
          return { day: days[new Date(t).getDay()], low: Math.round(data.daily.temperature_2m_min[i]), high: Math.round(data.daily.temperature_2m_max[i]), condition: info.text, icon: info.icon };
        })
      };
      setWeatherData(formatted);
      localStorage.setItem(WEATHER_CACHE_KEY, JSON.stringify(formatted));
    } catch (e) { console.error(e); } finally { setWeatherLoading(false); }
  }

  const startVictronSync = async (googleToken: string) => {
    if (victronSyncTimerRef.current) clearInterval(victronSyncTimerRef.current);
    const sync = async () => {
      try {
        if (!victronData) setVictronLoading(true);
        const searchResp = await fetch(`https://www.googleapis.com/drive/v3/files?q=name='${VICTRON_FILENAME}'&fields=files(id,name)`, { headers: { Authorization: `Bearer ${googleToken}` } });
        const searchData = await searchResp.json();
        if (!searchData.files?.[0]) throw new Error("Victron paswoord bestand niet gevonden.");
        const contentResp = await fetch(`https://www.googleapis.com/drive/v3/files/${searchData.files[0].id}?alt=media`, { headers: { Authorization: `Bearer ${googleToken}` } });
        const password = (await contentResp.text()).trim();
        const loginResp = await fetch('https://vrmapi.victronenergy.com/v2/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: VICTRON_USER, password }) });
        const loginData = await loginResp.json();
        if (!loginData.token) throw new Error("Victron login mislukt.");
        const instResp = await fetch(`https://vrmapi.victronenergy.com/v2/users/${loginData.idUser}/installations`, { headers: { 'X-Authorization': `Bearer ${loginData.token}` } });
        const site = (await instResp.json()).records?.[0];
        if (!site) throw new Error("Geen installatie gevonden.");
        const diagResp = await fetch(`https://vrmapi.victronenergy.com/v2/installations/${site.idSite}/diagnostics`, { headers: { 'X-Authorization': `Bearer ${loginData.token}` } });
        const diagData = await diagResp.json();
        const records = diagData.records || [];

        const getVal = (code: string, device = "System overview") => {
            const r = records.find((rec: any) => rec.Device === device && rec.code === code);
            if (!r) return 0;
            return parseFloat(r.rawValue !== undefined ? r.rawValue : r.value) || 0;
        };

        const soc = getVal('bs');
        const acLoadTotal = getVal('a1'); 
        const pvYieldAC = getVal('P'); 
        const pvYieldDC = getVal('Pdc');
        const gridPower = getVal('g1');
        const batteryPower = getVal('bp');
        const evPower = getVal('evp', 'EV Charging Station');

        setVictronData({
          soc: Math.round(soc), 
          acLoad: Math.round(acLoadTotal - evPower), // Diagram treats EVCS separately
          pvYieldAC: Math.round(pvYieldAC),
          pvYieldDC: Math.round(pvYieldDC),
          gridPower: Math.round(gridPower), 
          batteryPower: Math.round(batteryPower), 
          evPower: Math.round(evPower),
          isCharging: batteryPower > 0, 
          siteName: site.name
        });
        setVictronError(null);
      } catch (e: any) { setVictronError(e.message); } finally { setVictronLoading(false); }
    };
    sync();
    victronSyncTimerRef.current = window.setInterval(sync, 15000);
  };

  const handleEnergyClick = () => {
    setIsEnergyOpen(true);
