} from 'lucide-react';

// --- Constants & Types ---
const CLIENT_ID = '83368315587-g04nagjcgrsaotbdpet6gq2f7njrh2tu.apps.googleusercontent.com';
const SCOPES = 'https://www.googleapis.com/auth/calendar.readonly https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/drive.readonly';
const VICTRON_USER = 'stevenvw@gmail.com';
const VICTRON_FILENAME = 'victron_password.txt';

const WEATHER_CACHE_KEY = 'hub_weather_cache';

interface AgendaItem {
  id: string;
  start: Date;
  time: string;
  title: string;
  location: string;
  category: 'work' | 'personal' | 'health' | 'social';
}

interface WeatherData {
  location: string;
  currentTemp: number;
  condition: string;
  humidity: number;
  windSpeed: string;
  sourceUrl?: string;
  lastUpdated?: number;
  hourly: { time: string; temp: number; icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle' }[];
  daily: { day: string; low: number; high: number; condition: string; icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle' }[];
}

interface VictronData {
  soc: number;
  acLoad: number;
  pvYieldAC: number;
  pvYieldDC: number;
  gridPower: number;
  batteryPower: number;
  evPower: number;
  isCharging: boolean;
  siteName: string;
}

// --- Weather Helpers ---
const getWeatherInfo = (code: number): { icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle', text: string } => {
  if (code === 0) return { icon: 'sun', text: 'Zonnig' };
  if (code === 1) return { icon: 'sun', text: 'Helder' };
  if (code === 2) return { icon: 'cloud', text: 'Licht bewolkt' };
  if (code === 3) return { icon: 'cloud', text: 'Bewolkt' };
  if ([45, 48].includes(code)) return { icon: 'cloud', text: 'Mistig' };
  if ([51, 53, 55, 56, 57].includes(code)) return { icon: 'drizzle', text: 'Motregen' };
  if ([61, 63, 65, 66, 67].includes(code)) return { icon: 'rain', text: 'Regen' };
  if ([71, 73, 75, 77].includes(code)) return { icon: 'snow', text: 'Sneeuw' };
  if ([80, 81, 82].includes(code)) return { icon: 'rain', text: 'Regenbuien' };
  if ([85, 86].includes(code)) return { icon: 'snow', text: 'Sneeuwbuien' };
  if ([95, 96, 99].includes(code)) return { icon: 'storm', text: 'Onweer' };
  return { icon: 'cloud', text: 'Bewolkt' };
};

// --- Components ---
const Calendar = ({ accessToken, items, isLoading, onRefresh }: { accessToken: string | null; items: AgendaItem[]; isLoading: boolean; onRefresh: () => void; }) => {
  const categories = { work: 'bg-blue-500', personal: 'bg-emerald-500', health: 'bg-rose-500', social: 'bg-amber-500' };
  const weekDays = useMemo(() => Array.from({ length: 7 }, (_, i) => { const d = new Date(); d.setDate(d.getDate() + i); return d; }), []);
  const getEventsForDay = (date: Date) => items.filter(item => { const d = item.start; return d.getDate() === date.getDate() && d.getMonth() === date.getMonth() && d.getFullYear() === date.getFullYear(); });

  return (
    <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-gray-100 flex flex-col h-full transition-all duration-500 overflow-hidden">
      <div className="flex justify-between items-center mb-8 shrink-0">
        <div className="flex items-center gap-4">
          <h2 className="text-3xl font-light text-gray-800 tracking-tight">Week Agenda</h2>
          {accessToken && !isLoading && (
            <button onClick={onRefresh} className="flex items-center gap-2 px-3 py-1 bg-blue-50 text-[10px] text-blue-600 font-black rounded-full uppercase tracking-widest border border-blue-100 hover:bg-blue-100 transition-colors">
              <RefreshCw size={10} className={isLoading ? "animate-spin" : ""} /> Verversen
            </button>
          )}
        </div>
        <div className="text-xs font-black text-gray-300 uppercase tracking-[0.3em]">Komende 7 dagen</div>
      </div>
      <div className="flex-1 overflow-hidden">
        {!accessToken ? (
          <div className="h-full flex flex-col items-center justify-center text-center space-y-6 px-6 opacity-40">
            <div className="w-20 h-20 bg-blue-50 rounded-3xl flex items-center justify-center mb-2">
               <CalendarIcon className="w-10 h-10 text-blue-300" />
            </div>
            <p className="text-gray-500 text-lg font-medium max-w-sm">Synchroniseer met Google Agenda om je weekplanning te zien</p>
          </div>
        ) : isLoading ? (
          <div className="h-full flex flex-col items-center justify-center space-y-6">
            <Loader2 className="w-12 h-12 text-blue-400 animate-spin" />
            <p className="text-xs text-gray-400 font-black uppercase tracking-[0.3em] animate-pulse">Agenda ophalen...</p>
          </div>
        ) : (
          <div className="grid grid-cols-7 h-full gap-px bg-gray-100 border border-gray-100 rounded-3xl overflow-hidden">
            {weekDays.map((date, idx) => {
              const dayEvents = getEventsForDay(date);
              const dayLabel = date.toLocaleDateString('nl-BE', { weekday: 'short' }).toUpperCase();
              const dateLabel = date.getDate();
              const today = new Date().toDateString() === date.toDateString();
              return (
                <div key={idx} className={`bg-white flex flex-col min-w-0 ${today ? 'bg-blue-50/20' : ''}`}>
                  <div className={`p-4 text-center border-b border-gray-50 ${today ? 'bg-blue-500/5' : ''}`}>
                    <div className={`text-[10px] font-black tracking-widest ${today ? 'text-blue-600' : 'text-gray-400'}`}>{dayLabel}</div>
                    <div className={`text-xl font-black mt-0.5 ${today ? 'text-blue-600' : 'text-gray-800'}`}>{dateLabel}</div>
