              <span className="text-xl font-black text-blue-500">%</span>
            </div>
            {/* AC Power (House) next to battery percentage - Small version */}
            <div className="flex items-center gap-2 px-3 py-1.5 bg-white/10 rounded-2xl border border-white/10">
              <Home size={12} className="text-emerald-400" />
              <span className="text-[11px] font-black text-emerald-400">
                {data.acLoad}W
              </span>
            </div>
          </div>

          {/* Detailed metrics grid - 4 items */}
          <div className="grid grid-cols-2 gap-3">
             {/* Battery Power */}
             <div className="flex items-center gap-2 px-3 py-1.5 bg-white/5 rounded-2xl border border-white/5">
                {data.isCharging ? <ArrowUpRight size={12} className="text-green-400" /> : <ArrowDownLeft size={12} className="text-blue-400" />}
                <span className={`text-[11px] font-black ${data.isCharging ? 'text-green-400' : 'text-blue-400'}`}>
                  {Math.abs(data.batteryPower)}W
                </span>
             </div>
             {/* Solar Power */}
             <div className="flex items-center gap-2 px-3 py-1.5 bg-white/5 rounded-2xl border border-white/5">
                <Sun size={12} className="text-amber-400" />
                <span className="text-[11px] font-black text-amber-400">
                  {data.pvYieldAC + data.pvYieldDC}W
                </span>
             </div>
             {/* Grid Power */}
             <div className="flex items-center gap-2 px-3 py-1.5 bg-white/5 rounded-2xl border border-white/5">
                <UtilityPole size={12} className="text-rose-400" />
                <span className="text-[11px] font-black text-rose-400">
                  {data.gridPower}W
                </span>
             </div>
             {/* EV Power */}
             <div className="flex items-center gap-2 px-3 py-1.5 bg-white/5 rounded-2xl border border-white/5">
                <Car size={12} className="text-blue-400" />
                <span className="text-[11px] font-black text-blue-400">
                  {data.evPower}W
                </span>
             </div>
          </div>
        </div>
      ) : null}
    </div>
  );
};

