import React, { useState, useEffect, useRef, useMemo } from 'react';
import { createRoot } from 'react-dom/client';
import { 
  Cloud, Sun, CloudRain, CloudLightning, Wind, X, 
  MapPin, Clock, Calendar as CalendarIcon, 
  CloudSnow, CloudDrizzle, Loader2, Droplets, ExternalLink, RefreshCw,
  CheckCircle2, Bell, MapPinned, Copy, ClipboardCheck, Key,
  Zap, Battery as BatteryIcon, Home, Share2, Activity, AlertTriangle, LogOut,
  ArrowUpRight, ArrowDownLeft, Cpu, Car, UtilityPole, FileText
} from 'lucide-react';

// --- Constants & Types ---
const CLIENT_ID = '83368315587-g04nagjcgrsaotbdpet6gq2f7njrh2tu.apps.googleusercontent.com';
const SCOPES = 'https://www.googleapis.com/auth/calendar.readonly https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/drive.readonly';
const VICTRON_USER = 'stevenvw@gmail.com';
const VICTRON_FILENAME = 'victron_password.txt';

const WEATHER_CACHE_KEY = 'hub_weather_cache';

interface AgendaItem {
  id: string;
  start: Date;
  time: string;
  title: string;
  location: string;
  category: 'work' | 'personal' | 'health' | 'social';
}

interface WeatherData {
  location: string;
  currentTemp: number;
  condition: string;
  humidity: number;
  windSpeed: string;
  sourceUrl?: string;
  lastUpdated?: number;
  hourly: { time: string; temp: number; icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle' }[];
  daily: { day: string; low: number; high: number; condition: string; icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle' }[];
}

interface VictronData {
  soc: number;
  acLoad: number;
  pvYieldAC: number;
  pvYieldDC: number;
  gridPower: number;
  batteryPower: number;
  evPower: number;
  isCharging: boolean;
  siteName: string;
}

// --- Weather Helpers ---
const getWeatherInfo = (code: number): { icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle', text: string } => {
  if (code === 0) return { icon: 'sun', text: 'Zonnig' };
  if (code === 1) return { icon: 'sun', text: 'Helder' };
  if (code === 2) return { icon: 'cloud', text: 'Licht bewolkt' };
  if (code === 3) return { icon: 'cloud', text: 'Bewolkt' };
  if ([45, 48].includes(code)) return { icon: 'cloud', text: 'Mistig' };
  if ([51, 53, 55, 56, 57].includes(code)) return { icon: 'drizzle', text: 'Motregen' };
  if ([61, 63, 65, 66, 67].includes(code)) return { icon: 'rain', text: 'Regen' };
  if ([71, 73, 75, 77].includes(code)) return { icon: 'snow', text: 'Sneeuw' };
  if ([80, 81, 82].includes(code)) return { icon: 'rain', text: 'Regenbuien' };
  if ([85, 86].includes(code)) return { icon: 'snow', text: 'Sneeuwbuien' };
  if ([95, 96, 99].includes(code)) return { icon: 'storm', text: 'Onweer' };
  return { icon: 'cloud', text: 'Bewolkt' };
};

// --- Components ---
const Calendar = ({ accessToken, items, isLoading, onRefresh }: { accessToken: string | null; items: AgendaItem[]; isLoading: boolean; onRefresh: () => void; }) => {
  const categories = { work: 'bg-blue-500', personal: 'bg-emerald-500', health: 'bg-rose-500', social: 'bg-amber-500' };
  const weekDays = useMemo(() => Array.from({ length: 7 }, (_, i) => { const d = new Date(); d.setDate(d.getDate() + i); return d; }), []);
  const getEventsForDay = (date: Date) => items.filter(item => { const d = item.start; return d.getDate() === date.getDate() && d.getMonth() === date.getMonth() && d.getFullYear() === date.getFullYear(); });

  return (
    <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-gray-100 flex flex-col h-full transition-all duration-500 overflow-hidden">
      <div className="flex justify-between items-center mb-8 shrink-0">
        <div className="flex items-center gap-4">
          <h2 className="text-3xl font-light text-gray-800 tracking-tight">Week Agenda</h2>
          {accessToken && !isLoading && (
            <button onClick={onRefresh} className="flex items-center gap-2 px-3 py-1 bg-blue-50 text-[10px] text-blue-600 font-black rounded-full uppercase tracking-widest border border-blue-100 hover:bg-blue-100 transition-colors">
              <RefreshCw size={10} className={isLoading ? "animate-spin" : ""} /> Verversen
            </button>
          )}
        </div>
        <div className="text-xs font-black text-gray-300 uppercase tracking-[0.3em]">Komende 7 dagen</div>
      </div>
      <div className="flex-1 overflow-hidden">
        {!accessToken ? (
          <div className="h-full flex flex-col items-center justify-center text-center space-y-6 px-6 opacity-40">
            <div className="w-20 h-20 bg-blue-50 rounded-3xl flex items-center justify-center mb-2">
               <CalendarIcon className="w-10 h-10 text-blue-300" />
            </div>
            <p className="text-gray-500 text-lg font-medium max-w-sm">Synchroniseer met Google Agenda om je weekplanning te zien</p>
          </div>
        ) : isLoading ? (
          <div className="h-full flex flex-col items-center justify-center space-y-6">
            <Loader2 className="w-12 h-12 text-blue-400 animate-spin" />
            <p className="text-xs text-gray-400 font-black uppercase tracking-[0.3em] animate-pulse">Agenda ophalen...</p>
          </div>
        ) : (
          <div className="grid grid-cols-7 h-full gap-px bg-gray-100 border border-gray-100 rounded-3xl overflow-hidden">
            {weekDays.map((date, idx) => {
              const dayEvents = getEventsForDay(date);
              const dayLabel = date.toLocaleDateString('nl-BE', { weekday: 'short' }).toUpperCase();
              const dateLabel = date.getDate();
              const today = new Date().toDateString() === date.toDateString();
              return (
                <div key={idx} className={`bg-white flex flex-col min-w-0 ${today ? 'bg-blue-50/20' : ''}`}>
                  <div className={`p-4 text-center border-b border-gray-50 ${today ? 'bg-blue-500/5' : ''}`}>
                    <div className={`text-[10px] font-black tracking-widest ${today ? 'text-blue-600' : 'text-gray-400'}`}>{dayLabel}</div>
                    <div className={`text-xl font-black mt-0.5 ${today ? 'text-blue-600' : 'text-gray-800'}`}>{dateLabel}</div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-6 no-scrollbar">
                    {dayEvents.length === 0 ? (
                      <div className="h-full flex items-center justify-center">
                        <span className="text-[12px] font-black text-gray-200 uppercase tracking-widest rotate-[-90deg]">Vrij</span>
                      </div>
                    ) : (
                      dayEvents.map((item) => (
                        <div key={item.id} className="group bg-gray-50/50 hover:bg-white p-6 rounded-[2rem] border border-transparent hover:border-gray-100 hover:shadow-xl hover:shadow-gray-200/40 transition-all duration-300 cursor-default">
                          <div className="flex items-center gap-1.5 mb-1.5">
                            <div className={`w-1.5 h-1.5 rounded-full ${categories[item.category] || 'bg-gray-300'} shrink-0`} />
                            {item.time ? <span className="text-xl font-black text-gray-900 leading-none tracking-tight">{item.time}</span> : <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">Hele dag</span>}
                          </div>
                          <h4 className="text-2xl font-bold text-gray-800 leading-[1.15] group-hover:text-blue-600 transition-colors">{item.title}</h4>
                          {item.location && (
                            <div className="flex items-start gap-2 mt-4 opacity-50">
                              <MapPinned size={18} className="text-gray-400 shrink-0 mt-1" />
                              <span className="text-base font-bold text-gray-500 leading-tight">{item.location}</span>
                            </div>
                          )}
                        </div>
                      ))
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

const VictronDebugOverlay = ({ isOpen, onClose, log }: { isOpen: boolean, onClose: () => void, log: string | null }) => {
  const [copied, setCopied] = useState(false);
  if (!isOpen) return null;

  const handleCopy = () => {
    if (log) {
      navigator.clipboard.writeText(log);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="fixed inset-0 z-[400] flex items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-xl" onClick={onClose} />
      <div className="relative w-full max-w-5xl h-[90vh] bg-gray-900 rounded-[3rem] border border-white/10 shadow-2xl flex flex-col overflow-hidden">
        <div className="p-10 border-b border-white/5 flex items-center justify-between shrink-0 bg-gray-900/50 backdrop-blur-md">
          <div className="flex items-center gap-6">
            <div className="w-14 h-14 bg-blue-500/10 rounded-2xl flex items-center justify-center border border-blue-500/20">
              <FileText className="text-blue-400 w-7 h-7" />
            </div>
            <div>
              <h3 className="text-2xl font-black text-white tracking-tight">Victron RAW Debug Log</h3>
              <p className="text-[10px] text-gray-500 uppercase tracking-[0.3em] font-black mt-1">Full API Response Dump</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button 
              onClick={handleCopy} 
              className={`flex items-center gap-3 px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest transition-all active:scale-95 touch-manipulation shadow-lg ${copied ? 'bg-green-500 text-white' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
            >
              {copied ? <CheckCircle2 size={16} /> : <ClipboardCheck size={16} />}
              {copied ? 'Gekopieerd!' : 'Kopieer Log'}
            </button>
            <button onClick={onClose} className="w-14 h-14 bg-white/5 hover:bg-white/10 rounded-2xl flex items-center justify-center text-gray-400 transition-colors">
              <X size={28} />
            </button>
          </div>
        </div>
        <div className="flex-1 overflow-auto p-10 font-mono text-[12px] leading-relaxed text-blue-200/90 bg-black/40 custom-touch-scrollbar">
          <pre 
            className="whitespace-pre-wrap break-all" 
            style={{ userSelect: 'text', WebkitUserSelect: 'text', cursor: 'text' }}
          >
            {log || 'Geen log data beschikbaar. Wacht op volgende sync...'}
          </pre>
        </div>
      </div>
    </div>
  );
};

const EnergyOverlay = ({ data, onClose }: { data: VictronData | null; onClose: () => void }) => {
  if (!data) return null;

  const Block = ({ title, value, unit, icon: Icon, colorClass, subValue }: any) => (
    <div className={`bg-white rounded-[2rem] p-6 shadow-xl border border-gray-100 w-48 transition-all hover:scale-105`}>
      <div className="flex items-center gap-2 mb-2">
        <div className={`w-8 h-8 rounded-lg ${colorClass} flex items-center justify-center text-white`}>
          <Icon size={16} />
        </div>
        <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{title}</span>
      </div>
      <div className="flex items-baseline gap-1">
        <span className="text-2xl font-black text-gray-900">{value}</span>
        <span className="text-xs font-bold text-gray-400">{unit}</span>
      </div>
      {subValue && <div className="text-[10px] font-bold text-gray-400 mt-1">{subValue}</div>}
    </div>
  );

  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="absolute inset-0 bg-white/60 backdrop-blur-[100px]" onClick={onClose} />
      <div className="relative w-full max-w-6xl aspect-[16/9] bg-gray-50/20 rounded-[4rem] flex items-center justify-center overflow-hidden" onClick={e => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-12 right-12 w-20 h-20 bg-gray-900 text-white rounded-[2.5rem] flex items-center justify-center shadow-2xl active:scale-90 transition-all z-10">
          <X size={32} />
        </button>

        {/* System Diagram Grid */}
        <div className="relative w-full h-full flex items-center justify-between px-20">
          {/* Left Column: Grid */}
          <div className="flex flex-col gap-12">
            <Block title="Net" value={data.gridPower} unit="W" icon={UtilityPole} colorClass="bg-rose-500" />
          </div>

          {/* Central Column: Battery & MultiPlus */}
          <div className="flex flex-col items-center gap-12">
            <div className="bg-blue-600 w-40 h-40 rounded-[2.5rem] shadow-2xl flex flex-col items-center justify-center text-white border-b-8 border-amber-400 relative">
               <Activity size={48} className="opacity-40 absolute" />
               <span className="text-sm font-black uppercase tracking-widest z-10">{data.isCharging ? 'Opladen' : 'Ontladen'}</span>
            </div>

            <div className="bg-white rounded-[2rem] p-8 shadow-2xl border border-gray-100 w-56 text-center">
               <div className="flex items-center justify-center gap-2 mb-2 text-blue-500">
                  <BatteryIcon size={24} />
                  <span className="text-[10px] font-black uppercase tracking-[0.2em]">{data.isCharging ? 'Batterij' : 'Batterij'}</span>
               </div>
               <div className="text-5xl font-black text-gray-900">{data.soc}%</div>
