      <div className="absolute inset-0 bg-white/60 backdrop-blur-[100px]" onClick={onClose} />
      <div className="relative w-full h-full sm:h-auto sm:max-h-[95vh] bg-white/40 sm:rounded-[4rem] sm:border sm:border-white shadow-2xl flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>
        <div className="p-10 flex justify-between items-center bg-white/20 backdrop-blur-xl shrink-0">
          <div className="flex items-center gap-8">
            <div className="w-16 h-16 bg-white rounded-3xl flex items-center justify-center shadow-lg border border-gray-50">
              <Cloud className="w-8 h-8 text-blue-500" />
            </div>
            <div>
              <h3 className="text-3xl font-black text-gray-900 tracking-tight">Weersverwachting</h3>
              <div className="flex items-center gap-3 mt-1">
                 <span className="text-xs text-gray-400 font-black uppercase tracking-[0.3em]">Herenthout, BE</span>
                 <div className="w-1 h-1 bg-gray-200 rounded-full" />
                 <a href="https://www.meteo.be/nl/herenthout" target="_blank" rel="noreferrer" className="text-[10px] text-blue-400 font-bold uppercase hover:text-blue-600 flex items-center gap-1">Live op Meteo.be <ExternalLink size={10}/></a>
              </div>
            </div>
          </div>
          <button onClick={onClose} className="w-20 h-20 flex items-center justify-center bg-gray-900 hover:bg-black rounded-[2.5rem] transition-all text-white shadow-2xl active:scale-90 touch-manipulation group">
            <X className="w-10 h-10 group-hover:rotate-90 transition-transform" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-10 space-y-24 custom-touch-scrollbar scroll-smooth pb-32">
          {loading && !weatherData ? (
            <div className="flex flex-col items-center justify-center py-48 gap-8">
              <Loader2 className="w-24 h-24 text-blue-400 animate-spin" />
              <p className="text-gray-900 text-xs font-black uppercase tracking-[0.5em] animate-pulse">Laden...</p>
            </div>
          ) : weatherData && (
            <div className="space-y-24">
              <section className="space-y-12">
                <div className="flex items-center justify-between px-2">
                  <div className="flex items-center gap-4">
                    <div className="w-2 h-2 bg-blue-500 rounded-full" />
                    <span className="text-sm text-gray-900 font-black uppercase tracking-[0.4em]">Komende 12 uur</span>
                  </div>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-8 no-scrollbar snap-x px-2">
                  {weatherData.hourly.map((h: any, i: number) => (
                    <div key={i} className="flex-shrink-0 w-32 bg-white/80 border border-white/50 p-8 rounded-[2.5rem] flex flex-col items-center gap-6 hover:bg-white hover:shadow-2xl transition-all snap-start group">
                      <span className="text-[12px] text-gray-400 font-black uppercase tracking-widest">{h.time}</span>
                      <WeatherIcon type={h.icon} className="w-12 h-12 text-blue-400 group-hover:scale-110 transition-transform" />
