  daily: { day: string; low: number; high: number; condition: string; icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle' }[];
}

interface VictronData {
  soc: number;
  acLoad: number;
  pvYieldAC: number;
  pvYieldDC: number;
  gridPower: number;
  batteryPower: number;
  evPower: number;
  isCharging: boolean;
  siteName: string;
  dailyGridIn: number;
  dailySolarYield: number;
  dailyEvConsumption: number;
}

interface ChangeLogEntry {
  version: string;
  timestamp: string;
  title: string;
  description: string;
  tags: string[];
}

const CHANGE_LOG: ChangeLogEntry[] = [
  {
    version: '1.4.6',
