    if (systemInfoTimerRef.current) clearTimeout(systemInfoTimerRef.current);
    systemInfoTimerRef.current = window.setTimeout(() => setIsSystemInfoOpen(false), 180000);
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-[#fcfcfc] overflow-x-hidden relative">
      <div className="absolute top-0 right-0 w-[1000px] h-[1000px] bg-blue-50/20 rounded-full blur-[120px] -z-10 translate-x-1/2 -translate-y-1/2 pointer-events-none" />
      <header className="w-full px-[30px] pt-8 pb-4 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-100/60">
        <div className="space-y-4">
          <h1 className="text-5xl sm:text-7xl font-extralight tracking-tighter text-gray-900 leading-[0.95]">
            {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
            {user?.given_name ? <span className="text-gray-300">, {user.given_name}</span> : ''}
          </h1>
          <div className="flex items-center gap-6"><Clock className="w-5 h-5 text-gray-300" /><p className="text-gray-400 text-xs uppercase tracking-[0.4em] font-black">{currentDate.toLocaleDateString('nl-BE', { weekday: 'long', month: 'long', day: 'numeric' })}</p></div>
        </div>
        <div className="mt-8 md:mt-0 flex flex-col items-end gap-4">
          <div className="flex items-center gap-6">
            {!accessToken ? (
              <button onClick={handleLogin} disabled={isSyncing} className="px-8 py-4 bg-gray-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl">{isSyncing ? 'Verbinden...' : 'Google Sync'}</button>
            ) : (
              <div className="flex items-center gap-6 bg-white p-2.5 pr-6 rounded-[1.25rem] border border-gray-50 shadow-sm cursor-pointer group" onClick={handleLogout}>
                <div className="w-10 h-10 bg-gray-100 rounded-xl overflow-hidden border border-gray-50 group-hover:opacity-80 transition-opacity">
                  <img src={user?.picture} alt="" className="w-full h-full object-cover" />
                </div>
                <div className="text-right">
                  <div className="text-[10px] font-black text-gray-900 uppercase tracking-widest">{user?.name}</div>
                  <div className="text-[8px] text-green-500 font-bold flex items-center justify-end gap-1"><CheckCircle2 size={8}/> ONLINE</div>
                </div>
              </div>
            )}
            <WeatherWidget data={weatherData} onClick={() => fetchWeatherForecast(true)} isRefreshing={weatherLoading} />
          </div>
          <div className="text-[9px] font-black text-gray-300 uppercase tracking-[0.4em]">HERENTHOUT, BELGIË</div>
        </div>
      </header>
      <main className="w-full px-[30px] py-6 grid grid-cols-1 xl:grid-cols-10 gap-8 min-h-[600px]">
        <section className="xl:col-span-8 h-full">
          <Calendar accessToken={accessToken} items={agendaItems} isLoading={agendaLoading} onRefresh={() => accessToken && fetchCalendarEvents(accessToken)} />
        </section>
        <aside className="xl:col-span-2 space-y-6 flex flex-col h-full">
          <VictronWidget data={victronData} isLoading={victronLoading} error={victronError} onClick={handleEnergyClick} onDebugClick={handleDebugClick} />
          <TaskWidget />
          <div 
            onClick={handleSystemInfoClick}
            className="p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100 cursor-pointer hover:border-blue-300 hover:shadow-xl hover:shadow-blue-100/20 transition-all active:scale-95"
          >
            <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] block mb-4 flex items-center gap-2"><Info size={12}/> Systeem Info</span>
            <div className="space-y-2">
                <p className="text-[11px] font-medium text-gray-500 leading-relaxed italic line-clamp-2">
                  {lastSyncInfo}
                </p>
                <div className="h-px bg-gray-50" />
                <p className="text-[11px] font-medium text-gray-400 leading-relaxed italic">
                  Victron: {victronTokenRef.current ? 'Token hergebruik' : 'Aanmelden...'}
                </p>
            </div>
          </div>
          <div className="p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100 mt-auto">
            <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] block mb-4">Inspiratie</span>
            <p className="text-sm font-light text-gray-500 leading-relaxed italic">"Focus op de voortgang, niet op de perfectie."</p>
          </div>
        </aside>
      </main>

      {isWeatherOpen && <WeatherOverlay onClose={() => setIsWeatherOpen(false)} weatherData={weatherData} loading={weatherLoading} />}
      {isEnergyOpen && <EnergyOverlay data={victronData} onClose={() => setIsEnergyOpen(false)} />}
      {isSystemInfoOpen && (
        <SystemInfoOverlay 
          isOpen={isSystemInfoOpen} 
          onClose={() => setIsSystemInfoOpen(false)} 
