  History, ShieldCheck, Terminal, Layers, TrendingUp, Gauge, Leaf
} from 'lucide-react';

// --- Constants & Types ---
const CLIENT_ID = '83368315587-g04nagjcgrsaotbdpet6gq2f7njrh2tu.apps.googleusercontent.com';
const SCOPES = 'https://www.googleapis.com/auth/calendar.readonly https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/drive.readonly';
const VICTRON_USER = 'stevenvw@gmail.com';
const VICTRON_FILENAME = 'victron_password.txt';
const VICTRON_DASHBOARD_URL = 'https://vrm.victronenergy.com/installation/756249/dashboard';

const WEATHER_CACHE_KEY = 'hub_weather_cache';
const USER_CACHE_KEY = 'hub_user_profile_v2';
const USER_CACHE_TTL = 7 * 24 * 60 * 60 * 1000; // 7 days in milliseconds

interface AgendaItem {
  id: string;
  start: Date;
  time: string;
  title: string;
  location: string;
  category: 'work' | 'personal' | 'health' | 'social';
}

interface WeatherData {
  location: string;
  currentTemp: number;
  condition: string;
  humidity: number;
  windSpeed: string;
  sourceUrl?: string;
  lastUpdated?: number;
  hourly: { time: string; temp: number; icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle' }[];
  daily: { day: string; low: number; high: number; condition: string; icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle' }[];
}

interface VictronData {
  soc: number;
  acLoad: number;
  pvYieldAC: number;
  pvYieldDC: number;
  gridPower: number;
  batteryPower: number;
  evPower: number;
  isCharging: boolean;
  siteName: string;
  dailyGridIn: number;
  dailySolarYield: number;
  dailyEvConsumption: number;
}

interface ChangeLogEntry {
  version: string;
  timestamp: string;
  title: string;
  description: string;
  tags: string[];
}

