const VictronDebugOverlay = ({ isOpen, onClose, log }: { isOpen: boolean, onClose: () => void, log: string | null }) => {
  const [copied, setCopied] = useState(false);
  if (!isOpen) return null;

  const handleCopy = () => {
    if (log) {
      navigator.clipboard.writeText(log);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const logTimestamp = useMemo(() => {
    if (!log) return null;
    const match = log.match(/--- TIMESTAMP: (.*) ---/);
    return match ? match[1] : "Nog geen timestamp";
  }, [log]);

  return (
    <div className="fixed inset-0 z-[400] flex items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-xl" onClick={onClose} />
      <div className="relative w-full max-w-5xl h-[90vh] bg-gray-950 rounded-[3rem] border border-white/10 shadow-2xl flex flex-col overflow-hidden">
        <div className="p-10 border-b border-white/5 flex items-center justify-between shrink-0 bg-gray-900/50 backdrop-blur-md">
          <div className="flex items-center gap-6">
            <div className="w-14 h-14 bg-blue-500/10 rounded-2xl flex items-center justify-center border border-blue-500/20">
              <FileText className="text-blue-400 w-7 h-7" />
            </div>
            <div>
              <div className="flex items-center gap-3">
                <h3 className="text-2xl font-black text-white tracking-tight">Victron RAW Debug Log</h3>
                <span className="px-3 py-1 bg-white/5 text-[9px] font-black text-gray-400 uppercase tracking-widest rounded-md border border-white/5">
                  Last: {logTimestamp}
                </span>
              </div>
              <p className="text-[10px] text-gray-500 uppercase tracking-[0.3em] font-black mt-1">Real-time Diagnostics API Dump</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button 
              onClick={handleCopy} 
              className={`flex items-center gap-3 px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest transition-all active:scale-95 touch-manipulation shadow-lg ${copied ? 'bg-green-500 text-white' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
            >
              {copied ? <CheckCircle2 size={16} /> : <ClipboardCheck size={16} />}
              {copied ? 'Gekopieerd!' : 'Kopieer Log'}
            </button>
            <button onClick={onClose} className="w-14 h-14 bg-white/5 hover:bg-white/10 rounded-2xl flex items-center justify-center text-gray-400 transition-colors">
              <X size={28} />
            </button>
          </div>
        </div>
        <div className="flex-1 overflow-auto p-10 font-mono text-[12px] leading-relaxed text-blue-200/90 bg-black/20 custom-touch-scrollbar scroll-smooth">
          <pre 
            className="whitespace-pre-wrap break-all" 
            style={{ userSelect: 'text', WebkitUserSelect: 'text', cursor: 'text' }}
          >
            {log || 'Bezig met synchroniseren van Victron API... Even geduld.'}
          </pre>
        </div>
      </div>
    </div>
  );
};

