                <span className="px-3 py-1 bg-white/5 text-[9px] font-black text-gray-400 uppercase tracking-widest rounded-md border border-white/5">Laatste Sync: {logTimestamp}</span>
              </div>
              <p className="text-[10px] text-gray-500 uppercase tracking-[0.3em] font-black mt-1">Real-time Diagnostics API Dump</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={handleCopy} className={`flex items-center gap-3 px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-lg ${copied ? 'bg-green-500 text-white' : 'bg-blue-600 text-white hover:bg-blue-500'}`}>{copied ? <CheckCircle2 size={16} /> : <ClipboardCheck size={16} />}{copied ? 'Gekopieerd!' : 'Kopieer Log'}</button>
