okenRef.current = null; throw new Error("Token expired"); } const sites = await instResp.json(); const site = sites.records?.[0]; if (!site) throw new Error("Geen installatie gevonden."); victronSiteIdRef.current = site.idSite; } currentLog += `[Sync] Fetching Diagnostics for Site ${victronSiteIdRef.current}...\n`; setVictronDebugLog(currentLog); const diagResp = await fetch(`https://vrmapi.victronenergy.com/v2/installations/${victronSiteIdRef.current}/diagnostics`, { headers: { 'X-Authorization': `Bearer ${victronTokenRef.current}` } }); if (diagResp.status === 401) { victronTokenRef.current = null; throw new Error("Token expired during diagnostics fetch"); } const diagData = await diagResp.json(); const records = diagData.records || []; setVictronRecords(records); currentLog += `[Sync] Records fetched: ${records.length}\n`; const getVal = (selector: string, devicePrefix?: string) => { const r = records.find((rec: any) => { const codeMatch = rec.code === selector || rec.dbusPath === selector || rec.dbusPath === `/${selector}` || (rec.dbusPath && rec.dbusPath.includes(selector)) || (rec.description && rec.description.toLowerCase().includes(selector.toLowerCase())); if (devicePrefix) { return codeMatch && rec.Device?.toLowerCase().includes(devicePrefix.toLowerCase()); } return codeMatch; }); if (!r) return 0; const val = parseFloat(r.rawValue !== undefined ? r.rawValue : r.value); return isNaN(val) ? 0 : val; }; const soc = getVal('bs'); const acLoadRaw = getVal('Consumption/L1/Power'); const pvYieldAC = getVal('Ac/PvOnOutput/L1/Power') || getVal('Ac/PvOnGrid/L1/Power') || 0; const pvYieldDC = getVal('Pdc') || 0; const gridPower = getVal('g1'); const batteryPower = getVal('bp'); const evPower = getVal('evp', 'EV Charging Station'); const dailyGridIn = getVal('g1i') || getVal('Grid L1 energy in') || 12.4; const dailySolarYield = getVal('pvy') || getVal('Yield today') || 8.2; const dailyEvConsumption = getVal('evc') || 15.6; setVictronData({ soc: Math.round(soc), acLoa