          <div className="grid grid-cols-2 gap-3">
             <div className={`flex items-center gap-2 px-3 py-1.5 ${data ? 'bg-black/5' : 'bg-white/5'} rounded-2xl border ${data ? 'border-black/5' : 'border-white/5'}`}>{data.isCharging ? <ArrowUpRight size={12} className="text-emerald-600" /> : <ArrowDownLeft size={12} className="text-rose-600" />}<span className={`text-[11px] font-black ${data.isCharging ? 'text-emerald-600' : 'text-rose-600'}`}>{Math.abs(data.batteryPower)}W</span></div>
