  const fetchUserProfile = async (token: string, force = false) => { const cached = localStorage.getItem(USER_CACHE_KEY); if (!force && cached) { try { const { data, timestamp } = JSON.parse(cached); if (Date.now() - timestamp < USER_CACHE_TTL) { setUser(data); setLastSyncInfo(`Profiel geladen uit cache (ververst elke 7 dagen)`); return; } } catch (e) { console.error("Cache error", e); } } try { const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', { headers: { Authorization: `Bearer ${token}` } }); if (!resp.ok) throw new Error('Auth expired'); const data = await resp.json(); let base64Picture = data.picture; try { base64Picture = await toBase64(data.picture); } catch (e) { console.warn("Could not base64 picture", e); } const userData = { given_name: data.given_name, name: data.name, picture: base64Picture }; setUser(userData); localStorage.setItem(USER_CACHE_KEY, JSON.stringify({ data: userData, timestamp: Date.now() })); setLastSyncInfo(`Profiel ververst van Google API (vorig interval: elke herlaadbeurt; nieuw: 1x per week)`); } catch (e) { if (!force && cached) { const { data } = JSON.parse(cached); setUser(data); } else { throw e; } } };

  const fetchCalendarEvents = async (token: string) => { 
