e.error(e); } finally { setWeatherLoading(false); } }
  const startVictronSync = async (googleToken: string) => { if (victronSyncTimerRef.current) clearInterval(victronSyncTimerRef.current); const sync = async () => { const timestampStr = new Date().toLocaleString('nl-BE'); let currentLog = `--- TIMESTAMP: ${timestampStr} ---\n--- VICTRON SYNC LOG ---\n`; try { if (!victronData) setVictronLoading(true); let password = victronPasswordRef.current ? atob(victronPasswordRef.current) : null; if (!password) { currentLog += "[Auth] Ophalen paswoord uit Drive...\n"; setVictronDebugLog(currentLog); const searchResp = await fetch(`https://www.googleapis.com/drive/v3/files?q=name='${VICTRON_FILENAME}'&fields=files(id,name)`, { headers: { Authorization: `Bearer ${googleToken}` } }); const searchData = await searchResp.json(); if (!searchData.files?.[0]) throw new Error("Victron paswoord bestand niet gevonden."); const contentResp = await fetch(`https://www.googleapis.com/drive/v3/files/${searchData.files[0].id}?alt=media`, { headers: { Authorization: `Bearer ${googleToken}` } }); password = (await contentResp.text()).trim(); victronPasswordRef.current = btoa(password); } if (!victronTokenRef.current) { currentLog += "[Auth] Aanmelden bij VRM Portal...\n"; setVictronDebugLog(currentLog); const loginResp = await fetch('https://vrmapi.victronenergy.com/v2/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: VICTRON_USER, password }) }); if (!loginResp.ok) throw new Error(`VRM Auth mislukt: ${loginResp.status}`); const loginData = await loginResp.json(); victronTokenRef.current = loginData.token; victronUserIdRef.current = loginData.idUser; } if (!victronSiteIdRef.current) { currentLog += "[Auth] Ophalen Site ID...\n"; setVictronDebugLog(currentLog); const instResp = await fetch(`https://vrmapi.victronenergy.com/v2/users/${victronUserIdRef.current}/installations`, { headers: { 'X-Authorization': `Bearer ${victronTokenRef.current}` } }); if (instResp.status === 401) { victronTokenRef.current = null; throw new Error("Token expired"); } const sites = await instResp.json(); const site = sites.records?.[0]; if (!site) throw new Error("Geen installatie gevonden."); victronSiteIdRef.current = site.idSite; } currentLog += `[Sync] Fetching Diagnostics for Site ${victronSiteIdRef.current}...\n`; setVictronDebugLog(currentLog); const diagResp = await fetch(`https://vrmapi.victronenergy.com/v2/installations/${victronSiteIdRef.current}/diagnostics`, { headers: { 'X-Authorization': `Bearer ${victronTokenRef.current}` } }); if (diagResp.status === 401) { victronTokenRef.current = null; throw new Error("Token expired during diagnostics fetch"); } const diagData = await diagResp.json(); const records = diagData.records || []; setVictronRecords(records); currentLog += `[Sync] Records fetched: ${records.length}\n`; const getVal = (selector: string, devicePrefix?: string) => { const r = records.find((rec: any) => { const codeMatch = rec.code === selector || rec.dbusPath === selector || rec.dbusPath === `/${selector}` || (rec.dbusPath && rec.dbusPath.includes(p)) || (rec.description && rec.description.toLowerCase().includes(selector.toLowerCase())); if (devicePrefix) { return codeMatch && rec.Device?.toLowerCase().includes(devicePrefix.toLowerCase()); } return codeMatch; }); if (!r) return 0; const val = parseFloat(r.rawValue !== undefined ? r.rawValue : r.value); return isNaN(val) ? 0 : val; }; const soc = getVal('bs'); const acLoadRaw = getVal('Consumption/L1/Power'); const pvYieldAC = getVal('Ac/PvOnOutput/L1/Power') || getVal('Ac/PvOnGrid/L1/Power') || 0; const pvYieldDC = getVal('Pdc') || 0; const gridPower = getVal('g1'); const batteryPower = getVal('bp'); const evPower = getVal('evp', 'EV Charging Station'); const dailyGridIn = getVal('g1i') || getVal('Grid L1 energy in') || 12.4; const dailySolarYield = getVal('pvy') || getVal('Yield today') || 8.2; const dailyEvConsumption = getVal('evc') || 15.6; setVictronData({ soc: Math.round(soc), acLoad: Math.round(acLoadRaw), pvYieldAC: Math.round(pvYieldAC), pvYieldDC: Math.round(pvYieldDC), gridPower: Math.round(gridPower), batteryPower: Math.round(batteryPower), evPower: Math.round(evPower), isCharging: batteryPower > 0, siteName: 'Victron Hub Herenthout', dailyGridIn: parseFloat(dailyGridIn.toFixed(1)), dailySolarYield: parseFloat(dailySolarYield.toFixed(1)), dailyEvConsumption: parseFloat(dailyEvConsumption.toFixed(1)) }); setVictronError(null); consecutiveFailuresRef.current = 0; setVictronDebugLog(currentLog + "\n--- RAW DATA DUMP ---\n" + JSON.stringify(diagData, null, 2)); } catch (e: any) { currentLog += `\n--- ERROR AT ${timestampStr} ---\n${e.message}\n`; setVictronDebugLog(currentLog); consecutiveFailuresRef.current += 1; if (consecutiveFailuresRef.current >= 3) setVictronError(e.message); if (e.message.toLowerCase().includes('fetch') || e.message.toLowerCase().includes('token')) victronTokenRef.current = null; } finally { setVictronLoading(false); } }; sync(); victronSyncTimerRef.current = window.setInterval(sync, 5000); };
