const VictronWidget = ({ data, isLoading, error, onClick, onDebugClick }: { data: VictronData | null; isLoading: boolean; error: string | null; onClick: () => void; onDebugClick: () => void }) => {
  const isStandby = data ? Math.abs(data.batteryPower) < 20 : true;
  const widgetStyle = useMemo(() => {
    if (!data) return { bg: 'bg-gray-900', border: 'border-gray-800', text: 'text-white', sub: 'text-blue-400' };
    if (data.isCharging) return { bg: 'bg-emerald-100', border: 'border-emerald-200', text: 'text-gray-900', sub: 'text-emerald-600' };
    if (isStandby) return { bg: 'bg-amber-100', border: 'border-amber-200', text: 'text-gray-900', sub: 'text-amber-600' };
    return { bg: 'bg-rose-100', border: 'border-rose-200', text: 'text-gray-900', sub: 'text-rose-600' };
  }, [data, isStandby]);

  return (
    <div onClick={onClick} className={`p-8 ${widgetStyle.bg} rounded-[2.5rem] shadow-2xl border ${widgetStyle.border} relative overflow-hidden group min-h-[300px] flex flex-col justify-center transition-all duration-500 active:scale-95 cursor-pointer`}>
      <div className={`absolute top-0 right-0 p-8 opacity-5 ${widgetStyle.text}`}><Activity size={80} className="fill-current" /></div>
      <div className="mb-4 relative z-10 flex justify-between items-center">
        <span onClick={(e) => { e.stopPropagation(); onDebugClick(); }} className={`text-[12px] font-black ${widgetStyle.sub} uppercase tracking-[0.4em] flex items-center gap-2 hover:opacity-70 transition-colors cursor-help`}><Zap size={14} fill="currentColor" /> Energie</span>
        <div className={`flex items-center gap-1.5 px-2 py-0.5 ${data ? 'bg-black/5' : 'bg-white/5'} rounded-md border ${data ? 'border-black/5' : 'border-white/5'}`}><div className={`w-1 h-1 ${data ? 'bg-gray-900' : 'bg-blue-500'} rounded-full animate-pulse`} /><span className={`text-[8px] font-black ${data ? 'text-gray-400' : 'text-gray-500'} uppercase tracking-widest`}>Live 5s</span></div>
      </div>
      {isLoading && !data ? (<div className="py-8 flex flex-col items-center justify-center gap-4"><Loader2 className="w-8 h-8 text-blue-400 animate-spin" /></div>) : error ? (<div className="text-center py-4 relative z-10"><AlertTriangle size={24} className="text-rose-500 mx-auto mb-2" /><p className="text-[10px] text-gray-500 uppercase font-black">Data error</p></div>) : data ? (
        <div className="relative z-10 animate-in fade-in slide-in-from-bottom-2">
          <div className="flex items-center justify-between gap-4 mb-8"><div className="flex items-baseline gap-1"><span className={`text-7xl font-black ${widgetStyle.text} leading-none tabular-nums`}>{data.soc}</span><span className={`text-xl font-black ${widgetStyle.sub}`}>%</span></div><div className={`flex items-center gap-2 px-3 py-1.5 ${data.isCharging ? 'bg-emerald-500/20' : 'bg-black/5'} rounded-2xl border ${data.isCharging ? 'border-emerald-500/20' : 'border-black/5'}`}><Home size={12} className={data.isCharging ? 'text-emerald-700' : 'text-gray-500'} /><span className={`text-[11px] font-black ${data.isCharging ? 'text-emerald-700' : 'text-gray-700'} tabular-nums`}>{data.acLoad}W</span></div></div>
          <div className="grid grid-cols-2 gap-3">
             <div className={`flex items-center gap-2 px-3 py-1.5 ${data ? 'bg-black/5' : 'bg-white/5'} rounded-2xl border ${data ? 'border-black/5' : 'border-white/5'}`}>{data.isCharging ? <ArrowUpRight size={12} className="text-emerald-600" /> : <ArrowDownLeft size={12} className="text-rose-600" />}<span className={`text-[11px] font-black ${data.isCharging ? 'text-emerald-600' : 'text-rose-600'}`}>{Math.abs(data.batteryPower)}W</span></div>
             <div className={`flex items-center gap-2 px-3 py-1.5 ${data ? 'bg-black/5' : 'bg-white/5'} rounded-2xl border ${data ? 'border-black/5' : 'border-white/5'}`}><Sun size={12} className="text-amber-600" /><span className="text-[11px] font-black text-amber-600">{data.pvYieldAC + data.pvYieldDC}W</span></div>
             <div className={`flex items-center gap-2 px-3 py-1.5 ${data ? 'bg-black/5' : 'bg-white/5'} rounded-2xl border ${data ? 'border-black/5' : 'border-white/5'}`}><UtilityPole size={12} className="text-gray-600" /><span className="text-[11px] font-black text-gray-600">{data.gridPower}W</span></div>
             <div className={`flex items-center gap-2 px-3 py-1.5 ${data ? 'bg-black/5' : 'bg-white/5'} rounded-2xl border ${data ? 'border-black/5' : 'border-white/5'}`}><Car size={12} className="text-blue-600" /><span className="text-[11px] font-black text-blue-600">{data.evPower}W</span></div>
          </div>
        </div>
      ) : null}
    </div>
  );
};

