        <div className="p-10 flex justify-between items-center bg-white/20 backdrop-blur-xl shrink-0"><div className="flex items-center gap-8"><div className="w-16 h-16 bg-white rounded-3xl flex items-center justify-center shadow-lg border border-gray-50"><Cloud className="w-8 h-8 text-blue-500" /></div><div><h3 className="text-3xl font-black text-gray-900 tracking-tight">Weersverwachting</h3><div className="flex items-center gap-3 mt-1"><span className="text-xs text-gray-400 font-black uppercase tracking-[0.3em]">Herenthout, BE</span><div className="w-1 h-1 bg-gray-200 rounded-full" /><a href="https://www.meteo.be/nl/herenthout" target="_blank" rel="noreferrer" className="text-[10px] text-blue-400 font-bold uppercase hover:text-blue-600 flex items-center gap-1">Live op Meteo.be <ExternalLink size={10}/></a></div></div></div><button onClick={onClose} className="w-20 h-20 flex items-center justify-center bg-gray-900 hover:bg-black rounded-[2.5rem] transition-all text-white shadow-2xl active:scale-90 touch-manipulation group"><X className="w-10 h-10 group-hover:rotate-90 transition-transform" /></button></div>
        <div className="flex-1 overflow-y-auto p-10 space-y-24 custom-touch-scrollbar scroll-smooth pb-32">
