              <section className="space-y-12"><div className="flex items-center justify-between px-2"><div className="flex items-center gap-4"><div className="w-2 h-2 bg-blue-500 rounded-full" /><span className="text-sm text-gray-900 font-black uppercase tracking-[0.4em]">Komende 12 uur</span></div></div><div className="flex gap-4 overflow-x-auto pb-8 no-scrollbar snap-x px-2">{weatherData.hourly.map((h: any, i: number) => (<div key={i} className="flex-shrink-0 w-32 bg-white/80 border border-white/50 p-8 rounded-[2.5rem] flex flex-col items-center gap-6 hover:bg-white hover:shadow-2xl transition-all snap-start group"><span className="text-[12px] text-gray-400 font-black uppercase tracking-widest">{h.time}</span><WeatherIcon type={h.icon} className="w-12 h-12 text-blue-400 group-hover:scale-110 transition-transform" /><span className="text-3xl font-light text-gray-900 tracking-tighter">{h.temp}°</span></div>))}</div></section>
              <section className="space-y-12"><div className="flex items-center gap-4 px-2"><div className="w-2 h-2 bg-amber-400 rounded-full" /><span className="text-sm text-gray-900 font-black uppercase tracking-[0.4em]">7-daagse Verwachting</span></div><div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-7 gap-6 px-2">{weatherData.daily.map((d: any, i: number) => (<div key={i} className={`p-10 bg-white/40 border border-white rounded-[3.5rem] flex flex-col items-center gap-8 hover:bg-white transition-all hover:shadow-xl ${i === 0 ? 'ring-2 ring-blue-100 shadow-xl shadow-blue-100/20' : ''}`}><span className="text-[14px] font-black text-gray-800 tracking-widest uppercase">{i === 0 ? 'Vandaag' : d.day}</span><WeatherIcon type={d.icon} className="w-16 h-16 text-blue-500 relative z-10" /><div className="text-[11px] text-gray-400 font-black uppercase tracking-[0.2em] text-center px-2 line-clamp-2 min-h-[3rem]">{d.condition}</div><div className="mt-4 flex items-baseline gap-4 border-t border-gray-100/50 pt-10 w-full justify-center"><span className="text-4xl font-black text-gray-900">{d.high}°</span><span className="text-2xl font-light text-gray-300">{d.low}°</span></div></div>))}</div></section>
