        <div className="flex-1 overflow-y-auto p-12 custom-touch-scrollbar space-y-12 pb-32 bg-gray-50/50">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <DetailCard title={data.isCharging ? 'Batterij: Opladen' : isStandby ? 'Batterij: Standby' : 'Batterij: Ontladen'} val={data.soc} unit="%" icon={BatteryIcon} color={batteryIconColor} sub={`Flow: ${data.batteryPower} W`} path="/system/Dc/Battery/Soc" filterPaths={['/system/Dc/Battery/Soc', 'bp', 'Dc/Battery/Power', 'Dc/Battery/Voltage']} customStyle={{ backgroundColor: batteryBgColor }} />
            <DetailCard title="Huidig Huisverbruik" val={data.acLoad} unit="W" icon={Home} color="bg-indigo-500" trend="Live" path="/Ac/Consumption/L1/Power" filterPaths={['Consumption/L1/Power', 'Ac/L1/Power', 'Ac/L1/Voltage']} />
            <DetailCard title="Huidige Zonopbrengst" val={solarYield} unit="W" icon={Sun} color="bg-amber-400" sub={`AC: ${data.pvYieldAC}W | DC: ${data.pvYieldDC}W • Dag: ${data.dailySolarYield}kWh`} path="AC (/Ac/PvOnOutput/L1/Power) + DC (Pdc)" filterPaths={['Ac/PvOnOutput/L1/Power', 'Ac/PvOnGrid/L1/Power', 'Pdc', 'Pv/V', 'Pv/I', 'Yield today']} customStyle={{ backgroundColor: solarBgColor }} />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
             <DetailCard title="Netverbruik Vandaag" val={data.dailyGridIn} unit="kWh" icon={UtilityPole} color="bg-rose-500" trend={data.gridPower < 0 ? 'Export' : 'Import'} path="/Ac/Grid/L1/Power" filterPaths={['Ac/Grid/L1/Power', 'g1i', 'Grid L1 energy in', 'Ac/Grid/L1/Voltage']} />
             <DetailCard title="Kia EV9 Verbruik" val={data.evPower} unit="W" icon={Car} color="bg-blue-600" sub={`Totaal Vandaag: ${data.dailyEvConsumption} kWh`} path="/evp (EV Charging Station Device)" filterPaths={['evp', 'evc', 'EV Charging Station']} />
             <DetailCard title="Systeem Efficiëntie" val="98.2" unit="%" icon={Leaf} color="bg-emerald-500" trend="+1.2%" path="Internal Logic Hub Calculation" filterPaths={['bp', 'Pdc', 'Ac/L1/Power']} />
          </div>
          <div className="flex justify-center pt-8"><p className="text-[10px] font-black text-gray-300 uppercase tracking-[0.5em] animate-pulse">Klik op een widget voor gedetailleerde databronnen</p></div>
        </div>
      </div>
      {detailView && (<WidgetDetailOverlay title={detailView.title} records={getFilteredRecords(detailView.filter)} onClose={() => setDetailView(null)} />)}
    </div>
  );
};

const VictronWidget = ({ data, isLoading, error, onClick, onDebugClick }: { data: VictronData | null; isLoading: boolean; error: string | null; onClick: () => void; onDebugClick: () => void }) => {
  const isStandby = data ? Math.abs(data.batteryPower) < 20 : true;
  const widgetStyle = useMemo(() => {
    if (!data) return { bg: 'bg-gray-900', border: 'border-gray-800', text: 'text-white', sub: 'text-blue-400' };
    if (data.isCharging) return { bg: 'bg-emerald-100', border: 'border-emerald-200', text: 'text-gray-900', sub: 'text-emerald-600' };
    if (isStandby) return { bg: 'bg-amber-100', border: 'border-amber-200', text: 'text-gray-900', sub: 'text-amber-600' };
    return { bg: 'bg-rose-100', border: 'border-rose-200', text: 'text-gray-900', sub: 'text-rose-600' };
  }, [data, isStandby]);

  return (
    <div onClick={onClick} className={`p-8 ${widgetStyle.bg} rounded-[2.5rem] shadow-2xl border ${widgetStyle.border} relative overflow-hidden group min-h-[300px] flex flex-col justify-center transition-all duration-500 active:scale-95 cursor-pointer`}>
      <div className={`absolute top-0 right-0 p-8 opacity-5 ${widgetStyle.text}`}><Activity size={80} className="fill-current" /></div>
      <div className="mb-4 relative z-10 flex justify-between items-center">
        <span onClick={(e) => { e.stopPropagation(); onDebugClick(); }} className={`text-[12px] font-black ${widgetStyle.sub} uppercase tracking-[0.4em] flex items-center gap-2 hover:opacity-70 transition-colors cursor-help`}><Zap size={14} fill="currentColor" /> Energie</span>
        <div className={`flex items-center gap-1.5 px-2 py-0.5 ${data ? 'bg-black/5' : 'bg-white/5'} rounded-md border ${data ? 'border-black/5' : 'border-white/5'}`}><div className={`w-1 h-1 ${data ? 'bg-gray-900' : 'bg-blue-500'} rounded-full animate-pulse`} /><span className={`text-[8px] font-black ${data ? 'text-gray-400' : 'text-gray-500'} uppercase tracking-widest`}>Live 5s</span></div>
