const EnergyOverlay = ({ data, records, onClose }: { data: VictronData | null; records: any[]; onClose: () => void }) => {
  const [detailView, setDetailView] = useState<{ title: string; filter: string[] } | null>(null);
  if (!data) return null;
  const DetailCard = ({ title, val, unit, icon: Icon, color, sub, trend, path, customStyle, filterPaths }: any) => (
    <div onClick={() => setDetailView({ title, filter: filterPaths || [path] })} title="Klik voor data-bron details" className={`border border-gray-100 p-6 rounded-[2rem] shadow-sm hover:shadow-xl transition-all group flex flex-col justify-between h-full bg-white cursor-pointer active:scale-95 touch-manipulation relative overflow-hidden`} style={customStyle}>
      <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-10 transition-opacity"><Search size={40} className="text-gray-900" /></div>
      <div>
        <div className="flex items-center justify-between mb-4"><div className={`w-12 h-12 rounded-2xl ${color} flex items-center justify-center text-white shadow-lg`}><Icon size={20} /></div>{trend && (<div className="flex items-center gap-1 px-3 py-1 bg-gray-50/50 rounded-full"><TrendingUp size={12} className="text-gray-600" /><span className="text-[10px] font-black text-gray-600 uppercase tracking-widest">{trend}</span></div>)}</div>
        <span className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em]">{title}</span><div className="flex items-baseline gap-2 mt-2"><span className="text-5xl font-black text-gray-900 tracking-tighter tabular-nums leading-none">{val}</span><span className="text-xl font-bold text-gray-300 uppercase leading-none">{unit}</span></div>
      </div>
      {sub && <div className="mt-8 pt-6 border-t border-gray-100 text-[10px] font-black text-blue-500 uppercase tracking-widest">{sub}</div>}
    </div>
  );
  const isStandby = Math.abs(data.batteryPower) < 20;
  const batteryIconColor = data.isCharging ? 'bg-emerald-500' : isStandby ? 'bg-amber-500' : 'bg-rose-500';
  const batteryBgColor = data.isCharging ? '#d1fae5' : isStandby ? '#fef3c7' : '#fee2e2';
  const solarYield = data.pvYieldAC + data.pvYieldDC;
  const yellowIntensity = Math.min(100, (solarYield / 4000) * 100);
  const solarBgColor = `rgba(251, 191, 36, ${Math.max(0.08, yellowIntensity / 300)})`; 
  const getFilteredRecords = (paths: string[]) => { return records.filter(rec => paths.some(p => (rec.dbusPath && rec.dbusPath.includes(p)) || (rec.code && rec.code.includes(p)) || (rec.description && rec.description.toLowerCase().includes(p.toLowerCase())))); };
  return (
    <div className="fixed inset-0 z-[300] flex items-center justify-center p-0 md:p-12 animate-in fade-in duration-300">
      <div className="absolute inset-0 bg-gray-950" onClick={onClose} />
      <div className="relative w-full h-full md:rounded-[4rem] bg-white border border-gray-100 shadow-2xl flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>
        <div className="px-12 py-10 flex items-center justify-between border-b border-gray-50 shrink-0"><div className="flex items-center gap-12"><a href={VICTRON_DASHBOARD_URL} target="_blank" rel="noreferrer" className="flex items-center gap-4 group cursor-pointer"><div className="p-4 bg-orange-500 rounded-2xl shadow-xl group-hover:scale-110 transition-transform"><Zap size={32} className="text-white fill-current" /></div><div className="hidden sm:block"><h2 className="text-3xl font-black text-gray-900 tracking-tighter">Energy Dashboard</h2><div className="flex items-center gap-2 mt-1"><span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Installatie #756249</span><ExternalLink size={10} className="text-blue-500" /></div></div></a></div><button onClick={onClose} className="w-20 h-20 bg-gray-900 hover:bg-black text-white rounded-[2.5rem] flex items-center justify-center shadow-2xl transition-all active:scale-90"><X size={32} /></button></div>
        <div className="flex-1 overflow-y-auto p-12 custom-touch-scrollbar space-y-12 pb-32 bg-gray-50/50">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <DetailCard title={data.isCharging ? 'Batterij: Opladen' : isStandby ? 'Batterij: Standby' : 'Batterij: Ontladen'} val={data.soc} unit="%" icon={BatteryIcon} color={batteryIconColor} sub={`Flow: ${data.batteryPower} W`} path="/system/Dc/Battery/Soc" filterPaths={['/system/Dc/Battery/Soc', 'bp', 'Dc/Battery/Power', 'Dc/Battery/Voltage']} customStyle={{ backgroundColor: batteryBgColor }} />
            <DetailCard title="Huidig Huisverbruik" val={data.acLoad} unit="W" icon={Home} color="bg-indigo-500" trend="Live" path="/Ac/Consumption/L1/Power" filterPaths={['Consumption/L1/Power', 'Ac/L1/Power', 'Ac/L1/Voltage']} />
            <DetailCard title="Huidige Zonopbrengst" val={solarYield} unit="W" icon={Sun} color="bg-amber-400" sub={`AC: ${data.pvYieldAC}W | DC: ${data.pvYieldDC}W • Dag: ${data.dailySolarYield}kWh`} path="AC (/Ac/PvOnOutput/L1/Power) + DC (Pdc)" filterPaths={['Ac/PvOnOutput/L1/Power', 'Ac/PvOnGrid/L1/Power', 'Pdc', 'Pv/V', 'Pv/I', 'Yield today']} customStyle={{ backgroundColor: solarBgColor }} />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
             <DetailCard title="Netverbruik Vandaag" val={data.dailyGridIn} unit="kWh" icon={UtilityPole} color="bg-rose-500" trend={data.gridPower < 0 ? 'Export' : 'Import'} path="/Ac/Grid/L1/Power" filterPaths={['Ac/Grid/L1/Power', 'g1i', 'Grid L1 energy in', 'Ac/Grid/L1/Voltage']} />
             <DetailCard title="Kia EV9 Verbruik" val={data.evPower} unit="W" icon={Car} color="bg-blue-600" sub={`Totaal Vandaag: ${data.dailyEvConsumption} kWh`} path="/evp (EV Charging Station Device)" filterPaths={['evp', 'evc', 'EV Charging Station']} />
             <DetailCard title="Systeem Efficiëntie" val="98.2" unit="%" icon={Leaf} color="bg-emerald-500" trend="+1.2%" path="Internal Logic Hub Calculation" filterPaths={['bp', 'Pdc', 'Ac/L1/Power']} />
          </div>
          <div className="flex justify-center pt-8"><p className="text-[10px] font-black text-gray-300 uppercase tracking-[0.5em] animate-pulse">Klik op een widget for gedetailleerde databronnen</p></div>
        </div>
      </div>
      {detailView && (<WidgetDetailOverlay title={detailView.title} records={getFilteredRecords(detailView.filter)} onClose={() => setDetailView(null)} />)}
    </div>
  );
};

const VictronWidget = ({ data, isLoading, error, onClick, onDebugClick }: { data: VictronData | null; isLoading: boolean; error: string | null; onClick: () => void; onDebugClick: () => void }) => {
  const isStandby = data ? Math.abs(data.batteryPower) < 20 : true;
  const widgetStyle = useMemo(() => {
    if (!data) return { bg: 'bg-gray-900', border: 'border-gray-800', text: 'text-white', sub: 'text-blue-400' };
    if (data.isCharging) return { bg: 'bg-emerald-100', border: 'border-emerald-200', text: 'text-gray-900', sub: 'text-emerald-600' };
    if (isStandby) return { bg: 'bg-amber-100', border: 'border-amber-200', text: 'text-gray-900', sub: 'text-amber-600' };
    return { bg: 'bg-rose-100', border: 'border-rose-200', text: 'text-gray-900', sub: 'text-rose-600' };
