const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('hub_access_token'));
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [agendaItems, setAgendaItems] = useState<AgendaItem[]>([]);
  const [agendaLoading, setAgendaLoading] = useState(false);
  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(() => { const cached = localStorage.getItem(WEATHER_CACHE_KEY); return cached ? JSON.parse(cached) : null; });
  const [weatherLoading, setWeatherLoading] = useState(false);
  const weatherTimerRef = useRef<number | null>(null);
  const [isEnergyOpen, setIsEnergyOpen] = useState(false);
  const [isDebugOpen, setIsDebugOpen] = useState(false);
  const [isSystemInfoOpen, setIsSystemInfoOpen] = useState(false);
  const [victronData, setVictronData] = useState<VictronData | null>(null);
  const [victronRecords, setVictronRecords] = useState<any[]>([]);
  const [victronLoading, setVictronLoading] = useState(false);
  const [victronError, setVictronError] = useState<string | null>(null);
  const [victronDebugLog, setVictronDebugLog] = useState<string | null>(null);
  const energyTimerRef = useRef<number | null>(null);
  const debugTimerRef = useRef<number | null>(null);
  const systemInfoTimerRef = useRef<number | null>(null);
  const victronSyncTimerRef = useRef<number | null>(null);
  const victronPasswordRef = useRef<string | null>(null); 
  const victronTokenRef = useRef<string | null>(null);
  const victronUserIdRef = useRef<string | null>(null);
  const victronSiteIdRef = useRef<string | null>(null);
  const consecutiveFailuresRef = useRef<number>(0);
  const [lastSyncInfo, setLastSyncInfo] = useState<string>('Nog geen synchronisatie uitgevoerd');
  const tokenClientRef = useRef<any>(null);

  const handleLogout = () => { 
    localStorage.removeItem('hub_access_token'); 
    localStorage.removeItem(USER_CACHE_KEY); 
    setAccessToken(null); 
    setUser(null); 
    setAgendaItems([]); 
    setVictronData(null); 
    setVictronRecords([]); 
    setVictronError(null); 
    victronPasswordRef.current = null; 
    victronTokenRef.current = null; 
    victronUserIdRef.current = null; 
    victronSiteIdRef.current = null; 
    if (victronSyncTimerRef.current) clearInterval(victronSyncTimerRef.current); 
  };

  const handleLogin = () => { 
    setIsSyncing(true); 
    if (tokenClientRef.current) tokenClientRef.current.requestAccessToken({ prompt: 'select_account' }); 
  };

  useEffect(() => {
    const clockTimer = setInterval(() => setCurrentDate(new Date()), 1000);
    const initGsi = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: async (response: any) => {
            if (response.access_token) {
              setAccessToken(response.access_token);
              localStorage.setItem('hub_access_token', response.access_token);
              await fetchUserProfile(response.access_token, true);
              await fetchCalendarEvents(response.access_token);
              startVictronSync(response.access_token);
            }
            setIsSyncing(false);
          },
        });
        if (accessToken) {
          fetchUserProfile(accessToken).catch(() => handleLogout());
          fetchCalendarEvents(accessToken).catch(() => handleLogout());
          startVictronSync(accessToken);
        }
      } else { setTimeout(initGsi, 500); }
    };
    initGsi();
    if (!weatherData) fetchWeatherForecast(false);
    return () => {
      clearInterval(clockTimer);
      if (victronSyncTimerRef.current) clearInterval(victronSyncTimerRef.current);
      if (weatherTimerRef.current) clearTimeout(weatherTimerRef.current);
      if (energyTimerRef.current) clearTimeout(energyTimerRef.current);
      if (debugTimerRef.current) clearTimeout(debugTimerRef.current);
      if (systemInfoTimerRef.current) clearTimeout(systemInfoTimerRef.current);
    };
  }, []);

  const toBase64 = (url: string): Promise<string> => fetch(url).then(response => response.blob()).then(blob => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onloadend = () => resolve(reader.result as string); reader.onerror = reject; reader.readAsDataURL(blob); }));

  const fetchUserProfile = async (token: string, force = false) => { 
    const cached = localStorage.getItem(USER_CACHE_KEY); 
    if (!force && cached) { 
      try { 
        const { data, timestamp } = JSON.parse(cached); 
        if (Date.now() - timestamp < USER_CACHE_TTL) { setUser(data); setLastSyncInfo(`Profiel geladen uit cache`); return; } 
      } catch (e) { console.error(e); } 
    } 
    try { 
      const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', { headers: { Authorization: `Bearer ${token}` } }); 
      if (resp.status === 401) { handleLogout(); throw new Error('Auth expired'); }
      const data = await resp.json(); 
      let base64Picture = data.picture; 
      try { base64Picture = await toBase64(data.picture); } catch (e) { console.warn(e); } 
      const userData = { given_name: data.given_name, name: data.name, picture: base64Picture }; 
      setUser(userData); 
      localStorage.setItem(USER_CACHE_KEY, JSON.stringify({ data: userData, timestamp: Date.now() })); 
    } catch (e) { if (!force && cached) { const { data } = JSON.parse(cached); setUser(data); } else { throw e; } } 
  };

  const fetchCalendarEvents = async (token: string) => { 
    setAgendaLoading(true); 
    try { 
      const now = new Date(); 
      const start = new Date(now); start.setHours(0,0,0,0); 
      const end = new Date(now); end.setDate(now.getDate() + 30); 
      const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${start.toISOString()}&timeMax=${end.toISOString()}&singleEvents=true&orderBy=startTime`; 
      const resp = await fetch(url, { headers: { Authorization: `Bearer ${token}` } }); 
      if (resp.status === 401) { handleLogout(); return; }
      const data = await resp.json(); 
      const mapped = data.items.map((event: any) => { 
        const isAllDay = !event.start.dateTime;
        const startRaw = event.start.dateTime || event.start.date; 
        const endRaw = event.end.dateTime || event.end.date; 
        const startDate = isAllDay ? new Date(startRaw + 'T00:00:00') : new Date(startRaw); 
        const endDate = isAllDay ? new Date(endRaw + 'T00:00:00') : new Date(endRaw); 
        let timeStr = ''; 
        if (!isAllDay) { timeStr = `${new Date(event.start.dateTime).toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit', hour12:false})} - ${new Date(event.end.dateTime).toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit', hour12:false})}`; } 
        let category: any = 'personal'; 
        const low = (event.summary || '').toLowerCase(); 
        if (low.includes('werk') || low.includes('meeting')) category = 'work'; 
        else if (low.includes('doktor') || low.includes('sport')) category = 'health'; 
        else if (low.includes('feest') || low.includes('drink')) category = 'social'; 
        return { id: event.id, start: startDate, end: endDate, time: timeStr, title: event.summary || '(Geen titel)', location: event.location || '', category, isAllDay, htmlLink: event.htmlLink }; 
      }); 
      setAgendaItems(mapped); 
    } catch (e) { console.error(e); } finally { setAgendaLoading(false); } 
  };

  async function fetchWeatherForecast(triggerOverlay = true) { if (triggerOverlay) { setIsWeatherOpen(true); if (weatherTimerRef.current) clearTimeout(weatherTimerRef.current); weatherTimerRef.current = window.setTimeout(() => setIsWeatherOpen(false), 180000); } setWeatherLoading(true); try { const lat = 51.1378, lon = 4.7570; const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&hourly=temperature_2m,weather_code&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=7`; const resp = await fetch(url); const data = await resp.json(); const days = ['Zondag', 'Maandag', 'Dinsdag', 'Woensdag', 'Donderdag', 'Vrijdag', 'Zaterdag']; const now = new Date(); const nextHourIndex = data.hourly.time.findIndex((t: string) => new Date(t) > now); const hourlyData = data.hourly.time.slice(nextHourIndex, nextHourIndex + 12).map((t: string, i: number) => ({ time: new Date(t).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit' }), temp: Math.round(data.hourly.temperature_2m[nextHourIndex + i]), icon: getWeatherInfo(data.hourly.weather_code[nextHourIndex + i]).icon })); const weatherInfo = getWeatherInfo(data.current.weather_code); const formatted: WeatherData = { location: "Herenthout", currentTemp: Math.round(data.current.temperature_2m), condition: weatherInfo.text, humidity: data.current.relative_humidity_2m, windSpeed: `${Math.round(data.current.wind_speed_10m)} km/u`, lastUpdated: Date.now(), hourly: hourlyData, daily: data.daily.time.slice(0, 7).map((t: string, i: number) => { const info = getWeatherInfo(data.daily.weather_code[i]); return { day: days[new Date(t).getDay()], low: Math.round(data.daily.temperature_2m_min[i]), high: Math.round(data.daily.temperature_2m_max[i]), condition: info.text, icon: info.icon }; }) }; setWeatherData(formatted); localStorage.setItem(WEATHER_CACHE_KEY, JSON.stringify(formatted)); } catch (e) { console.error(e); } finally { setWeatherLoading(false); } }

  const startVictronSync = async (googleToken: string) => { 
    if (victronSyncTimerRef.current) clearInterval(victronSyncTimerRef.current); 
    const sync = async () => { 
      try { 
        if (!victronData) setVictronLoading(true); 
        let password = victronPasswordRef.current ? atob(victronPasswordRef.current) : null; 
        if (!password) { 
          const searchResp = await fetch(`https://www.googleapis.com/drive/v3/files?q=name='${VICTRON_FILENAME}'&fields=files(id,name)`, { headers: { Authorization: `Bearer ${googleToken}` } }); 
          if (searchResp.status === 401) { handleLogout(); return; }
          const searchData = await searchResp.json(); 
          if (!searchData.files?.[0]) throw new Error("Victron file not found"); 
          const contentResp = await fetch(`https://www.googleapis.com/drive/v3/files/${searchData.files[0].id}?alt=media`, { headers: { Authorization: `Bearer ${googleToken}` } }); 
          password = (await contentResp.text()).trim(); 
          victronPasswordRef.current = btoa(password); 
        } 
        if (!victronTokenRef.current) { 
          const loginResp = await fetch('https://vrmapi.victronenergy.com/v2/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: VICTRON_USER, password }) }); 
          const loginData = await loginResp.json(); 
          victronTokenRef.current = loginData.token; 
          victronUserIdRef.current = loginData.idUser; 
        } 
        if (!victronSiteIdRef.current) { 
          const instResp = await fetch(`https://vrmapi.victronenergy.com/v2/users/${victronUserIdRef.current}/installations`, { headers: { 'X-Authorization': `Bearer ${victronTokenRef.current}` } }); 
          const sites = await instResp.json(); 
          victronSiteIdRef.current = sites.records?.[0]?.idSite; 
        } 
        const diagResp = await fetch(`https://vrmapi.victronenergy.com/v2/installations/${victronSiteIdRef.current}/diagnostics`, { headers: { 'X-Authorization': `Bearer ${victronTokenRef.current}` } }); 
        const diagData = await diagResp.json(); 
        const records = diagData.records || []; 
        setVictronRecords(records); 
        setVictronDebugLog(JSON.stringify(diagData, null, 2));
        const getVal = (sel: string) => { const r = records.find((rec: any) => rec.code === sel || (rec.dbusPath && rec.dbusPath.includes(sel)) || (rec.description && rec.description.toLowerCase().includes(sel.toLowerCase()))); return r ? parseFloat(r.rawValue !== undefined ? r.rawValue : r.value) : 0; }; 
        setVictronData({ soc: Math.round(getVal('bs')), acLoad: Math.round(getVal('Consumption/L1/Power')), pvYieldAC: Math.round(getVal('Ac/PvOnOutput/L1/Power') || getVal('Ac/PvOnGrid/L1/Power')), pvYieldDC: Math.round(getVal('Pdc')), gridPower: Math.round(getVal('g1')), batteryPower: Math.round(getVal('bp')), evPower: Math.round(getVal('evp')), dailyGridIn: parseFloat((getVal('g1i') || 0).toFixed(1)), dailySolarYield: parseFloat((getVal('pvy') || 0).toFixed(1)), dailyEvConsumption: parseFloat((getVal('evc') || 0).toFixed(1)), isCharging: getVal('bp') > 0, siteName: 'Hub Herenthout' }); 
        setVictronError(null); 
      } catch (e: any) { setVictronError(e.message); } finally { setVictronLoading(false); } 
    }; 
    sync(); 
    victronSyncTimerRef.current = window.setInterval(sync, 5000); 
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-[#fcfcfc] overflow-x-hidden relative">
      <div className="absolute top-0 right-0 w-[1000px] h-[1000px] bg-blue-50/20 rounded-full blur-[120px] -z-10 translate-x-1/2 -translate-y-1/2 pointer-events-none" />
      <header className="w-full px-[30px] pt-12 pb-8 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-100/60">
        <div className="flex flex-col md:flex-row items-center md:items-baseline gap-12 text-left">
          <div className="flex flex-col">
            <div className="text-[5rem] sm:text-[7rem] font-black tracking-tighter text-gray-900 leading-[0.8] select-none tabular-nums animate-in fade-in slide-in-from-bottom-2">
              {currentDate.toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit', hour12: false })}
            </div>
            <div className="flex items-center gap-4 mt-2 px-1">
              <CalendarIcon className="w-4 h-4 text-gray-200" />
              <p className="text-gray-400 text-[10px] sm:text-xs uppercase tracking-[0.4em] font-black">
                {currentDate.toLocaleDateString('nl-BE', { weekday: 'long', month: 'long', day: 'numeric' })}
              </p>
            </div>
          </div>
          <h1 className="text-4xl sm:text-6xl font-extralight tracking-tighter text-gray-300 leading-none">
            {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
          </h1>
        </div>
        <div className="mt-8 md:mt-0 flex flex-col items-end gap-6 self-start md:self-end">
          <div className="flex items-center gap-6">
            {!accessToken ? (
              <button onClick={handleLogin} disabled={isSyncing} className="px-10 py-5 bg-gray-900 text-white rounded-[2rem] text-[11px] font-black uppercase tracking-widest shadow-2xl hover:bg-black transition-all active:scale-95">
                {isSyncing ? 'Verbinden...' : 'Google Sync'}
