              <div className="flex items-center gap-6 bg-white p-3 pr-8 rounded-[2rem] border border-gray-100 shadow-xl cursor-pointer group hover:border-gray-200 transition-all active:scale-95" onClick={handleLogout}>
                <div className="w-12 h-12 bg-gray-100 rounded-2xl overflow-hidden border border-gray-50">
                  <img src={user?.picture} alt="" className="w-full h-full object-cover" />
                </div>
