// --- Gemini Voice Assistant Component ---
const GeminiAssistantWidget = () => {
  const [isActive, setIsActive] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [timers, setTimers] = useState<{id: string, label: string, end: number}[]>([]);
  const nextStartTimeRef = useRef(0);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const outputGainRef = useRef<GainNode | null>(null);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());
  const sessionRef = useRef<any>(null);

  useEffect(() => {
    const timer = setInterval(() => {
      setTimers(prev => prev.filter(t => t.end > Date.now()));
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const stopSession = (reason?: string) => {
    setIsActive(false);
    setIsSpeaking(false);
    if (reason) setErrorMsg(reason);
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    if (inputAudioContextRef.current) inputAudioContextRef.current.close();
    if (outputAudioContextRef.current) outputAudioContextRef.current.close();
  };

  const startSession = async () => {
    setErrorMsg(null);
    try {
      const inCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      await inCtx.resume();
      await outCtx.resume();

      const outGain = outCtx.createGain();
      outGain.connect(outCtx.destination);

      inputAudioContextRef.current = inCtx;
      outputAudioContextRef.current = outCtx;
      outputGainRef.current = outGain;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const setTimerDecl = {
        name: 'set_timer',
        parameters: {
          type: Type.OBJECT,
          description: 'Sets a countdown timer for a specific duration in minutes.',
          properties: {
            duration_minutes: { type: Type.NUMBER, description: 'Duration in minutes' },
            label: { type: Type.STRING, description: 'Optional label for the timer' }
          },
          required: ['duration_minutes']
        }
      };

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            const source = inCtx.createMediaStreamSource(stream);
            const scriptProcessor = inCtx.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBytes = createPCMUnit8Array(inputData);
              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: { data: encode(pcmBytes), mimeType: 'audio/pcm;rate=16000' } });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(inCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
              setIsSpeaking(true);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outCtx, 24000, 1);
              const source = outCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outGain);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }

            if (message.toolCall) {
              for (const fc of message.toolCall.functionCalls) {
                if (fc.name === 'set_timer') {
                  const { duration_minutes, label } = fc.args as any;
                  const end = Date.now() + duration_minutes * 60000;
                  setTimers(prev => [...prev, { id: Math.random().toString(), label: label || 'Keukentimer', end }]);
                  sessionPromise.then(session => {
                    session.sendToolResponse({
                      functionResponses: { id: fc.id, name: fc.name, response: { result: "ok, timer is geactiveerd" } }
                    });
                  });
                }
              }
            }
          },
          onclose: (e) => {
            console.warn("Session Closed:", e);
            stopSession(e.reason || "Verbinding gesloten door server.");
          },
          onerror: (e) => {
            console.error("Session Error:", e);
            stopSession("Er is een verbindingsfout opgetreden.");
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } },
          tools: [{ functionDeclarations: [setTimerDecl] }],
          systemInstruction: "Je bent Gemini Hub, een slimme assistent in een woning in Herenthout. Je spreekt Nederlands. Je kunt timers instellen en vragen beantwoorden. Wees kort en bondig."
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      console.error(err);
      setErrorMsg(err.message || "Kon geen verbinding maken.");
      setIsActive(false);
    }
  };

  return (
    <div className={`p-8 rounded-[2.5rem] shadow-sm border transition-all duration-500 overflow-hidden relative ${isActive ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-gray-100'}`}>
      <div className="flex justify-between items-center mb-6">
        <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] flex items-center gap-2">
          <span className={`w-2 h-2 rounded-full ${isActive ? 'bg-indigo-500 animate-pulse' : 'bg-gray-300'}`} /> Gemini Hub Live
        </span>
        <button 
          onClick={isActive ? stopSession : startSession}
          className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all active:scale-90 ${isActive ? 'bg-indigo-500 text-white shadow-lg' : 'bg-gray-50 text-gray-400 hover:bg-gray-100'}`}
        >
          {isActive ? <MicOff size={20} /> : <Mic size={20} />}
        </button>
      </div>

      <div className="space-y-4">
        {errorMsg ? (
          <div className="py-4 flex items-center gap-3 text-rose-500">
             <AlertTriangle size={16} />
             <p className="text-[11px] font-bold leading-tight">{errorMsg}</p>
          </div>
        ) : isActive ? (
          <div className="py-4">
            <div className="flex items-center gap-2 mb-2">
              <div className={`flex items-end gap-1 h-6 ${isSpeaking ? 'animate-pulse' : ''}`}>
                {[1, 2, 3, 4, 5].map(i => (
                  <div key={i} className={`w-1 bg-indigo-400 rounded-full transition-all duration-300 ${isSpeaking ? 'h-full' : 'h-2'}`} style={{animationDelay: `${i * 0.1}s`}} />
                ))}
              </div>
              <span className="text-xs font-black text-indigo-600 uppercase tracking-widest">
                {isSpeaking ? 'Spreekt...' : 'Luistert...'}
              </span>
            </div>
            <p className="text-[11px] text-indigo-400 italic">"Zeg: 'Zet een timer voor 5 minuten'"</p>
          </div>
        ) : (
          <p className="text-sm font-medium text-gray-500 leading-relaxed">Druk op de microfoon om de assistent te activeren.</p>
        )}

        {timers.length > 0 && (
          <div className="pt-4 border-t border-indigo-100/50 space-y-2 max-h-32 overflow-y-auto no-scrollbar">
            {timers.map(timer => (
              <div key={timer.id} className="flex items-center justify-between p-3 bg-white/60 rounded-xl border border-indigo-100 shadow-sm animate-in fade-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3">
                  <Timer size={14} className="text-indigo-500" />
                  <span className="text-[11px] font-bold text-gray-700">{timer.label}</span>
                </div>
                <span className="text-[11px] font-black text-indigo-600 tabular-nums">
                  {Math.max(0, Math.ceil((timer.end - Date.now()) / 1000))}s
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

