// --- Audio Helpers ---
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

function createPCMUnit8Array(data: Float32Array): Uint8Array {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return new Uint8Array(int16.buffer);
}

const getWeatherInfo = (code: number): { icon: 'sun' | 'cloud' | 'rain' | 'storm' | 'snow' | 'drizzle', text: string } => {
  if (code === 0) return { icon: 'sun', text: 'Zonnig' };
  if (code === 1) return { icon: 'sun', text: 'Helder' };
  if (code === 2) return { icon: 'cloud', text: 'Licht bewolkt' };
  if (code === 3) return { icon: 'cloud', text: 'Bewolkt' };
  if ([45, 48].includes(code)) return { icon: 'cloud', text: 'Mistig' };
  if ([51, 53, 55, 56, 57].includes(code)) return { icon: 'drizzle', text: 'Motregen' };
  if ([61, 63, 65, 66, 67].includes(code)) return { icon: 'rain', text: 'Regen' };
  if ([71, 73, 75, 77].includes(code)) return { icon: 'snow', text: 'Sneeuw' };
  if ([80, 81, 82].includes(code)) return { icon: 'rain', text: 'Regenbuien' };
  if ([85, 86].includes(code)) return { icon: 'snow', text: 'Sneeuwbuien' };
  if ([95, 96, 99].includes(code)) return { icon: 'storm', text: 'Onweer' };
  return { icon: 'cloud', text: 'Bewolkt' };
};

// --- Gemini Assistant Widget (Fixed WebSocket stability & spam) ---
const GeminiAssistantWidget = () => {
  const [isActive, setIsActive] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const nextStartTimeRef = useRef(0);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const sessionRef = useRef<any>(null);
  const sessionActiveRef = useRef(false);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());

  const stopSession = (reason?: string) => {
    sessionActiveRef.current = false;
    setIsActive(false);
    setIsSpeaking(false);
    if (reason && reason !== "Sessie gesloten.") setErrorMsg(reason);

    // Stop current audio output
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();

    // Clean up nodes immediately to prevent onaudioprocess from firing more
    if (scriptProcessorRef.current) {
      scriptProcessorRef.current.disconnect();
      scriptProcessorRef.current.onaudioprocess = null;
      scriptProcessorRef.current = null;
    }

    if (sessionRef.current) {
      try { sessionRef.current.close(); } catch(e) {}
      sessionRef.current = null;
    }

    if (inputAudioContextRef.current) {
      try { inputAudioContextRef.current.close(); } catch(e) {}
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      try { outputAudioContextRef.current.close(); } catch(e) {}
      outputAudioContextRef.current = null;
    }
  };

  useEffect(() => {
    return () => stopSession();
  }, []);

  const startSession = async () => {
    setErrorMsg(null);
    try {
      const inCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      await inCtx.resume();
      await outCtx.resume();

      const outGain = outCtx.createGain();
      outGain.connect(outCtx.destination);

      inputAudioContextRef.current = inCtx;
      outputAudioContextRef.current = outCtx;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            sessionActiveRef.current = true;
            setIsActive(true);
            const source = inCtx.createMediaStreamSource(stream);
            const scriptProcessor = inCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;

            scriptProcessor.onaudioprocess = (e) => {
              // Safety check: skip if session marked inactive or sessionRef not yet populated
              if (!sessionActiveRef.current || !sessionRef.current) return;

              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBytes = createPCMUnit8Array(inputData);
              try {
                sessionRef.current.sendRealtimeInput({ 
                  media: { data: encode(pcmBytes), mimeType: 'audio/pcm;rate=16000' } 
                });
              } catch (err) {
                // If it fails once, stop immediately to prevent console flooding
                console.error("WebSocket send failed, stopping session.");
                stopSession("Verbinding verloren.");
              }
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(inCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData && sessionActiveRef.current && outputAudioContextRef.current) {
              setIsSpeaking(true);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContextRef.current.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputAudioContextRef.current, 24000, 1);
              const source = outputAudioContextRef.current.createBufferSource();
              source.buffer = buffer;
              source.connect(outGain);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsSpeaking(false);
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onclose: (e) => stopSession(e.reason || "Sessie gesloten."),
          onerror: (e) => stopSession("Verbindingsfout (Check API key of SSL).")
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } },
          systemInstruction: "Je bent Gemini Hub, een behulpzame assistent in Herenthout. Houd antwoorden kort."
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      stopSession("Kon microfoon niet activeren of verbinden.");
    }
  };

  return (
    <div className={`p-8 rounded-[2.5rem] shadow-sm border transition-all duration-500 overflow-hidden relative ${isActive ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-gray-100'}`}>
      <div className="flex justify-between items-center mb-6">
        <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] flex items-center gap-2">
          <span className={`w-2 h-2 rounded-full ${isActive ? 'bg-indigo-500 animate-pulse' : 'bg-gray-300'}`} /> Gemini Hub Live
        </span>
        <button 
          onClick={isActive ? () => stopSession() : startSession}
          className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all active:scale-90 ${isActive ? 'bg-indigo-500 text-white shadow-lg' : 'bg-gray-50 text-gray-400 hover:bg-gray-100'}`}
        >
          {isActive ? <MicOff size={20} /> : <Mic size={20} />}
        </button>
      </div>

      <div className="space-y-4">
        {errorMsg ? (
          <div className="py-4 flex items-center gap-3 text-rose-500">
             <AlertTriangle size={16} />
             <p className="text-[11px] font-bold leading-tight">{errorMsg}</p>
          </div>
        ) : isActive ? (
          <div className="py-4">
            <div className="flex items-center gap-2 mb-2">
              <div className={`flex items-end gap-1 h-6 ${isSpeaking ? 'animate-pulse' : ''}`}>
                {[1, 2, 3, 4, 5].map(i => (
                  <div key={i} className={`w-1 bg-indigo-400 rounded-full transition-all duration-300 ${isSpeaking ? 'h-full' : 'h-2'}`} style={{animationDelay: `${i * 0.1}s`}} />
                ))}
              </div>
              <span className="text-xs font-black text-indigo-600 uppercase tracking-widest">
                {isSpeaking ? 'Hub spreekt...' : 'Luistert...'}
              </span>
            </div>
          </div>
        ) : (
          <p className="text-sm font-medium text-gray-500 leading-relaxed">Activeer de assistent voor een live gesprek.</p>
        )}
      </div>
    </div>
  );
};

