        setEnergyError(null); 
      } catch (e: any) { 
        setEnergyError("Geen dataverbinding"); 
      } 
    }; 
    sync(); 
    energySyncTimerRef.current = window.setInterval(sync, 2000); 
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-gray-100 p-0 xl:p-8">
