        <header className="w-full px-[50px] pt-16 pb-12 flex flex-col md:flex-row md:items-end justify-between border-b border-gray-100/60 shrink-0">
          <div className="flex flex-col md:flex-row items-center md:items-baseline gap-16 text-left">
            <div className="flex flex-col">
              <div className="text-[7rem] sm:text-[9rem] font-black tracking-tighter text-gray-900 leading-[0.8] select-none tabular-nums animate-in fade-in slide-in-from-bottom-2">
                {currentDate.toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit', hour12: false })}
              </div>
              <div className="flex items-center gap-6 mt-6 px-2">
                <CalendarIcon className="w-6 h-6 text-gray-200" />
                <p className="text-gray-400 text-sm uppercase tracking-[0.5em] font-black">
                  {currentDate.toLocaleDateString('nl-BE', { weekday: 'long', month: 'long', day: 'numeric' })}
                </p>
              </div>
            </div>
            <h1 className="text-5xl sm:text-7xl font-extralight tracking-tighter text-gray-300 leading-none">
              {currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}
            </h1>
          </div>
          <div className="mt-10 md:mt-0 flex flex-col items-end gap-10 self-start md:self-end">
            <div className="flex items-center gap-10">
              {!accessToken ? (
                <button onClick={handleLogin} disabled={isSyncing} className="px-12 py-6 bg-gray-900 text-white rounded-[2.5rem] text-[13px] font-black uppercase tracking-widest shadow-2xl hover:bg-black transition-all active:scale-95">
                  {isSyncing ? 'Verbinden...' : 'Google Sync'}
                </button>
              ) : (
                <div className="flex items-center gap-8 bg-white p-4 pr-10 rounded-[2.5rem] border border-gray-100 shadow-xl cursor-pointer group hover:border-gray-200 transition-all active:scale-95" onClick={handleLogout}>
                  <div className="w-16 h-16 bg-gray-100 rounded-3xl overflow-hidden border border-gray-50">
                    <img src={user?.picture} alt="" className="w-full h-full object-cover" />
                  </div>
                  <div className="text-right">
                    <div className="text-[13px] font-black text-gray-900 uppercase tracking-widest">{user?.name}</div>
                    <div className="text-[10px] text-green-500 font-bold flex items-center justify-end gap-2 mt-1"><CheckCircle2 size={12}/> ONLINE</div>
                  </div>
                </div>
              )}
              <WeatherWidget data={weatherData} onClick={() => fetchWeatherForecast(true)} isRefreshing={weatherLoading} />
            </div>
            <div className="text-[12px] font-black text-gray-300 uppercase tracking-[0.5em]">HERENTHOUT, BELGIË</div>
          </div>
        </header>

        <main className="w-full px-[50px] py-10 grid grid-cols-1 xl:grid-cols-10 gap-10 flex-1 overflow-hidden">
          <section className="xl:col-span-7 h-full">
            <Calendar accessToken={accessToken} items={agendaItems} isLoading={agendaLoading} onRefresh={() => accessToken && fetchCalendarEvents(accessToken)} />
          </section>
          <aside className="xl:col-span-3 space-y-10 flex flex-col h-full overflow-y-auto no-scrollbar">
            <EnergyWidget data={energyData} isLoading={energyLoading} error={energyError} onClick={() => setIsEnergyOpen(true)} />
            <GeminiAssistantWidget />
            <TaskWidget />
          </aside>
        </main>

        {/* Overlays are absolute to fill the 1920x1200 container */}
        {isWeatherOpen && <WeatherOverlay onClose={() => setIsWeatherOpen(false)} weatherData={weatherData} loading={weatherLoading} />}
        {isEnergyOpen && <EnergyOverlay data={energyData} onClose={() => setIsEnergyOpen(false)} />}
      </div>
    </div>
  );
};

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

