                    {timedItems.length > 0 ? timedItems.map((item) => (<div key={item.id + date.toISOString()} onClick={() => openEvent(item.htmlLink)} className="group bg-gray-50/50 hover:bg-white p-6 rounded-[2rem] border border-transparent hover:border-gray-100 hover:shadow-xl hover:shadow-gray-200/40 transition-all duration-300 cursor-pointer"><div className="flex items-center gap-2 mb-2"><div className={`w-2 h-2 rounded-full ${categories[item.category] || 'bg-gray-300'} shrink-0`} /><span className="text-xl font-black text-gray-900 leading-none tracking-tight">{item.time}</span></div><h4 className="text-2xl font-bold text-gray-800 leading-[1.2] group-hover:text-blue-600 transition-colors">{item.title}</h4></div>)) : (allDayItems.length === 0 && (<div className="h-full flex items-center justify-center py-16"><span className="text-[14px] font-black text-gray-200 uppercase tracking-widest rotate-[-90deg]">Vrij</span></div>))}
