// --- Gemini Assistant Widget ---
const GeminiAssistantWidget = () => {
  const [isActive, setIsActive] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [needsKey, setNeedsKey] = useState(false);
  const nextStartTimeRef = useRef(0);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const sessionRef = useRef<any>(null);
  const sessionActiveRef = useRef(false);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());

  const stopSession = (reason?: string) => {
    sessionActiveRef.current = false;
    setIsActive(false);
    setIsSpeaking(false);
    if (reason && reason !== "Sessie gesloten.") setErrorMsg(reason);
    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();
    if (scriptProcessorRef.current) {
      scriptProcessorRef.current.disconnect();
      scriptProcessorRef.current.onaudioprocess = null;
      scriptProcessorRef.current = null;
    }
    if (sessionRef.current) {
      try { sessionRef.current.close(); } catch(e) {}
      sessionRef.current = null;
    }
    if (inputAudioContextRef.current) {
      try { inputAudioContextRef.current.close(); } catch(e) {}
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      try { outputAudioContextRef.current.close(); } catch(e) {}
      outputAudioContextRef.current = null;
    }
  };

  const handleKeySetup = async () => {
    if ((window as any).aistudio) {
      await (window as any).aistudio.openSelectKey();
      setErrorMsg(null);
      setNeedsKey(false);
    }
  };

  const startSession = async () => {
    setErrorMsg(null);
    setNeedsKey(false);
    if ((window as any).aistudio) {
      const hasKey = await (window as any).aistudio.hasSelectedApiKey();
      if (!hasKey && !process.env.API_KEY) {
        setNeedsKey(true);
        setErrorMsg("API Key vereist voor Live verbinding.");
        return;
      }
    }
    try {
      const inCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      await inCtx.resume(); await outCtx.resume();
      const outGain = outCtx.createGain(); outGain.connect(outCtx.destination);
      inputAudioContextRef.current = inCtx; outputAudioContextRef.current = outCtx;
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      // Fix: Proper initialization of Live session and handling of pcm streams with sessionPromise to avoid race conditions.
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            sessionActiveRef.current = true; setIsActive(true);
            const source = inCtx.createMediaStreamSource(stream);
            const scriptProcessor = inCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBytes = createPCMUnit8Array(inputData);
              // Fix: Use sessionPromise.then to ensure session is resolved before sending data.
              sessionPromise.then((session) => {
                if (sessionActiveRef.current) {
                  session.sendRealtimeInput({ media: { data: encode(pcmBytes), mimeType: 'audio/pcm;rate=16000' } });
                }
              }).catch(() => {});
            };
            source.connect(scriptProcessor); scriptProcessor.connect(inCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData && sessionActiveRef.current && outputAudioContextRef.current) {
              setIsSpeaking(true);
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContextRef.current.currentTime);
              const buffer = await decodeAudioData(decode(audioData), outputAudioContextRef.current, 24000, 1);
              const source = outputAudioContextRef.current.createBufferSource();
              source.buffer = buffer; source.connect(outGain);
              source.addEventListener('ended', () => { sourcesRef.current.delete(source); if (sourcesRef.current.size === 0) setIsSpeaking(false); });
              source.start(nextStartTimeRef.current); nextStartTimeRef.current += buffer.duration; sourcesRef.current.add(source);
            }
            // Fix: Added handling for session interruptions as per Live API requirements.
            const interrupted = message.serverContent?.interrupted;
            if (interrupted) {
              for (const source of sourcesRef.current.values()) {
                try { source.stop(); } catch(e) {}
                sourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onclose: (e) => stopSession(e.reason || "Sessie gesloten."),
          onerror: (e: any) => stopSession("Verbindingsfout.")
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } },
          systemInstruction: "Je bent Gemini Hub, een behulpzame assistent in Herenthout. Houd antwoorden kort en spreek Nederlands."
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { stopSession("Kon geen verbinding maken."); }
  };

  return (
    <div className={`p-8 rounded-[2.5rem] shadow-sm border transition-all duration-500 overflow-hidden relative ${isActive ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-gray-100'}`}>
      <div className="flex justify-between items-center mb-6">
        <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] flex items-center gap-2">
          <span className={`w-2 h-2 rounded-full ${isActive ? 'bg-indigo-500 animate-pulse' : 'bg-gray-300'}`} /> Gemini Hub Live
        </span>
        <button onClick={isActive ? () => stopSession() : startSession} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all active:scale-90 ${isActive ? 'bg-indigo-500 text-white shadow-lg' : 'bg-gray-50 text-gray-400 hover:bg-gray-100'}`}>
          {isActive ? <MicOff size={20} /> : <Mic size={20} />}
        </button>
      </div>
      <div className="space-y-4">
        {errorMsg ? (
          <div className="py-2">
            <div className="flex items-center gap-3 text-rose-500 mb-3"><AlertTriangle size={16} /><p className="text-[11px] font-bold leading-tight">{errorMsg}</p></div>
            {needsKey && (<button onClick={handleKeySetup} className="w-full py-3 bg-rose-50 text-rose-600 rounded-xl text-[10px] font-black uppercase tracking-widest border border-rose-100 hover:bg-rose-100 transition-colors">Koppel API Key</button>)}
          </div>
        ) : isActive ? (
          <div className="py-4">
            <div className="flex items-center gap-2 mb-2">
              <div className={`flex items-end gap-1 h-6 ${isSpeaking ? 'animate-pulse' : ''}`}>{[1, 2, 3, 4, 5].map(i => (<div key={i} className={`w-1 bg-indigo-400 rounded-full transition-all duration-300 ${isSpeaking ? 'h-full' : 'h-2'}`} style={{animationDelay: `${i * 0.1}s`}} />))}</div>
              <span className="text-xs font-black text-indigo-600 uppercase tracking-widest">{isSpeaking ? 'Hub spreekt...' : 'Luistert...'}</span>
            </div>
          </div>
        ) : (<p className="text-sm font-medium text-gray-500 leading-relaxed">Activeer de assistent voor een live gesprek.</p>)}
      </div>
    </div>
  );
};

