const EnergyWidget = ({ data, isLoading, error, onClick }: { data: EnergyData | null, isLoading: boolean, error: string | null, onClick: () => void }) => {
  const evDisplay = useMemo(() => {
    if (!data) return '--';
    const isIdle = data.evStatus.toLowerCase().includes('idle') || data.evPower < 10;
    return isIdle ? 'Idle' : `${data.evPower}W`;
  }, [data]);

  const BatteryIndicator = () => {
    if (!data) return null;
    const status = data.batteryStatus.toLowerCase();
    if (status === 'opladen') return <ArrowUp size={24} className="text-emerald-500 animate-bounce" />;
    if (status === 'ontladen') return <ArrowDown size={24} className="text-rose-500 animate-bounce" />;
    return <Equals size={24} className="text-gray-400" />;
