    setIsActive(false);
    setIsSpeaking(false);
    setIsStarting(false);

    if (reason && reason !== "Sessie gesloten.") {
      const isAuthError = 
        reason.includes("API key not valid") || 
        reason.includes("Requested entity was not found") ||
        reason.includes("403") ||
        reason.includes("401");

      if (isAuthError) {
        addLog("Authenticatie fout gedetecteerd.", 'error');
        setNeedsKey(true);
        setErrorMsg("API Key ongeldig of niet gekoppeld.");
      } else {
        setErrorMsg(reason);
      }
    }

    sourcesRef.current.forEach(s => { try { s.stop(); } catch(e) {} });
    sourcesRef.current.clear();

    if (scriptProcessorRef.current) {
      try {
        scriptProcessorRef.current.disconnect();
        scriptProcessorRef.current.onaudioprocess = null;
      } catch (e) {}
      scriptProcessorRef.current = null;
    }

    if (sessionRef.current) {
      try { sessionRef.current.close(); } catch(e) {}
      sessionRef.current = null;
    }

    if (inputAudioContextRef.current) {
      try { inputAudioContextRef.current.close(); } catch(e) {}
      inputAudioContextRef.current = null;
    }

    if (outputAudioContextRef.current) {
      try { outputAudioContextRef.current.close(); } catch(e) {}
      outputAudioContextRef.current = null;
    }
  };

  const handleKeySetup = async () => {
    addLog("API Key setup geopend.", 'info');
    if ((window as any).aistudio) {
      await (window as any).aistudio.openSelectKey();
      setErrorMsg(null);
      setNeedsKey(false);
      addLog("API Key picker gesloten. Proberen te herstarten...", 'success');
      setTimeout(startSession, 500);
    }
  };

  const startSession = async () => {
    if (isActive || isStarting) {
      addLog("Sessie reeds actief of startend. Commando genegeerd.", 'info');
      return;
    }

    addLog("--- NIEUWE SESSIE START ---", 'info');
    setIsStarting(true);
    setErrorMsg(null);
    setNeedsKey(false);

    addLog(`Browser context: Secure=${window.isSecureContext}, Host=${window.location.hostname}`, 'info');

    if (!window.isSecureContext && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1') {
      addLog("Geweigerd: Geen beveiligde verbinding (HTTPS vereist voor microfoon).", 'error');
      stopSession("Microfoon vereist HTTPS (beveiligde verbinding).");
      return;
    }

    if ((window as any).aistudio) {
      addLog("Controleren op API Key...", 'info');
      const hasKey = await (window as any).aistudio.hasSelectedApiKey();
      addLog(`AI Studio Key status: ${hasKey ? 'Gevonden' : 'Niet gevonden'}`, hasKey ? 'success' : 'info');
      if (!hasKey && !process.env.API_KEY) {
        addLog("Geen API Key gevonden in env of picker.", 'error');
        setNeedsKey(true);
        setErrorMsg("Koppel een betaalde API Key om te starten.");
        setIsStarting(false);
        return;
      }
    }

    try {
      addLog("Audio Contexts initialiseren...", 'info');
      const inCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      addLog(`AudioContext input state: ${inCtx.state}`, 'info');
      if (inCtx.state === 'suspended') {
        addLog("Input context hervatten...", 'info');
        await inCtx.resume();
        addLog(`Input context state na resume: ${inCtx.state}`, 'info');
      }

      const outGain = outCtx.createGain(); 
      outGain.connect(outCtx.destination);
      inputAudioContextRef.current = inCtx; 
      outputAudioContextRef.current = outCtx;

      addLog("Microfoon toegang aanvragen...", 'info');
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      addLog(`Microfoon stream verkregen. Tracks: ${stream.getAudioTracks().length}`, 'success');

      if (stream.getAudioTracks().length === 0) {
        throw new Error("Geen actieve microfoon gevonden.");
      }

      addLog(`Gemini SDK initialiseren met model: gemini-2.5-flash-native-audio-preview-12-2025`, 'info');
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      addLog("Verbinding maken met Live API...", 'info');
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            addLog("WebSocket Verbinding GEOPEND.", 'success');
            sessionActiveRef.current = true; 
            setIsActive(true);
            setIsStarting(false);

            addLog("Input processor koppelen...", 'info');
            const source = inCtx.createMediaStreamSource(stream);
            const scriptProcessor = inCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current = scriptProcessor;

            scriptProcessor.onaudioprocess = (e) => {
              if (!sessionActiveRef.current) return;
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBytes = createPCMUnit8Array(inputData);

              sessionPromise.then((session) => {
                if (sessionActiveRef.current) {
                  session.sendRealtimeInput({ 
                    media: { 
                      data: encode(pcmBytes), 
                      mimeType: 'audio/pcm;rate=16000' 
                    } 
                  });
                }
              }).catch((err) => {
                addLog(`Fout bij verzenden PCM data: ${err.message}`, 'error');
              });
            };

            source.connect(scriptProcessor); 
            scriptProcessor.connect(inCtx.destination);
            addLog("Microfoon data streamt nu naar Gemini.", 'info');
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data) {
              addLog("Audio ontvangen van model.", 'info');
              const audioData = message.serverContent.modelTurn.parts[0].inlineData.data;
              if (sessionActiveRef.current && outputAudioContextRef.current) {
                setIsSpeaking(true);
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContextRef.current.currentTime);
                const buffer = await decodeAudioData(decode(audioData), outputAudioContextRef.current, 24000, 1);
                const source = outputAudioContextRef.current.createBufferSource();
                source.buffer = buffer; 
                source.connect(outGain);
                source.addEventListener('ended', () => { 
                  sourcesRef.current.delete(source); 
                  if (sourcesRef.current.size === 0) setIsSpeaking(false); 
                });
                source.start(nextStartTimeRef.current); 
                nextStartTimeRef.current += buffer.duration; 
                sourcesRef.current.add(source);
              }
            }
            if (message.serverContent?.interrupted) {
              addLog("Model onderbroken door gebruiker.", 'info');
              for (const source of sourcesRef.current.values()) {
                try { source.stop(); } catch(e) {}
                sourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
              setIsSpeaking(false);
            }
          },
          onclose: (e) => {
            addLog(`WebSocket GESLOTEN. Code: ${e.code}, Reden: ${e.reason || 'Niet gespecificeerd'}`, 'info');
            stopSession(e.reason || "Sessie gesloten.");
          },
          onerror: (e: any) => {
            const msg = e?.message || e?.toString() || "Onbekende socket fout";
            addLog(`WebSocket FOUT: ${msg}`, 'error');
            if (msg.includes("API key not valid") || msg.includes("Requested entity was not found") || msg.includes("403") || msg.includes("401")) {
              setNeedsKey(true);
              stopSession("API Key ongeldig of verlopen.");
            } else {
              stopSession("Netwerkfout bij verbinding.");
            }
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } },
          systemInstruction: "Je bent Gemini Hub, een behulpzame assistent in Herenthout. Houd antwoorden kort en spreek Nederlands."
        }
      });
      sessionRef.current = await sessionPromise;
      addLog("Session object verkregen.", 'info');
    } catch (err: any) { 
      const msg = err.message || "Onbekende fout";
      addLog(`FATALE FOUT bij start: ${msg}`, 'error');
      if (msg.includes("API key not valid") || msg.includes("Requested entity was not found") || msg.includes("403") || msg.includes("401")) {
        setNeedsKey(true);
        stopSession("Koppel een geldige API Key.");
      } else if (msg.includes("Permission denied")) {
        stopSession("Toegang tot microfoon geweigerd.");
      } else {
        stopSession(msg || "Kon Live sessie niet starten."); 
      }
    }
  };

  const copyLogs = () => {
    const text = logs.map(l => `[${l.timestamp}] [${l.type.toUpperCase()}] ${l.msg}`).join('\n');
    navigator.clipboard.writeText(text);
    addLog("Logs gekopieerd naar klembord.", 'success');
  };

  return (
    <>
      <div className={`p-8 rounded-[2.5rem] shadow-sm border transition-all duration-500 overflow-hidden relative ${isActive ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-gray-100'}`}>
        <div className="flex justify-between items-center mb-6">
          <button 
            onClick={() => setShowLogs(true)}
            className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] flex items-center gap-2 hover:text-indigo-400 transition-colors"
          >
            <span className={`w-2 h-2 rounded-full ${(isActive || isStarting) ? 'bg-indigo-500 animate-pulse' : 'bg-gray-300'}`} /> Gemini Hub Live
          </button>
          <button 
            onClick={isActive ? () => stopSession() : startSession} 
            disabled={isStarting}
            className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all active:scale-90 ${(isActive || isStarting) ? 'bg-indigo-500 text-white shadow-lg' : 'bg-gray-50 text-gray-400 hover:bg-gray-100'} ${isStarting ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            {isStarting ? <Loader2 size={20} className="animate-spin" /> : isActive ? <MicOff size={20} /> : <Mic size={20} />}
          </button>
        </div>
        <div className="space-y-4">
          {errorMsg ? (
            <div className="py-2">
              <div className="flex items-center gap-3 text-rose-500 mb-3"><AlertTriangle size={16} /><p className="text-[11px] font-bold leading-tight">{errorMsg}</p></div>
              {needsKey && (<button onClick={handleKeySetup} className="w-full py-3 bg-rose-50 text-rose-600 rounded-xl text-[10px] font-black uppercase tracking-widest border border-rose-100 hover:bg-rose-100 transition-colors shadow-sm">Koppel API Key</button>)}
            </div>
          ) : isActive ? (
            <div className="py-4">
              <div className="flex items-center gap-2 mb-2">
                <div className={`flex items-end gap-1 h-6 ${isSpeaking ? 'animate-pulse' : ''}`}>{[1, 2, 3, 4, 5].map(i => (<div key={i} className={`w-1 bg-indigo-400 rounded-full transition-all duration-300 ${isSpeaking ? 'h-full' : 'h-2'}`} style={{animationDelay: `${i * 0.1}s`}} />))}</div>
                <span className="text-xs font-black text-indigo-600 uppercase tracking-widest">{isSpeaking ? 'Hub spreekt...' : 'Hub luistert...'}</span>
              </div>
            </div>
          ) : isStarting ? (
            <p className="text-sm font-medium text-indigo-400 leading-relaxed animate-pulse">Initialiseren...</p>
          ) : (<p className="text-sm font-medium text-gray-500 leading-relaxed">Activeer de assistent voor een live gesprek.</p>)}
        </div>
      </div>

      {/* Gemini Log Overlay */}
      {showLogs && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center animate-in fade-in bg-black/80 backdrop-blur-md p-10">
          <div className="bg-[#1a1a1a] w-full max-w-4xl h-[80vh] rounded-[3rem] border border-white/10 flex flex-col overflow-hidden shadow-2xl">
            <div className="p-8 bg-[#222] border-b border-white/5 flex justify-between items-center">
              <div className="flex items-center gap-4 text-indigo-400">
                <Terminal size={24} />
                <h3 className="font-black text-xs uppercase tracking-[0.4em]">Gemini Live Console Logs</h3>
              </div>
              <div className="flex items-center gap-4">
                <button onClick={copyLogs} className="p-3 bg-white/5 hover:bg-white/10 text-white rounded-xl transition-all" title="Logs kopiëren"><Copy size={18} /></button>
                <button onClick={() => setLogs([])} className="p-3 bg-white/5 hover:bg-white/10 text-rose-400 rounded-xl transition-all" title="Logs wissen"><Trash2 size={18} /></button>
                <button onClick={() => setShowLogs(false)} className="w-12 h-12 flex items-center justify-center bg-white/10 hover:bg-white/20 text-white rounded-2xl transition-all"><X size={24} /></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-8 space-y-2 font-mono text-[11px] scroll-smooth no-scrollbar">
              {logs.length === 0 ? (
                <div className="h-full flex items-center justify-center opacity-20 text-white font-black uppercase tracking-widest">Geen logs beschikbaar</div>
              ) : logs.map((log, i) => (
                <div key={i} className={`flex gap-4 border-b border-white/5 pb-2 last:border-0 ${log.type === 'error' ? 'text-rose-400' : log.type === 'success' ? 'text-emerald-400' : 'text-gray-400'}`}>
                  <span className="opacity-40 whitespace-nowrap">[{log.timestamp}]</span>
                  <span className="font-bold whitespace-nowrap">[{log.type.toUpperCase()}]</span>
                  <span className="text-white opacity-80 break-all">{log.msg}</span>
                </div>
              ))}
            </div>
            <div className="p-6 bg-[#222] border-t border-white/5 text-[9px] text-gray-500 font-black uppercase tracking-widest flex justify-between items-center">
              <span>Host: {window.location.hostname}</span>
              <span>Total Logs: {logs.length}/100</span>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

// --- Timer Widget Component ---
const TimerWidget = () => {
  const [timeLeft, setTimeLeft] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [status, setStatus] = useState<'idle' | 'running' | 'finished'>('idle');
  const [showOther, setShowOther] = useState(false);
  const [selectedMins, setSelectedMins] = useState(0);
  const [selectedSecs, setSelectedSecs] = useState(0);

  const timerRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const alarmIntervalRef = useRef<number | null>(null);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const playAlarm = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') ctx.resume();

    const beep = (freq: number, start: number, duration: number) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, start);
      gain.gain.setValueAtTime(0, start);
      gain.gain.linearRampToValueAtTime(0.3, start + 0.05);
      gain.gain.linearRampToValueAtTime(0, start + duration);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(start);
      osc.stop(start + duration);
    };

    const now = ctx.currentTime;
    for (let i = 0; i < 3; i++) {
      beep(880, now + i * 0.3, 0.15);
    }
  };

  const startTimer = (seconds: number) => {
    setTimeLeft(seconds);
    setIsRunning(true);
    setStatus('running');
    setShowOther(false);
    if (alarmIntervalRef.current) clearInterval(alarmIntervalRef.current);
  };

  const stopTimer = () => {
    setIsRunning(false);
    setStatus('idle');
    setTimeLeft(0);
    if (timerRef.current) clearInterval(timerRef.current);
    if (alarmIntervalRef.current) clearInterval(alarmIntervalRef.current);
  };

  useEffect(() => {
    if (isRunning && timeLeft > 0) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && isRunning) {
      setIsRunning(false);
      setStatus('finished');
      playAlarm();
      alarmIntervalRef.current = window.setInterval(playAlarm, 2000);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isRunning, timeLeft]);

  // Rolling Picker Component
  const RollingPicker = ({ max, value, onChange, label }: { max: number, value: number, onChange: (val: number) => void, label: string }) => {
    const scrollRef = useRef<HTMLDivElement>(null);
    const itemHeight = 120; // Match CSS height
    const items = Array.from({ length: max + 1 }, (_, i) => i);

    useEffect(() => {
      if (scrollRef.current) {
        scrollRef.current.scrollTop = value * itemHeight;
      }
    }, []);

    const handleScroll = () => {
      if (scrollRef.current) {
        const index = Math.round(scrollRef.current.scrollTop / itemHeight);
        if (items[index] !== undefined && items[index] !== value) {
          onChange(items[index]);
        }
      }
    };

    return (
      <div className="flex flex-col items-center flex-1">
        <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4">{label}</span>
        <div className="relative h-[360px] w-full flex items-center justify-center group">
          {/* Overlay Highlight */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-[120px] bg-indigo-50/50 rounded-3xl -z-10 pointer-events-none" />

          <div 
            ref={scrollRef}
            onScroll={handleScroll}
            className="w-full h-full overflow-y-auto no-scrollbar scroll-smooth snap-y snap-mandatory py-[120px]"
          >
            {items.map(i => (
              <div 
                key={i} 
                className={`h-[120px] flex items-center justify-center snap-center transition-all duration-300 ${value === i ? 'text-gray-900 scale-125 font-black' : 'text-gray-200 scale-90 font-medium'}`}
              >
                <span className="text-7xl tabular-nums tracking-tighter">{i.toString().padStart(2, '0')}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className={`p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100 transition-all duration-500 overflow-hidden ${status !== 'idle' ? 'flex-1' : ''}`}>
      <div className="flex justify-between items-center mb-6">
        <span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] flex items-center gap-2">
          <Clock size={10} className="text-indigo-400" /> Timer
        </span>
      </div>

      {status === 'idle' ? (
        <div className="grid grid-cols-3 gap-3">
          {[5, 10, 15, 30, 45].map(m => (
            <button key={m} onClick={() => startTimer(m * 60)} className="py-4 bg-gray-50 hover:bg-indigo-50 text-gray-700 hover:text-indigo-600 rounded-2xl font-black text-sm uppercase tracking-widest transition-all active:scale-95 border border-transparent hover:border-indigo-100">{m}:00</button>
          ))}
          <button onClick={() => setShowOther(true)} className="py-4 bg-gray-50 hover:bg-gray-100 text-gray-400 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] transition-all active:scale-95">ANDER</button>
        </div>
      ) : status === 'running' ? (
        <div className="flex flex-col items-center justify-center py-6 animate-in fade-in">
          <div className="text-7xl font-black text-gray-900 tabular-nums tracking-tighter mb-8">{formatTime(timeLeft)}</div>
          <button onClick={stopTimer} className="w-16 h-16 bg-rose-50 hover:bg-rose-100 text-rose-500 rounded-full flex items-center justify-center transition-all active:scale-90 border border-rose-100 shadow-sm"><Square size={24} fill="currentColor" /></button>
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center py-6 animate-in zoom-in-95 duration-500">
          <div className="text-2xl font-black text-rose-500 uppercase tracking-[0.3em] mb-12 flex items-center gap-4">
             <Bell className="animate-bounce" /> Timer voltooid! <Bell className="animate-bounce" />
          </div>
          <button onClick={stopTimer} className="w-full py-16 bg-rose-500 hover:bg-rose-600 text-white rounded-[3rem] font-black text-5xl uppercase tracking-[0.4em] transition-all active:scale-95 shadow-2xl shadow-rose-200">Stop</button>
        </div>
      )}

      {showOther && (
        <div className="fixed inset-0 z-[1100] flex items-center justify-center animate-in fade-in duration-300 bg-white/95 backdrop-blur-3xl p-10">
          <div className="bg-white w-full max-w-2xl p-16 rounded-[4rem] shadow-2xl border border-gray-100 flex flex-col">
            <div className="flex justify-between items-center w-full mb-16">
              <h3 className="text-2xl font-black text-gray-900 uppercase tracking-widest">Kies Tijd</h3>
              <button onClick={() => setShowOther(false)} className="w-16 h-16 rounded-3xl bg-gray-50 flex items-center justify-center text-gray-400 hover:bg-gray-100 transition-colors"><X size={32} /></button>
            </div>

            <div className="flex items-center gap-12 mb-20 px-8">
              <RollingPicker max={99} value={selectedMins} onChange={setSelectedMins} label="Minuten" />
              <div className="text-5xl font-black text-gray-200 pt-10">:</div>
              <RollingPicker max={59} value={selectedSecs} onChange={setSelectedSecs} label="Seconden" />
            </div>

            <button 
              onClick={() => startTimer(selectedMins * 60 + selectedSecs)}
              className="w-full py-12 bg-indigo-600 hover:bg-indigo-700 text-white rounded-[2.5rem] font-black text-2xl uppercase tracking-[0.4em] shadow-xl shadow-indigo-100 transition-all active:scale-95"
            >
              Start Timer
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

