      <button onClick={onClose} className="absolute top-8 right-8 w-14 h-14 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white transition-all z-[210] opacity-0 group-hover:opacity-100">
