// --- Calendar ---
const Calendar = ({ accessToken, items, isLoading, onRefresh }: { accessToken: string | null; items: AgendaItem[]; isLoading: boolean; onRefresh: () => void; }) => {
  const weekDays = useMemo(() => Array.from({ length: 7 }, (_, i) => { const d = new Date(); d.setDate(d.getDate() + i); return d; }), []);
  const getEventsForDay = (date: Date) => {
    const startOfDay = new Date(date); startOfDay.setHours(0,0,0,0); const endOfDay = new Date(date); endOfDay.setHours(23,59,59,999);
    return items.filter(item => { const itemStart = new Date(item.start); const itemEnd = new Date(item.end); return item.isAllDay ? (startOfDay < itemEnd && endOfDay > itemStart) : (itemStart <= endOfDay && itemEnd >= startOfDay); });
  };
  return (
    <div className="bg-white rounded-[3rem] p-10 shadow-sm border border-gray-100 flex flex-col h-full transition-all duration-500 overflow-hidden">
      <div className="flex justify-between items-center mb-10 shrink-0"><div className="flex items-center gap-6"><h2 className="text-4xl font-light text-gray-800 tracking-tight">Week Agenda</h2>{accessToken && !isLoading && <button onClick={onRefresh} className="flex items-center gap-3 px-4 py-2 bg-blue-50 text-[11px] text-blue-600 font-black rounded-full uppercase border border-blue-100 hover:bg-blue-100"><RefreshCw size={12} className={isLoading ? "animate-spin" : ""} /> Verversen</button>}</div><div className="text-[11px] font-black text-gray-300 uppercase tracking-[0.4em]">Komende 7 dagen</div></div>
      <div className="flex-1 overflow-hidden">
        {!accessToken ? (
          <div className="h-full flex flex-col items-center justify-center text-center opacity-40"><div className="w-24 h-24 bg-blue-50 rounded-[2.5rem] flex items-center justify-center mb-2"><CalendarIcon className="w-12 h-12 text-blue-300" /></div><p className="text-gray-500 text-xl font-medium max-w-sm">Synchroniseer met Google Agenda</p></div>
        ) : isLoading ? (
          <div className="h-full flex flex-col items-center justify-center space-y-8"><Loader2 className="w-16 h-16 text-blue-400 animate-spin" /><p className="text-xs text-gray-400 font-black uppercase tracking-[0.4em] animate-pulse">Agenda ophalen...</p></div>
        ) : (
          <div className="grid grid-cols-7 h-full gap-px bg-gray-100 border border-gray-100 rounded-[2.5rem] overflow-hidden">
            {weekDays.map((date, idx) => {
              const allEvents = getEventsForDay(date); const allDayItems = allEvents.filter(e => e.isAllDay); const timedItems = allEvents.filter(e => !e.isAllDay); const today = new Date().toDateString() === date.toDateString();
              return (
                <div key={idx} className={`bg-white flex flex-col min-w-0 ${today ? 'bg-blue-50/20' : ''}`}>
                  <div className={`p-6 text-center border-b border-gray-50 shrink-0 ${today ? 'bg-blue-500/5' : ''}`}><div className={`text-[11px] font-black tracking-widest ${today ? 'text-blue-600' : 'text-gray-400'}`}>{date.toLocaleDateString('nl-BE', { weekday: 'short' }).toUpperCase()}</div><div className={`text-3xl font-black mt-1 ${today ? 'text-blue-600' : 'text-gray-800'}`}>{date.getDate()}</div></div>
                  <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar">
                    {allDayItems.map(item => <div key={item.id + date.toISOString()} onClick={() => window.open(item.htmlLink, '_blank')} style={{ backgroundColor: item.color }} className="p-3 rounded-2xl cursor-pointer hover:brightness-95 transition-all"><span className="text-[12px] font-bold text-white truncate block">{item.title}</span></div>)}
                    {timedItems.map(item => <div key={item.id + date.toISOString()} onClick={() => window.open(item.htmlLink, '_blank')} className="group bg-gray-50/50 hover:bg-white p-6 rounded-[2rem] border border-transparent hover:border-gray-100 transition-all cursor-pointer"><div className="flex items-center gap-2 mb-2"><div className="w-2 h-2 rounded-full" style={{ backgroundColor: item.color }} /><span className="text-xl font-black text-gray-900 leading-none">{item.time}</span></div><h4 className="text-2xl font-bold text-gray-800 leading-[1.2] group-hover:text-blue-600">{item.title}</h4></div>)}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

