const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('hub_access_token'));
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [agendaItems, setAgendaItems] = useState<AgendaItem[]>([]);
  const [agendaLoading, setAgendaLoading] = useState(false);
  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(() => { const cached = localStorage.getItem(WEATHER_CACHE_KEY); return cached ? JSON.parse(cached) : null; });
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [isEnergyOpen, setIsEnergyOpen] = useState(false);
  const [energyData, setEnergyData] = useState<EnergyData | null>(null);
  const [energyError, setEnergyError] = useState<string | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isPhotosOpen, setIsPhotosOpen] = useState(false);
  const tokenClientRef = useRef<any>(null);

  const handleLogout = () => { localStorage.removeItem('hub_access_token'); localStorage.removeItem(USER_CACHE_KEY); setAccessToken(null); setUser(null); setAgendaItems([]); setIsPhotosOpen(false); };
  const handleLogin = () => { setIsSyncing(true); if (tokenClientRef.current) tokenClientRef.current.requestAccessToken({ prompt: 'select_account' }); };
  const toggleFullScreen = () => { if (!document.fullscreenElement) document.documentElement.requestFullscreen(); else document.exitFullscreen(); };

  useEffect(() => {
    const clockTimer = setInterval(() => setCurrentDate(new Date()), 1000);
    const fullscreenHandler = () => setIsFullscreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', fullscreenHandler);
    const initGsi = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID, scope: SCOPES,
          callback: async (response: any) => {
            if (response.access_token) { setAccessToken(response.access_token); localStorage.setItem('hub_access_token', response.access_token); await fetchUserProfile(response.access_token); await fetchCalendarEvents(response.access_token); }
            setIsSyncing(false);
          },
        });
        if (accessToken) { fetchUserProfile(accessToken).catch(() => handleLogout()); fetchCalendarEvents(accessToken).catch(() => handleLogout()); }
      } else { setTimeout(initGsi, 500); }
    };
    initGsi(); if (!weatherData) fetchWeatherForecast(false);
    return () => { clearInterval(clockTimer); document.removeEventListener('fullscreenchange', fullscreenHandler); };
  }, []);

  const fetchUserProfile = async (token: string) => { 
    const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', { headers: { Authorization: `Bearer ${token}` } });
    if (resp.status === 401) { handleLogout(); return; }
    const data = await resp.json(); setUser({ given_name: data.given_name, name: data.name, picture: data.picture }); 
  };
  const fetchCalendarEvents = async (token: string) => { 
    setAgendaLoading(true); try { 
      const now = new Date(); const start = new Date(now); start.setHours(0,0,0,0); const end = new Date(now); end.setDate(now.getDate() + 30); 
      const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${start.toISOString()}&timeMax=${end.toISOString()}&singleEvents=true&orderBy=startTime`; 
      const resp = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
      const data = await resp.json(); 
      const mapped = data.items.map((event: any) => { 
        const isAllDay = !event.start.dateTime; const startRaw = event.start.dateTime || event.start.date; const startDate = isAllDay ? new Date(startRaw + 'T00:00:00') : new Date(startRaw); 
        let timeStr = ''; if (!isAllDay) timeStr = `${new Date(event.start.dateTime).toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit', hour12: false})}`; 
        return { id: event.id, start: startDate, end: new Date(event.end.dateTime || event.end.date), time: timeStr, title: (event.summary || '(Geen titel)').replace(/\s*\d{1,2}u\d{0,2}(?:-\d{1,2}u\d{0,2})?$/, '').trim(), location: event.location || '', category: 'personal', color: GOOGLE_COLOR_MAP[event.colorId] || '#10b981', isAllDay, htmlLink: event.htmlLink }; 
      }); setAgendaItems(mapped); 
    } catch (e) { console.error(e); } finally { setAgendaLoading(false); } 
  };
  async function fetchWeatherForecast(triggerOverlay = true) { 
    if (triggerOverlay) setIsWeatherOpen(true); setWeatherLoading(true); 
    try { 
      const lat = 51.1378, lon = 4.7570; const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&hourly=temperature_2m,weather_code&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=7`; 
      const resp = await fetch(url); const data = await resp.json(); 
      const days = ['Zondag', 'Maandag', 'Dinsdag', 'Woensdag', 'Donderdag', 'Vrijdag', 'Zaterdag']; const now = new Date(); const nextHourIndex = data.hourly.time.findIndex((t: string) => new Date(t) > now); 
      const formatted: WeatherData = { location: "Herenthout", currentTemp: Math.round(data.current.temperature_2m), condition: getWeatherInfo(data.current.weather_code).text, humidity: data.current.relative_humidity_2m, windSpeed: `${Math.round(data.current.wind_speed_10m)} km/u`, hourly: data.hourly.time.slice(nextHourIndex, nextHourIndex + 12).map((t: string, i: number) => ({ time: new Date(t).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit' }), temp: Math.round(data.hourly.temperature_2m[nextHourIndex + i]), icon: getWeatherInfo(data.hourly.weather_code[nextHourIndex + i]).icon })), daily: data.daily.time.slice(0, 7).map((t: string, i: number) => { const info = getWeatherInfo(data.daily.weather_code[i]); return { day: days[new Date(t).getDay()], low: Math.round(data.daily.temperature_2m_min[i]), high: Math.round(data.daily.temperature_2m_max[i]), condition: info.text, icon: info.icon }; }) }; 
      setWeatherData(formatted); localStorage.setItem(WEATHER_CACHE_KEY, JSON.stringify(formatted)); 
    } catch (e) { console.error(e); } finally { setWeatherLoading(false); } 
  }

  return (
    <div className="min-h-screen w-full bg-[#fcfcfc] flex flex-col animate-in fade-in overflow-hidden">
      <header className="w-full px-[50px] pt-16 pb-4 flex flex-col md:flex-row md:items-end justify-between shrink-0 relative z-[300]">
        <div className="flex flex-col md:flex-row items-center md:items-baseline gap-16 text-left relative z-[310]">
          <div className="flex flex-col">
            <div className="text-[7rem] sm:text-[9rem] font-black tracking-tighter text-gray-900 leading-[0.8] tabular-nums select-none drop-shadow-sm">
              {currentDate.toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit', hour12: false })}
            </div>
            <div className="flex items-center gap-6 mt-6 px-2"><CalendarIcon className="w-6 h-6 text-gray-200" /><p className="text-gray-400 text-sm uppercase tracking-[0.5em] font-black">{currentDate.toLocaleDateString('nl-BE', { weekday: 'long', month: 'long', day: 'numeric' })}</p></div>
          </div>
          <h1 className="text-5xl sm:text-7xl font-extralight tracking-tighter text-gray-300 leading-none">{currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}</h1>
        </div>
        <div className="mt-10 md:mt-0 flex flex-col items-end gap-10 self-start md:self-end">
          <div className="flex items-center gap-10">
            {accessToken && (
              <button onClick={() => setIsPhotosOpen(!isPhotosOpen)} className={`w-16 h-16 border rounded-[2rem] shadow-xl flex items-center justify-center transition-all active:scale-95 ${isPhotosOpen ? 'bg-blue-600 border-blue-500 text-white' : 'bg-white border-gray-100 text-gray-400'}`} title="Google Photos">
                <ImageIcon size={24} />
              </button>
            )}
            <button onClick={toggleFullScreen} className="w-16 h-16 bg-white border border-gray-100 rounded-[2rem] shadow-xl flex items-center justify-center text-gray-400 hover:text-gray-900 transition-all active:scale-95">
              {isFullscreen ? <Minimize size={24} /> : <Maximize size={24} />}
