  return (
    <button onClick={onClick} className="w-full p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100 text-left hover:border-emerald-400 hover:shadow-xl transition-all group active:scale-[0.98] touch-manipulation overflow-hidden">
      <div className="flex justify-between items-center mb-6">
