          </div>

          <div className="space-y-5 border-l border-gray-100 pl-8">
            <div className="flex items-center gap-4">
              <Sun size={24} className="text-amber-400" />
              <span className="text-2xl font-black text-gray-800 tabular-nums">{data ? data.solarTotal : '--'}W</span>
            </div>
            <div className="flex items-center gap-4">
              <UtilityPole size={24} className="text-blue-400" />
              <span className="text-2xl font-black text-gray-800 tabular-nums">{data ? data.gridTotal : '--'}W</span>
            </div>
            <div className="flex items-center gap-4">
              <BatteryIcon size={24} className="text-emerald-500" />
              <div className="flex items-center gap-2">
                <span className="text-2xl font-black text-gray-800 tabular-nums">{data ? data.batteryPower : '--'}W</span>
                <BatteryIndicator />
              </div>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 border-t border-gray-50 pt-8">
          <div className="flex flex-col gap-2">
            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Batterij</span>
            <div className="flex items-center gap-3">
               <div className="w-2.5 h-5 border-2 border-emerald-400 rounded-[2px] relative flex items-end">
                  <div className="w-full bg-emerald-400" style={{ height: `${data?.soc || 0}%` }} />
               </div>
               <span className="text-2xl font-black text-gray-900 tabular-nums">{data ? data.soc : '--'}%</span>
            </div>
          </div>
          <div className="flex flex-col gap-2 text-right">
            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">EV Lader</span>
            <div className="flex items-center justify-end gap-4">
               <Car size={28} className={data?.evStatus.toLowerCase().includes('idle') || data?.evPower < 10 ? "text-gray-200" : "text-blue-500"} />
               <span className={`text-2xl font-black tabular-nums ${data?.evStatus.toLowerCase().includes('idle') || data?.evPower < 10 ? "text-gray-400" : "text-gray-900"}`}>
