// --- Main App Component ---
const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('hub_access_token'));
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [agendaItems, setAgendaItems] = useState<AgendaItem[]>([]);
  const [agendaLoading, setAgendaLoading] = useState(false);
  const [isAgendaCollapsed, setIsAgendaCollapsed] = useState(false);
  const [activeMainView, setActiveMainView] = useState<'agenda' | 'photos'>('agenda');
  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(() => { const cached = localStorage.getItem(WEATHER_CACHE_KEY); return cached ? JSON.parse(cached) : null; });
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [isEnergyOpen, setIsEnergyOpen] = useState(false);
  const [energyData, setEnergyData] = useState<EnergyData | null>(null);
  const [energyLoading, setEnergyLoading] = useState(false);
  const [energyError, setEnergyError] = useState<string | null>(null);
  const energySyncTimerRef = useRef<number | null>(null);
  const tokenClientRef = useRef<any>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const handleLogout = () => { localStorage.removeItem('hub_access_token'); localStorage.removeItem(USER_CACHE_KEY); setAccessToken(null); setUser(null); setAgendaItems([]); };
  const handleLogin = () => { setIsSyncing(true); if (tokenClientRef.current) tokenClientRef.current.requestAccessToken({ prompt: 'select_account' }); };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
      }
    }
  };

  useEffect(() => {
    const clockTimer = setInterval(() => setCurrentDate(new Date()), 1000);
    const fullscreenHandler = () => setIsFullscreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', fullscreenHandler);

    const initGsi = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID, scope: SCOPES,
          callback: async (response: any) => {
            if (response.access_token) { setAccessToken(response.access_token); localStorage.setItem('hub_access_token', response.access_token); await fetchUserProfile(response.access_token, true); await fetchCalendarEvents(response.access_token); }
            setIsSyncing(false);
          },
        });
        if (accessToken) { fetchUserProfile(accessToken).catch(() => handleLogout()); fetchCalendarEvents(accessToken).catch(() => handleLogout()); }
      } else { setTimeout(initGsi, 500); }
    };
    initGsi(); startEnergySync(); if (!weatherData) fetchWeatherForecast(false);
    return () => { 
      clearInterval(clockTimer); 
      document.removeEventListener('fullscreenchange', fullscreenHandler);
      if (energySyncTimerRef.current) clearInterval(energySyncTimerRef.current); 
    };
  }, []);

  const fetchUserProfile = async (token: string, force = false) => { 
    const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', { headers: { Authorization: `Bearer ${token}` } }); if (resp.status === 401) { handleLogout(); return; }
    const data = await resp.json(); setUser({ given_name: data.given_name, name: data.name, picture: data.picture }); 
  };

  const fetchCalendarEvents = async (token: string) => { 
    setAgendaLoading(true); 
    try { 
      const now = new Date(); const start = new Date(now); start.setHours(0,0,0,0); const end = new Date(now); end.setDate(now.getDate() + 30); 
      const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${start.toISOString()}&timeMax=${end.toISOString()}&singleEvents=true&orderBy=startTime`; 
      const resp = await fetch(url, { headers: { Authorization: `Bearer ${token}` } }); if (resp.status === 401) { handleLogout(); return; }
      const data = await resp.json(); 
      const mapped = data.items.map((event: any) => { 
        const isAllDay = !event.start.dateTime; const startRaw = event.start.dateTime || event.start.date; const endDateRaw = event.end.dateTime || event.end.date; 
        const startDate = isAllDay ? new Date(startRaw + 'T00:00:00') : new Date(startRaw); const endDate = isAllDay ? new Date(endDateRaw + 'T00:00:00') : new Date(endDateRaw); 
        let timeStr = ''; if (!isAllDay) { timeStr = `${new Date(event.start.dateTime).toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit', hour12: false})}`; } 
        const eventColor = GOOGLE_COLOR_MAP[event.colorId] || '#10b981';
        const rawSummary = event.summary || '(Geen titel)';
        const cleanTitle = rawSummary.replace(/\s*\d{1,2}u\d{0,2}(?:-\d{1,2}u\d{0,2})?$/, '').trim();
        return { id: event.id, start: startDate, end: endDate, time: timeStr, title: cleanTitle, location: event.location || '', category: 'personal', color: eventColor, isAllDay, htmlLink: event.htmlLink }; 
      }); setAgendaItems(mapped); 
    } catch (e) { console.error(e); } finally { setAgendaLoading(false); } 
  };

  async function fetchWeatherForecast(triggerOverlay = true) { 
    if (triggerOverlay) setIsWeatherOpen(true); setWeatherLoading(true); 
    try { 
      const lat = 51.1378, lon = 4.7570; 
      const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&hourly=temperature_2m,weather_code&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=7`; 
      const resp = await fetch(url); const data = await resp.json(); 
      const days = ['Zondag', 'Maandag', 'Dinsdag', 'Woensdag', 'Donderdag', 'Vrijdag', 'Zaterdag']; const now = new Date(); const nextHourIndex = data.hourly.time.findIndex((t: string) => new Date(t) > now); 
      const hourlyData = data.hourly.time.slice(nextHourIndex, nextHourIndex + 12).map((t: string, i: number) => ({ time: new Date(t).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit' }), temp: Math.round(data.hourly.temperature_2m[nextHourIndex + i]), icon: getWeatherInfo(data.hourly.weather_code[nextHourIndex + i]).icon })); 
      const weatherInfo = getWeatherInfo(data.current.weather_code); 
      const formatted: WeatherData = { location: "Herenthout", currentTemp: Math.round(data.current.temperature_2m), condition: weatherInfo.text, humidity: data.current.relative_humidity_2m, windSpeed: `${Math.round(data.current.wind_speed_10m)} km/u`, lastUpdated: Date.now(), hourly: hourlyData, daily: data.daily.time.slice(0, 7).map((t: string, i: number) => { const info = getWeatherInfo(data.daily.weather_code[i]); return { day: days[new Date(t).getDay()], low: Math.round(data.daily.temperature_2m_min[i]), high: Math.round(data.daily.temperature_2m_max[i]), condition: info.text, icon: info.icon }; }) }; setWeatherData(formatted); localStorage.setItem(WEATHER_CACHE_KEY, JSON.stringify(formatted)); 
    } catch (e) { console.error(e); } finally { setWeatherLoading(false); } 
  }

  const startEnergySync = () => { 
    if (energySyncTimerRef.current) clearInterval(energySyncTimerRef.current); 
    const sync = async () => { 
      try { 
        const resp = await fetch(ENERGY_ENDPOINT); const data = await resp.json();
        setEnergyData({
          houseLoad: data.grid?.ac_power?.value || 0,
          evPower: data.ev?.current_power?.value || 0, evChargedToday: data.ev?.charged_today?.value || 0, evChargedMonth: data.ev?.charged_month?.value || 0, evTotalCounter: data.ev?.total_counter?.value || 0, evStatus: data.ev?.status?.value || 'Idle',
          solarTotal: data.solar?.total_power?.value || 0, solarAC: data.solar?.ac_power?.value || 0, solarDC: data.solar?.dc_power?.value || 0, solarDCDay: data.solar?.dc_pv_total?.value || 0, solarACDay: data.solar?.ac_pv_totalday?.value || 0, solarTotalDay: data.solar?.total_powerday?.value || 0,
          gridTotal: data.grid?.total_power?.value || 0, gridSetpoint: data.grid?.setpoint?.value || 0,
          soc: data.battery?.soc?.value || 0, batteryStatus: data.battery?.status?.value || 'Idle', batteryPower: data.battery?.power?.value || 0,
          forecastPrediction: parseFloat(data.forecast?.prediction?.value || "0"), forecastSummary: data.forecast?.summary?.value || 'Laden...',
          timestamp: data.meta?.timestamp || new Date().toISOString()
        }); setEnergyError(null); 
      } catch (e: any) { setEnergyError("Geen dataverbinding"); } 
    }; sync(); energySyncTimerRef.current = window.setInterval(sync, 2000); 
  };

  return (
    <div className="min-h-screen w-full bg-[#fcfcfc] flex flex-col animate-in fade-in">
