        <button onClick={onForceLogout} className="px-8 py-4 bg-gray-900 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest hover:bg-black transition-all active:scale-95 flex items-center gap-3"><LogOut size={14} /> Log uit en log opnieuw in</button>
