const Calendar = ({ accessToken, items, isLoading, onRefresh, isCollapsed, onToggleCollapse }: { accessToken: string | null; items: AgendaItem[]; isLoading: boolean; onRefresh: () => void; isCollapsed: boolean; onToggleCollapse: () => void; }) => {
  const weekDays = useMemo(() => Array.from({ length: 7 }, (_, i) => { const d = new Date(); d.setDate(d.getDate() + i); return d; }), []);

  const getEventsForDay = (date: Date) => {
    const startOfDay = new Date(date); startOfDay.setHours(0,0,0,0); 
    const endOfDay = new Date(date); endOfDay.setHours(23,59,59,999);

    return items.filter(item => { 
      const itemStart = new Date(item.start); 
      const itemEnd = new Date(item.end); 

      if (item.isAllDay) {
        const colDateStr = date.toLocaleDateString('en-CA'); 
        const evDateStr = itemStart.toLocaleDateString('en-CA');
        return colDateStr === evDateStr;
      }
      return (itemStart <= endOfDay && itemEnd >= startOfDay); 
    });
  };

  return (
    <div className={`bg-white rounded-[3rem] p-10 shadow-sm border border-gray-100 flex flex-col transition-all duration-500 overflow-hidden ${isCollapsed ? 'h-auto' : 'h-full'}`}>
      <div className="flex justify-between items-center shrink-0"><div className="flex items-center gap-6"><h2 className="text-4xl font-light text-gray-800 tracking-tight">Week Agenda</h2>{!isCollapsed && accessToken && !isLoading && ( <button onClick={onRefresh} className="flex items-center gap-3 px-4 py-2 bg-blue-50 text-[11px] text-blue-600 font-black rounded-full uppercase tracking-widest border border-blue-100 hover:bg-blue-100"><RefreshCw size={12} className={isLoading ? "animate-spin" : ""} /> Verversen</button> )}</div><div className="flex items-center gap-8"><div className="text-[11px] font-black text-gray-300 uppercase tracking-[0.4em]">Komende 7 dagen</div><button onClick={onToggleCollapse} className="w-12 h-12 flex items-center justify-center bg-gray-50 hover:bg-gray-100 text-gray-400 rounded-2xl transition-all active:scale-90">{isCollapsed ? <ChevronDown size={24} /> : <ChevronUp size={24} />}</button></div></div>
      {!isCollapsed && ( <div className="flex-1 overflow-hidden mt-10 animate-in fade-in">{!accessToken ? ( <div className="h-full flex flex-col items-center justify-center text-center space-y-8 px-10 opacity-40"><div className="w-24 h-24 bg-blue-50 rounded-[2.5rem] flex items-center justify-center mb-2"><CalendarIcon className="w-12 h-12 text-blue-300" /></div><p className="text-gray-500 text-xl font-medium max-w-sm">Synchroniseer met Google Agenda om je weekplanning te zien</p></div> ) : isLoading ? ( <div className="h-full flex flex-col items-center justify-center space-y-8"><Loader2 className="w-16 h-16 text-blue-400 animate-spin" /><p className="text-xs text-gray-400 font-black uppercase tracking-[0.4em] animate-pulse">Agenda ophalen...</p></div> ) : ( <div className="grid grid-cols-7 h-full gap-px bg-gray-100 border border-gray-100 rounded-[2.5rem] overflow-hidden">{weekDays.map((date, idx) => { const allEvents = getEventsForDay(date); const allDayItems = allEvents.filter(e => e.isAllDay); const timedItems = allEvents.filter(e => !e.isAllDay); const today = new Date().toDateString() === date.toDateString(); return ( <div key={idx} className={`bg-white flex flex-col min-w-0 ${today ? 'bg-blue-50/20' : ''}`}><div className={`p-6 text-center border-b border-gray-50 shrink-0 ${today ? 'bg-blue-500/5' : ''}`}><div className={`text-[11px] font-black tracking-widest ${today ? 'text-blue-600' : 'text-gray-400'}`}>{date.toLocaleDateString('nl-BE', { weekday: 'short' }).toUpperCase()}</div><div className={`text-3xl font-black mt-1 ${today ? 'text-blue-600' : 'text-gray-800'}`}>{date.getDate()}</div></div><div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar">

      {allDayItems.map(item => ( 
        <div 
          key={item.id + date.toISOString()} 
          onClick={() => window.open(item.htmlLink, '_blank')} 
          style={{ backgroundColor: item.color || '#9ca3af' }} 
          className="p-6 rounded-[2rem] cursor-pointer hover:brightness-95 active:scale-95 transition-all shadow-sm border border-black/5"
        >
          <span className="text-[20px] font-black leading-[1.15] block line-clamp-2 text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.3)]">
            {item.title}
          </span>
        </div> 
      ))} 

      {timedItems.map((item) => ( 
        <div key={item.id + date.toISOString()} onClick={() => window.open(item.htmlLink, '_blank')} className="group bg-gray-50/50 hover:bg-white p-6 rounded-[2rem] border border-transparent hover:border-gray-100 transition-all cursor-pointer">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: item.color || '#d1d5db' }} />
            <span className="text-xl font-black text-gray-900 leading-none">{item.time}</span>
          </div>
          <h4 className="text-2xl font-bold text-gray-800 leading-[1.2] group-hover:text-blue-600">{item.title}</h4>
        </div> 
      ))}

      </div></div> ); })}</div> )}</div> )}
    </div>
  );
};

const TaskWidget = () => (
  <div className="p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100 flex-1"><span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.3em] block mb-6">Takenlijst</span><div className="space-y-4">{[{ label: 'Check Meteo Herenthout', time: '09:00' }, { label: 'Node-RED Monitor', time: '11:30' }, { label: 'Hub Onderhoud', time: '20:00' }].map((task, i) => ( <div key={i} className="flex items-center gap-4 p-4 hover:bg-gray-50 rounded-2xl transition-colors cursor-pointer group"><div className="w-8 h-8 rounded-xl border-2 border-gray-100 group-hover:border-blue-400 transition-colors" /><div className="flex-1"><div className="text-sm font-bold text-gray-700">{task.label}</div><div className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{task.time}</div></div></div> ))}</div></div>
);

const EnergyWidget = ({ data, error, onClick }: { data: EnergyData | null, error: string | null, onClick: () => void }) => {
  const evDisplay = useMemo(() => { if (!data) return '--'; return (data.evStatus.toLowerCase().includes('idle') || data.evPower < 10) ? 'Idle' : `${data.evPower}W`; }, [data]);
  return (
    <button onClick={onClick} className="w-full p-8 bg-white rounded-[2.5rem] shadow-sm border border-gray-100 text-left hover:border-emerald-400 hover:shadow-xl transition-all active:scale-[0.98] overflow-hidden">
      <div className="flex justify-between items-center mb-6"><span className="text-[10px] font-black text-gray-300 uppercase tracking-[0.4em] flex items-center gap-2"><Zap size={10} className="text-emerald-500" /> Energie Status</span>{error ? (<span className="text-[9px] font-black text-rose-500 uppercase flex items-center gap-1"><AlertTriangle size={10}/> {error}</span>) : (<span className="text-[9px] font-black text-emerald-500 uppercase flex items-center gap-1"><CheckCircle2 size={10}/> LIVE</span>)}</div>
      <div className="space-y-8"><div className="flex items-center justify-between gap-6"><div className="flex-1"><p className="text-[12px] font-black text-gray-400 uppercase tracking-[0.2em] mb-1">Huis Verbruik</p><div className="flex items-baseline gap-2"><p className="text-7xl font-black text-gray-900 leading-none tracking-tighter tabular-nums">{data ? data.houseLoad : '---'}</p><span className="text-2xl font-bold text-gray-300">W</span></div></div><div className="space-y-5 border-l border-gray-100 pl-8"><div className="flex items-center gap-4"><Sun size={24} className="text-amber-400" /><span className="text-2xl font-black text-gray-800 tabular-nums">{data ? `${data.solarTotal}W` : '--W'}</span></div><div className="flex items-center gap-4"><UtilityPole size={24} className="text-blue-400" /><span className="text-2xl font-black text-gray-800 tabular-nums">{data ? `${data.gridTotal}W` : '--W'}</span></div><div className="flex items-center gap-4"><BatteryIcon size={24} className="text-emerald-500" /><div className="flex items-center gap-2"><span className="text-2xl font-black text-gray-800 tabular-nums">{data ? `${data.batteryPower}W` : '--W'}</span></div></div></div></div><div className="grid grid-cols-2 gap-4 border-t border-gray-50 pt-8"><div className="flex flex-col gap-2"><span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Batterij</span><div className="flex items-center gap-3"><div className="w-2.5 h-5 border-2 border-emerald-400 rounded-[2px] relative flex items-end"><div className="w-full bg-emerald-400" style={{ height: `${data?.soc || 0}%` }} /></div><span className="text-2xl font-black text-gray-900 tabular-nums">{data ? `${data.soc}%` : '--%'}</span></div></div><div className="flex flex-col gap-2 text-right"><span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">EV Lader</span><div className="flex items-center justify-end gap-4"><Car size={28} className={(data?.evStatus.toLowerCase().includes('idle') || data?.evPower < 10) ? "text-gray-200" : "text-blue-500"} /><span className={`text-2xl font-black tabular-nums ${(data?.evStatus.toLowerCase().includes('idle') || data?.evPower < 10) ? "text-gray-400" : "text-gray-900"}`}>{evDisplay}</span></div></div></div></div>
    </button>
  );
};

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [accessToken, setAccessToken] = useState<string | null>(localStorage.getItem('hub_access_token'));
  const [grantedScopes, setGrantedScopes] = useState<string>(localStorage.getItem('hub_granted_scopes') || "");
  const [user, setUser] = useState<any>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [agendaItems, setAgendaItems] = useState<AgendaItem[]>([]);
  const [agendaLoading, setAgendaLoading] = useState(false);
  const [isAgendaCollapsed, setIsAgendaCollapsed] = useState(false);
  const [activeMainView, setActiveMainView] = useState<'agenda' | 'photos'>('agenda');
  const [isWeatherOpen, setIsWeatherOpen] = useState(false);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(() => { const cached = localStorage.getItem(WEATHER_CACHE_KEY); return cached ? JSON.parse(cached) : null; });
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [isEnergyOpen, setIsEnergyOpen] = useState(false);
  const [energyData, setEnergyData] = useState<EnergyData | null>(null);
  const [energyError, setEnergyError] = useState<string | null>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const tokenClientRef = useRef<any>(null);

  const handleLogout = () => { 
    localStorage.removeItem('hub_access_token'); 
    localStorage.removeItem('hub_granted_scopes');
    localStorage.removeItem(USER_CACHE_KEY); 
    setAccessToken(null); 
    setGrantedScopes("");
    setUser(null); 
    setAgendaItems([]); 
  };

  const handleLogin = () => { 
    setIsSyncing(true); 
    if (tokenClientRef.current) {
      // Forceer select_account AND consent om verse scopes te krijgen
      tokenClientRef.current.requestAccessToken({ 
        prompt: 'select_account consent'
      }); 
    } 
  };

  const toggleFullScreen = () => { if (!document.fullscreenElement) document.documentElement.requestFullscreen(); else document.exitFullscreen(); };

  useEffect(() => {
    const clockTimer = setInterval(() => setCurrentDate(new Date()), 1000);
    const fullscreenHandler = () => setIsFullscreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', fullscreenHandler);
    const initGsi = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID, 
          scope: SCOPES,
          callback: async (response: any) => {
            if (response.access_token) { 
               console.log("Nieuw Token. Granted Scopes:", response.scope);
               setAccessToken(response.access_token); 
               setGrantedScopes(response.scope || "");
               localStorage.setItem('hub_access_token', response.access_token); 
               localStorage.setItem('hub_granted_scopes', response.scope || "");
               await fetchUserProfile(response.access_token); 
               await fetchCalendarEvents(response.access_token); 
            }
            setIsSyncing(false);
          },
        });
        if (accessToken) { fetchUserProfile(accessToken).catch(() => handleLogout()); fetchCalendarEvents(accessToken).catch(() => handleLogout()); }
      } else { setTimeout(initGsi, 500); }
    };
    initGsi(); startEnergySync(); if (!weatherData) fetchWeatherForecast(false);
    return () => { clearInterval(clockTimer); document.removeEventListener('fullscreenchange', fullscreenHandler); };
  }, []);

  const fetchUserProfile = async (token: string) => { 
    const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', { headers: { Authorization: `Bearer ${token}` } }); if (resp.status === 401) { handleLogout(); return; }
    const data = await resp.json(); setUser({ name: data.name, picture: data.picture }); 
  };

  const fetchCalendarEvents = async (token: string) => { 
    setAgendaLoading(true); 
    try { 
      const now = new Date(); const start = new Date(now); start.setHours(0,0,0,0); const end = new Date(now); end.setDate(now.getDate() + 30); 
      const resp = await fetch(`https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${start.toISOString()}&timeMax=${end.toISOString()}&singleEvents=true&orderBy=startTime`, { headers: { Authorization: `Bearer ${token}` } });
      const data = await resp.json(); 
      if (data.items) { 
        const mapped = data.items.map((event: any) => { 
          const isAllDay = !event.start.dateTime; 
          const startRaw = event.start.dateTime || event.start.date; 
          const startDate = isAllDay ? new Date(startRaw + 'T00:00:00') : new Date(startRaw);
          return { 
            id: event.id, 
            start: startDate, 
            end: new Date(event.end.dateTime || event.end.date), 
            time: !isAllDay ? new Date(event.start.dateTime).toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit'}) : '', 
            title: event.summary || '(Geen titel)', 
            color: GOOGLE_COLOR_MAP[event.colorId] || '#10b981', 
            isAllDay, 
            htmlLink: event.htmlLink 
          }; 
        }); 
        setAgendaItems(mapped); 
      }
    } catch (e) { console.error(e); } finally { setAgendaLoading(false); } 
  };

  async function fetchWeatherForecast(triggerOverlay = true) { 
    if (triggerOverlay) setIsWeatherOpen(true); setWeatherLoading(true); try { 
      const resp = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=51.1378&longitude=4.7570&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&hourly=temperature_2m,weather_code&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto`); 
      const data = await resp.json(); const now = new Date(); const nextHourIndex = data.hourly.time.findIndex((t: string) => new Date(t) > now); 
      setWeatherData({ location: "Herenthout", currentTemp: Math.round(data.current.temperature_2m), condition: getWeatherInfo(data.current.weather_code).text, humidity: data.current.relative_humidity_2m, windSpeed: `${Math.round(data.current.wind_speed_10m)} km/u`, hourly: data.hourly.time.slice(nextHourIndex, nextHourIndex + 12).map((t: string, i: number) => ({ time: new Date(t).toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit' }), temp: Math.round(data.hourly.temperature_2m[nextHourIndex + i]), icon: getWeatherInfo(data.hourly.weather_code[nextHourIndex + i]).icon })), daily: data.daily.time.slice(0, 7).map((t: string, i: number) => { const info = getWeatherInfo(data.daily.weather_code[i]); return { day: ['Zondag', 'Maandag', 'Dinsdag', 'Woensdag', 'Donderdag', 'Vrijdag', 'Zaterdag'][new Date(t).getDay()], low: Math.round(data.daily.temperature_2m_min[i]), high: Math.round(data.daily.temperature_2m_max[i]), condition: info.text, icon: info.icon }; }) });
    } catch (e) { console.error(e); } finally { setWeatherLoading(false); } 
  }
  const startEnergySync = () => { setInterval(async () => { try { const resp = await fetch(ENERGY_ENDPOINT); const data = await resp.json(); setEnergyData({ houseLoad: data.grid?.ac_power?.value || 0, evPower: data.ev?.current_power?.value || 0, evChargedToday: data.ev?.charged_today?.value || 0, evChargedMonth: data.ev?.charged_month?.value || 0, evTotalCounter: data.ev?.total_counter?.value || 0, evStatus: data.ev?.status?.value || 'Idle', solarTotal: data.solar?.total_power?.value || 0, solarAC: data.solar?.ac_power?.value || 0, solarDC: data.solar?.dc_power?.value || 0, solarDCDay: data.solar?.dc_pv_total?.value || 0, solarACDay: data.solar?.ac_pv_totalday?.value || 0, solarTotalDay: data.solar?.total_powerday?.value || 0, gridTotal: data.grid?.total_power?.value || 0, gridSetpoint: data.grid?.setpoint?.value || 0, soc: data.battery?.soc?.value || 0, batteryStatus: data.battery?.status?.value || 'Idle', batteryPower: data.battery?.power?.value || 0, forecastPrediction: parseFloat(data.forecast?.prediction?.value || "0"), forecastSummary: data.forecast?.summary?.value || 'Laden...', timestamp: new Date().toISOString() }); setEnergyError(null); } catch (e) { setEnergyError("Geen verbinding"); } }, 2000); };

  return (
    <div className="min-h-screen w-full bg-[#fcfcfc] flex flex-col animate-in fade-in">
      <header className="w-full px-[50px] pt-16 pb-4 flex flex-col md:flex-row md:items-end justify-between shrink-0">
        <div className="flex flex-col md:flex-row items-center md:items-baseline gap-16 text-left">
          <div className="flex flex-col"><div className="text-[7rem] sm:text-[9rem] font-black tracking-tighter text-gray-900 leading-[0.8] tabular-nums">{currentDate.toLocaleTimeString('nl-BE', { hour: '2-digit', minute: '2-digit' })}</div><div className="flex items-center gap-6 mt-6 px-2"><CalendarIcon className="w-6 h-6 text-gray-200" /><p className="text-gray-400 text-sm uppercase tracking-[0.5em] font-black">{currentDate.toLocaleDateString('nl-BE', { weekday: 'long', month: 'long', day: 'numeric' })}</p></div></div>
          <h1 className="text-5xl sm:text-7xl font-extralight tracking-tighter text-gray-300 leading-none">{currentDate.getHours() < 12 ? 'Goedemorgen' : currentDate.getHours() < 18 ? 'Goedemiddag' : 'Goedenavond'}</h1>
        </div>
        <div className="mt-10 md:mt-0 flex flex-col items-end gap-10">
          <div className="flex items-center gap-10">
            {accessToken && ( <button onClick={() => setActiveMainView(activeMainView === 'agenda' ? 'photos' : 'agenda')} className={`w-16 h-16 border rounded-[2rem] shadow-xl flex items-center justify-center transition-all ${activeMainView === 'photos' ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-white border-gray-100 text-gray-400 hover:text-gray-900'}`}>{activeMainView === 'agenda' ? <ImageIcon size={24} /> : <CalendarIcon size={24} />}</button> )}
            <button onClick={toggleFullScreen} className="w-16 h-16 bg-white border border-gray-100 rounded-[2rem] shadow-xl flex items-center justify-center text-gray-400 hover:text-gray-900">{isFullscreen ? <Minimize size={24} /> : <Maximize size={24} />}</button>
            {!accessToken ? (<button onClick={handleLogin} disabled={isSyncing} className="px-12 py-6 bg-gray-900 text-white rounded-[2.5rem] text-[13px] font-black uppercase tracking-widest shadow-2xl">Google Sync</button>) : ( <div className="flex items-center gap-8 bg-white p-4 pr-10 rounded-[2.5rem] border border-gray-100 shadow-xl cursor-pointer" onClick={handleLogout}><div className="w-16 h-16 bg-gray-100 rounded-3xl overflow-hidden border border-gray-50"><img src={user?.picture} alt="" className="w-full h-full object-cover" /></div><div className="text-right"><div className="text-[13px] font-black text-gray-900 uppercase tracking-widest">{user?.name}</div><div className="text-[10px] text-green-500 font-bold flex items-center justify-end gap-2 mt-1"><CheckCircle2 size={12}/> ONLINE</div></div></div> )}
            <WeatherWidget data={weatherData} onClick={() => fetchWeatherForecast(true)} isRefreshing={weatherLoading} />
          </div>
          <div className="text-[12px] font-black text-gray-300 uppercase tracking-[0.5em]">HERENTHOUT, BELGIË</div>
        </div>
      </header>
      <main className="w-full px-[50px] pt-3 pb-10 grid grid-cols-1 xl:grid-cols-10 gap-10 flex-1 overflow-hidden">
        <section className="xl:col-span-7 h-full">{activeMainView === 'agenda' ? ( <Calendar accessToken={accessToken} items={agendaItems} isLoading={agendaLoading} onRefresh={() => accessToken && fetchCalendarEvents(accessToken)} isCollapsed={isAgendaCollapsed} onToggleCollapse={() => setIsAgendaCollapsed(!isAgendaCollapsed)} /> ) : ( <GooglePhotosWidget accessToken={accessToken} grantedScopes={grantedScopes} onForceLogout={handleLogout} /> )}</section>
        <aside className="xl:col-span-3 space-y-10 flex flex-col h-full overflow-y-auto no-scrollbar"><EnergyWidget data={energyData} error={energyError} onClick={() => setIsEnergyOpen(true)} /><TimerWidget /><GeminiAssistantWidget /><TaskWidget /></aside>
      </main>
      {isWeatherOpen && <WeatherOverlay onClose={() => setIsWeatherOpen(false)} weatherData={weatherData} loading={weatherLoading} />}
      {isEnergyOpen && <EnergyOverlay data={energyData} onClose={() => setIsEnergyOpen(false)} />}
    </div>
  );
};

