const GooglePhotosWidget = ({ accessToken, grantedScopes, onForceLogout }: { accessToken: string | null, grantedScopes: string, onForceLogout: () => void }) => {
  const [photos, setPhotos] = useState<any[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<{status: string, message: string} | null>(null);

  const fetchPhotos = async () => {
    if (!accessToken) return;
    setLoading(true); setError(null);
    try {
      const response = await fetch('https://photoslibrary.googleapis.com/v1/mediaItems?pageSize=50', {
        headers: { Authorization: 'Bearer ' + accessToken }
      });
      const data = await response.json();
      if (data.error) {
        setError({
          status: data.error.status || "UNKNOWN",
          message: data.error.message || "Onbekende fout van Google Photos API."
        });
      } else if (data.mediaItems && data.mediaItems.length > 0) {
        setPhotos(data.mediaItems);
      } else { 
        setError({status: "EMPTY", message: "Geen foto's gevonden in je bibliotheek."}); 
      }
    } catch (e: any) { 
      setError({status: "FETCH_ERROR", message: "Netwerkfout bij ophalen van foto's."}); 
    }
    finally { setLoading(false); }
  };

  useEffect(() => { fetchPhotos(); }, [accessToken]);
  useEffect(() => {
    if (photos.length === 0) return;
    const interval = setInterval(() => { setCurrentIndex(prev => (prev + 1) % photos.length); }, 10000);
    return () => clearInterval(interval);
  }, [photos]);

  if (loading) return ( <div className="bg-white rounded-[3rem] p-10 shadow-sm border border-gray-100 flex flex-col h-full items-center justify-center"><Loader2 className="w-12 h-12 text-blue-400 animate-spin" /><p className="mt-4 text-xs font-black text-gray-400 uppercase tracking-widest">Foto's laden...</p></div> );

  if (error) return (
    <div className="bg-white rounded-[3rem] p-10 shadow-sm border border-gray-100 flex flex-col h-full items-center justify-center text-center overflow-y-auto no-scrollbar">
      <div className="w-20 h-20 bg-rose-50 rounded-3xl flex items-center justify-center mb-6"><ShieldAlert size={40} className="text-rose-400" /></div>
      <h3 className="text-lg font-black text-gray-800 uppercase tracking-tight mb-2">Google Photos Toegangsfout</h3>

      <div className="w-full max-w-md bg-gray-50 p-6 rounded-3xl mb-8 border border-gray-100 text-left space-y-4">
         <div>
           <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Fout Status:</p>
           <p className="text-rose-600 text-sm font-bold">{error.status}</p>
         </div>
         <div>
           <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Gekregen Rechten (Scopes):</p>
           <p className="text-gray-500 text-[10px] font-mono break-all leading-tight bg-white p-2 border border-gray-100 rounded-lg">
             {grantedScopes || "Geen scopes gevonden"}
           </p>
           {!grantedScopes.includes("photoslibrary.readonly") && (
             <p className="text-[10px] text-rose-500 font-bold mt-1 uppercase">⚠️ Photos scope ontbreekt!</p>
           )}
         </div>
         <p className="text-gray-600 text-sm leading-relaxed">{error.message}</p>
      </div>

      <div className="flex flex-col gap-4 w-full max-w-xs">
        <button onClick={onForceLogout} className="px-8 py-5 bg-gray-900 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest hover:bg-black transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl shadow-gray-200">
          <LogOut size={16} /> Log uit & Herstart Scopes
        </button>
        <button onClick={fetchPhotos} className="text-[11px] font-black text-blue-500 uppercase tracking-widest flex items-center justify-center gap-2 hover:text-blue-600 transition-colors">
          <RefreshCw size={14} /> Opnieuw proberen laden
        </button>
      </div>

      <div className="mt-10 p-6 bg-blue-50 rounded-3xl text-left border border-blue-100">
        <p className="text-[11px] font-black text-blue-600 uppercase tracking-widest mb-2 flex items-center gap-2"><Info size={14} /> Belangrijke Tips:</p>
        <ul className="text-[11px] text-blue-800 space-y-2 leading-relaxed list-disc ml-4">
          <li><b>Test Users:</b> Ga naar Google Cloud Console &rarr; OAuth Consent Screen en voeg je e-mail toe aan de <b>"Test Users"</b> lijst.</li>
          <li><b>Checkbox:</b> Vink bij het inloggen expliciet het vakje <i>"View your Google Photos library"</i> aan.</li>
          <li><b>Refresh:</b> Gebruik de zwarte knop hierboven om een verse sessie te starten.</li>
        </ul>
      </div>
    </div>
  );

  return (
    <div className="bg-black rounded-[3rem] shadow-sm border border-gray-100 flex flex-col h-full overflow-hidden relative group">
      {photos.map((photo, idx) => ( <div key={photo.id} className={`absolute inset-0 transition-opacity duration-1000 ease-in-out ${idx === currentIndex ? 'opacity-100' : 'opacity-0'}`}><img src={photo.baseUrl + '=w1920-h1080'} alt="" className="w-full h-full object-cover" /></div> ))}
      <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-black/10" />
      <div className="absolute bottom-10 left-10 text-white flex flex-col gap-1"><span className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60">Google Photos</span><span className="text-xs font-bold truncate max-w-sm">{photos[currentIndex]?.filename}</span></div>
      <div className="absolute top-10 right-10 flex gap-4"><button onClick={fetchPhotos} className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white hover:bg-white/40 transition-colors"><RefreshCw size={18} /></button><div className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white"><ImageIcon size={20} /></div></div>
    </div>
  );
};

const Calendar = ({ accessToken, items, isLoading, onRefresh, isCollapsed, onToggleCollapse }: { accessToken: string | null; items: AgendaItem[]; isLoading: boolean; onRefresh: () => void; isCollapsed: boolean; onToggleCollapse: () => void; }) => {
  const weekDays = useMemo(() => Array.from({ length: 7 }, (_, i) => { const d = new Date(); d.setDate(d.getDate() + i); return d; }), []);

  const getEventsForDay = (date: Date) => {
    const startOfDay = new Date(date); startOfDay.setHours(0,0,0,0); 
    const endOfDay = new Date(date); endOfDay.setHours(23,59,59,999);

    return items.filter(item => { 
      const itemStart = new Date(item.start); 
      const itemEnd = new Date(item.end); 

      if (item.isAllDay) {
        const colDateStr = date.toLocaleDateString('en-CA'); 
        const evDateStr = itemStart.toLocaleDateString('en-CA');
        return colDateStr === evDateStr;
      }
      return (itemStart <= endOfDay && itemEnd >= startOfDay); 
    });
  };

  return (
    <div className={`bg-white rounded-[3rem] p-10 shadow-sm border border-gray-100 flex flex-col transition-all duration-500 overflow-hidden ${isCollapsed ? 'h-auto' : 'h-full'}`}>
      <div className="flex justify-between items-center shrink-0"><div className="flex items-center gap-6"><h2 className="text-4xl font-light text-gray-800 tracking-tight">Week Agenda</h2>{!isCollapsed && accessToken && !isLoading && ( <button onClick={onRefresh} className="flex items-center gap-3 px-4 py-2 bg-blue-50 text-[11px] text-blue-600 font-black rounded-full uppercase tracking-widest border border-blue-100 hover:bg-blue-100"><RefreshCw size={12} className={isLoading ? "animate-spin" : ""} /> Verversen</button> )}</div><div className="flex items-center gap-8"><div className="text-[11px] font-black text-gray-300 uppercase tracking-[0.4em]">Komende 7 dagen</div><button onClick={onToggleCollapse} className="w-12 h-12 flex items-center justify-center bg-gray-50 hover:bg-gray-100 text-gray-400 rounded-2xl transition-all active:scale-90">{isCollapsed ? <ChevronDown size={24} /> : <ChevronUp size={24} />}</button></div></div>
      {!isCollapsed && ( <div className="flex-1 overflow-hidden mt-10 animate-in fade-in">{!accessToken ? ( <div className="h-full flex flex-col items-center justify-center text-center space-y-8 px-10 opacity-40"><div className="w-24 h-24 bg-blue-50 rounded-[2.5rem] flex items-center justify-center mb-2"><CalendarIcon className="w-12 h-12 text-blue-300" /></div><p className="text-gray-500 text-xl font-medium max-w-sm">Synchroniseer met Google Agenda om je weekplanning te zien</p></div> ) : isLoading ? ( <div className="h-full flex flex-col items-center justify-center space-y-8"><Loader2 className="w-16 h-16 text-blue-400 animate-spin" /><p className="text-xs text-gray-400 font-black uppercase tracking-[0.4em] animate-pulse">Agenda ophalen...</p></div> ) : ( <div className="grid grid-cols-7 h-full gap-px bg-gray-100 border border-gray-100 rounded-[2.5rem] overflow-hidden">{weekDays.map((date, idx) => { const allEvents = getEventsForDay(date); const allDayItems = allEvents.filter(e => e.isAllDay); const timedItems = allEvents.filter(e => !e.isAllDay); const today = new Date().toDateString() === date.toDateString(); return ( <div key={idx} className={`bg-white flex flex-col min-w-0 ${today ? 'bg-blue-50/20' : ''}`}><div className={`p-6 text-center border-b border-gray-50 shrink-0 ${today ? 'bg-blue-500/5' : ''}`}><div className={`text-[11px] font-black tracking-widest ${today ? 'text-blue-600' : 'text-gray-400'}`}>{date.toLocaleDateString('nl-BE', { weekday: 'short' }).toUpperCase()}</div><div className={`text-3xl font-black mt-1 ${today ? 'text-blue-600' : 'text-gray-800'}`}>{date.getDate()}</div></div><div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar">

      {allDayItems.map(item => ( 
        <div 
          key={item.id + date.toISOString()} 
          onClick={() => window.open(item.htmlLink, '_blank')} 
          style={{ backgroundColor: item.color || '#9ca3af' }} 
          className="p-6 rounded-[2rem] cursor-pointer hover:brightness-95 active:scale-95 transition-all shadow-sm border border-black/5"
        >
          <span className="text-[20px] font-black leading-[1.15] block line-clamp-2 text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.3)]">
            {item.title}
          </span>
        </div> 
      ))} 

      {timedItems.map((item) => ( 
        <div key={item.id + date.toISOString()} onClick={() => window.open(item.htmlLink, '_blank')} className="group bg-gray-50/50 hover:bg-white p-6 rounded-[2rem] border border-transparent hover:border-gray-100 transition-all cursor-pointer">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: item.color || '#d1d5db' }} />
            <span className="text-xl font-black text-gray-900 leading-none">{item.time}</span>
          </div>
          <h4 className="text-2xl font-bold text-gray-800 leading-[1.2] group-hover:text-blue-600">{item.title}</h4>
        </div> 
      ))}

      </div></div> ); })}</div> )}</div> )}
    </div>
  );
};

