k text-gray-900">{d.high + '°'}</div><div className="text-xl font-bold text-gray-300 mt-1">{d.low + '°'}</div></div><span className="text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">{d.condition}</span></div> ))}</div></section></div> )}</div>
