                    </div>

                    <div className="flex-1 overflow-y-auto p-0 space-y-0.5 no-scrollbar">
                      {dayEvents.sort((a,b) => (a.isAllDay ? -1 : 1) - (b.isAllDay ? -1 : 1)).map(item => ( 
                        <div 
