      const data = await resp.json(); 
      if (data.items) { 
        const mapped = data.items.map((event: any) => { 
          const isAllDay = !event.start.dateTime; 
          const startRaw = event.start.dateTime || event.start.date; 
          // For all-day events, use noon (T12:00:00) to prevent flipping days when viewed in nearby timezones like UTC or Brussels
          const startDate = isAllDay ? new Date(startRaw + 'T12:00:00') : new Date(startRaw);
          const endDate = isAllDay ? new Date(event.end.date + 'T12:00:00') : new Date(event.end.dateTime);

          return { 
            id: event.id, 
            start: startDate, 
            end: endDate, 
            title: event.summary || '(Geen titel)', 
            color: GOOGLE_COLOR_MAP[event.colorId] || '#10b981', 
            isAllDay, 
            htmlLink: event.htmlLink 
