                              </span>
                            )}
                            <span className="text-[30px] font-bold leading-tight line-clamp-3 pl-1 pr-1">
                              {item.title}
                            </span>
                          </div>
                        </div> 
                      ))} 
                    </div>
                  </div> 
                ); 
              })}
            </div> 
          )}
        </div> 
      )}
    </div>
  );
};

