                          onClick={() => window.open(item.htmlLink, '_blank')} 
                          style={item.isAllDay ? { backgroundColor: item.color || '#9ca3af' } : {}} 
                          className={`w-full cursor-pointer hover:brightness-95 active:scale-[0.98] transition-all ${
