            displayTitle = displayTitle
              .replace(/\s*\d{1,2}[u:]\d{0,2}\s*-\s*\d{1,2}[u:]\d{0,2}/gi, '')
              .replace(/\s*\d{1,2}[u:]\d{2}/gi, '')
              .replace(/\s*\d{1,2}\s*u/gi, '')
              .trim();
          }

          return { 
            id: event.id, 
            start: startDate, 
            end: endDate, 
