        const updateResp = await fetch(`https://www.googleapis.com/upload/drive/v3/files/${fileId}?uploadType=media`, {
          method: 'PATCH',
          headers: { 
            'Authorization': 'Bearer ' + accessToken,
            'Content-Type': 'text/plain'
